-- Create procedure `exportar_Presupuestos_Tanteo_Recursos`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS exportar_Presupuestos_Tanteo_Recursos
  (
    IN iCodBase VARCHAR(255),
    IN iCodPresupuesto VARCHAR(255),
    IN iRevision INT,
    IN id_exports VARCHAR(255)
  )
  BEGIN
    DECLARE done INTEGER;
    DECLARE v_id INTEGER;
    DECLARE cur1 CURSOR FOR
      SELECT
              ptr.id
      FROM
              presupuestos_tanteo_recursos ptr
      WHERE
              ptr.codBase = iCodBase
              AND ptr.codPresupuesto = iCodPresupuesto
              AND ptr.revision = iRevision;
    DECLARE CONTINUE HANDLER FOR NOT FOUND
    SET done = TRUE;
    /* ------------ INICIO ---------- -- */
    SET done := FALSE;
    OPEN cur1;
    loop_cur1:
    LOOP
      FETCH cur1 INTO v_id;
      IF done
      THEN
        LEAVE loop_cur1;
      END IF;

      INSERT INTO presupuestos_tanteo_recursos_exports
            (
              codUnicoTanteo,
              codBase,
              codPresupuesto,
              revision,
              CodAPU,
              descripcion,
              idUnicoRecurso,
              Precio,
              CantidadUnidad,
              Rendimiento,
              Total,
              id_exports
            )
          SELECT
                  codUnicoTanteo,
                  codBase,
                  codPresupuesto,
                  revision,
                  CodAPU,
                  descripcion,
                  idUnicoRecurso,
                  Precio,
                  CantidadUnidad,
                  Rendimiento,
                  Total,
                  id_exports
          FROM
                  presupuestos_tanteo_recursos
          WHERE
                  id = v_id;

    END LOOP;
    CLOSE cur1;
  END
