--
-- Create function `DaCodAPUGenerico`
--
CREATE
DEFINER = 'root'@'localhost'
FUNCTION IF NOT EXISTS DaCodAPUGenerico
  (
    icodBase CHAR(50),
    icodAPU CHAR(50)
  )
RETURNS CHAR(15) CHARSET utf8mb4 COLLATE utf8mb4_general_ci
READS SQL DATA
  BEGIN
    DECLARE contador INT;
    DECLARE CodGenericoAPU CHAR(15);
    DECLARE codSubCategoria INT;
    DECLARE codRecurso INT;
    SELECT
            a.codCategoriaAPU,
            a.codRecursoAPU
            INTO codSubCategoria, codRecurso
    FROM
            apus a
    WHERE
            codBase = icodBase
            AND codAPU = icodAPU;
    SET CodGenericoAPU := '6';
    SET contador := 4 - (4 - LENGTH(
      CodSubCategoria));
    WHILE contador < 4 DO
      SET CodGenericoAPU := CONCAT(
        CodGenericoAPU,
        '0');
      SET contador := contador + 1;
    END WHILE;
    SET CodGenericoAPU := CONCAT(
      CodGenericoAPU,
      CodSubCategoria);
    SET contador := 5 - (5 - LENGTH(
      codRecurso));
    WHILE contador < 5 DO
      SET CodGenericoAPU := CONCAT(
        CodGenericoAPU,
        '0');
      SET contador := contador + 1;
    END WHILE;
    SET CodGenericoAPU := CONCAT(
      CodGenericoAPU,
      codRecurso);
    RETURN CodGenericoAPU;
  END
  $$

--
-- Create procedure `UpsertCabeceraAPU`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS UpsertCabeceraAPU
  (
    IN p_codBase VARCHAR(255),
    IN p_codCategoriaAPU VARCHAR(255),
    IN p_codRecursoAPU INT,
    IN p_CategoriaAPU VARCHAR(255),
    IN p_codAPU VARCHAR(255),
    IN p_codAPUAlternativo VARCHAR(255),
    IN p_Descripcion VARCHAR(255),
    IN p_Unidad VARCHAR(255),
    IN p_RendimientoTodoAnalisis VARCHAR(255),
    IN p_RendimientoTodoEscenario VARCHAR(255),
    IN p_CostoDirectoTotal DECIMAL(65, 10),
    IN p_CostoIndirectoTotal DECIMAL(65, 10),
    IN p_PorcentajeCostoIndirecto DECIMAL(65, 10),
    IN p_PrecioUnitarioTotal DECIMAL(65, 10),
    IN p_moneda VARCHAR(255),
    IN p_ultimaModificacion DATETIME,
    IN p_rendimientoHUnidad VARCHAR(255),
    IN p_nhCuadrillas VARCHAR(255),
    IN p_anidado VARCHAR(255),
    IN p_pendienteRevision VARCHAR(255)
  )
  BEGIN

    -- UPDATE si existe
    UPDATE
    apus
    SET
            codCategoriaAPU = p_codCategoriaAPU,
            CategoriaAPU = p_CategoriaAPU,
            descripcion = p_Descripcion,
            unidad = p_Unidad,
            codAPUAlternativo = p_codAPUAlternativo,
            RendimientoTodoAnalisis = p_RendimientoTodoAnalisis,
            RendimientoTodoEscenario = p_RendimientoTodoEscenario,
            CostoDirectoTotal = p_CostoDirectoTotal,
            CostoIndirectoTotal = p_CostoIndirectoTotal,
            PorcentajeCostoIndirecto = p_PorcentajeCostoIndirecto,
            PrecioUnitarioTotal = p_PrecioUnitarioTotal,
            moneda = p_moneda,
            ultimaModificacion = p_ultimaModificacion,
            rendimientoHUnidad = p_rendimientoHUnidad,
            nhCuadrillas = p_nhCuadrillas,
            anidado = p_anidado,
            pendienteRevision = p_pendienteRevision
    WHERE
      codBase = p_codBase
      AND codAPU = p_codAPU;

    -- Si no afectó filas, hacer INSERT
    IF ROW_COUNT() = 0
    THEN
      INSERT INTO apus
            (
              codBase,
              codCategoriaAPU,
              codRecursoAPU,
              CategoriaAPU,
              codAPU,
              codAPUAlternativo,
              descripcion,
              unidad,
              RendimientoTodoAnalisis,
              RendimientoTodoEscenario,
              CostoDirectoTotal,
              CostoIndirectoTotal,
              PorcentajeCostoIndirecto,
              PrecioUnitarioTotal,
              moneda,
              ultimaModificacion,
              rendimientoHUnidad,
              nhCuadrillas,
              anidado,
              pendienteRevision
            )
      VALUES
          (
            p_codBase, p_codCategoriaAPU, p_codRecursoAPU, p_CategoriaAPU, p_codAPU, p_codAPUAlternativo, p_Descripcion, p_Unidad, p_RendimientoTodoAnalisis, p_RendimientoTodoEscenario, p_CostoDirectoTotal, p_CostoIndirectoTotal, p_PorcentajeCostoIndirecto, p_PrecioUnitarioTotal, p_moneda, p_ultimaModificacion, p_rendimientoHUnidad, p_nhCuadrillas, p_anidado, p_pendienteRevision
          );
    END IF;

    -- Verificar conflicto de codRecursoAPU
    SET @conflict := (SELECT
                COUNT(*)
        FROM
                (   SELECT
                            1
                    FROM
                            apus
                    WHERE
                            codBase = p_codBase
                            AND codCategoriaAPU = p_codCategoriaAPU
                            AND codRecursoAPU = p_codRecursoAPU
                            AND codAPU <> p_codAPU
                    LIMIT 1) AS conflict_check);

    -- Si no hay conflicto, actualizar codRecursoAPU si cambió
    IF @conflict = 0
    THEN
      UPDATE
      apus
      SET
              codRecursoAPU = p_codRecursoAPU
      WHERE
        codBase = p_codBase
        AND codAPU = p_codAPU
        AND IFNULL(
          codRecursoAPU,
          0) <> IFNULL(
          p_codRecursoAPU,
          0);
    END IF;

  END
  $$

--
-- Create procedure `apus_upsert_cabecera`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS apus_upsert_cabecera
  (
    IN pCodBase VARCHAR(255),
    IN pCodAPU VARCHAR(255),

    IN pCodCategoriaAPU VARCHAR(255),
    IN pCodRecursoAPU INT,            -- puede venir NULL/0 para "auto"
    IN pCategoriaAPU VARCHAR(255),

    IN pDescripcion VARCHAR(255),
    IN pUnidad VARCHAR(255),
    IN pCodAPUAlternativo VARCHAR(255),

    IN pRendTodoAnalisis VARCHAR(255),
    IN pRendTodoEscenario VARCHAR(255),

    IN pCostoDirectoTotal DECIMAL(65, 10),
    IN pCostoIndirectoTotal DECIMAL(65, 10),
    IN pPctIndirecto DECIMAL(65, 10),
    IN pPrecioUnitarioTotal DECIMAL(65, 10),

    IN pMoneda VARCHAR(255),
    IN pRendimientoHUnidad VARCHAR(255),
    IN pNhCuadrillas VARCHAR(255),
    IN pAnidado VARCHAR(255),
    IN pPendienteRevision VARCHAR(255),

    OUT pCodRecursoAPUFinal INT             -- devuelve el codRecursoAPU que quedó
  )
  BEGIN
    DECLARE vExiste INT DEFAULT 0;
    DECLARE vOldCodRecursoAPU INT DEFAULT NULL;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      RESIGNAL;
    END;

    IF pCodBase IS NULL
      OR
      TRIM(pCodBase) = ''
    THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'codBase vacío';
    END IF;

    IF pCodAPU IS NULL
      OR
      TRIM(pCodAPU) = ''
    THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'codAPU vacío';
    END IF;

    IF pCodCategoriaAPU IS NULL
      OR
      TRIM(pCodCategoriaAPU) = ''
    THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'codCategoriaAPU vacío';
    END IF;

    START TRANSACTION;

    /* ¿Existe el APU? Bloquea fila si existe */
    SELECT
            COUNT(*),
            MAX(codRecursoAPU)
            INTO vExiste, vOldCodRecursoAPU
    FROM
            apus
    WHERE
            codBase = pCodBase
            AND CodAPU = pCodAPU
    FOR UPDATE;

    IF vExiste > 0
    THEN
      /* UPDATE */

      /* Si pidieron cambiar codRecursoAPU, valida que no choque */
      IF pCodRecursoAPU IS NOT NULL
        AND
        pCodRecursoAPU <> 0
        AND
        pCodRecursoAPU <> vOldCodRecursoAPU
      THEN
        IF EXISTS (SELECT
                      1
              FROM
                      apus a
              WHERE
                      a.codBase = pCodBase
                      AND a.codCategoriaAPU = pCodCategoriaAPU
                      AND a.codRecursoAPU = pCodRecursoAPU
                      AND a.CodAPU <> pCodAPU
              LIMIT 1)
        THEN
          SIGNAL SQLSTATE '45000'
          SET MESSAGE_TEXT = 'INTEGRIDAD: codRecursoAPU duplicado para codBase/codCategoriaAPU';
        END IF;

        SET pCodRecursoAPUFinal = pCodRecursoAPU;
      ELSE
        /* Mantener el actual */
        SET pCodRecursoAPUFinal = vOldCodRecursoAPU;
      END IF;

      UPDATE
      apus
      SET
              codCategoriaAPU = pCodCategoriaAPU,
              codRecursoAPU = pCodRecursoAPUFinal,
              CategoriaAPU = pCategoriaAPU,
              Descripcion = pDescripcion,
              Unidad = pUnidad,
              codAPUAlternativo = pCodAPUAlternativo,
              RendimientoTodoAnalisis = pRendTodoAnalisis,
              RendimientoTodoEscenario = pRendTodoEscenario,
              CostoDirectoTotal = pCostoDirectoTotal,
              CostoIndirectoTotal = pCostoIndirectoTotal,
              PorcentajeCostoIndirecto = pPctIndirecto,
              PrecioUnitarioTotal = pPrecioUnitarioTotal,
              moneda = pMoneda,
              ultimaModificacion = NOW(),
              rendimientoHUnidad = pRendimientoHUnidad,
              nhCuadrillas = pNhCuadrillas,
              anidado = pAnidado,
              pendienteRevision = pPendienteRevision
      WHERE
        codBase = pCodBase
        AND CodAPU = pCodAPU;

    ELSE
      /* INSERT */

      /* Si no viene codRecursoAPU, lo generamos como MAX+1 por base+categoria */
      IF pCodRecursoAPU IS NULL
        OR
        pCodRecursoAPU = 0
      THEN
        SELECT
                IFNULL(
                  MAX(CAST(codRecursoAPU AS UNSIGNED)),
                  0) + 1
                INTO pCodRecursoAPUFinal
        FROM
                apus
        WHERE
                codBase = pCodBase
                AND codCategoriaAPU = pCodCategoriaAPU
        FOR UPDATE;
      ELSE
        /* Si viene, validamos que no choque */
        IF EXISTS (SELECT
                      1
              FROM
                      apus a
              WHERE
                      a.codBase = pCodBase
                      AND a.codCategoriaAPU = pCodCategoriaAPU
                      AND a.codRecursoAPU = pCodRecursoAPU
              LIMIT 1)
        THEN
          SIGNAL SQLSTATE '45000'
          SET MESSAGE_TEXT = 'INTEGRIDAD: codRecursoAPU duplicado para codBase/codCategoriaAPU';
        END IF;

        SET pCodRecursoAPUFinal = pCodRecursoAPU;
      END IF;

      INSERT INTO apus
            (
              codBase,
              CodAPU,
              codCategoriaAPU,
              codRecursoAPU,
              CategoriaAPU,
              Descripcion,
              Unidad,
              codAPUAlternativo,
              RendimientoTodoAnalisis,
              RendimientoTodoEscenario,
              CostoDirectoTotal,
              CostoIndirectoTotal,
              PorcentajeCostoIndirecto,
              PrecioUnitarioTotal,
              moneda,
              FechaHoraCreacion,
              ultimaModificacion,
              pendienteRevision,
              rendimientoHUnidad,
              nhCuadrillas,
              anidado
            )
      VALUES
          (
            pCodBase, pCodAPU, pCodCategoriaAPU, pCodRecursoAPUFinal, pCategoriaAPU, pDescripcion, pUnidad, pCodAPUAlternativo, pRendTodoAnalisis, pRendTodoEscenario, pCostoDirectoTotal, pCostoIndirectoTotal, pPctIndirecto, pPrecioUnitarioTotal, pMoneda, NOW(), NOW(), pPendienteRevision, pRendimientoHUnidad, pNhCuadrillas, pAnidado
          );
    END IF;

    COMMIT;
  END
  $$

--
-- Create procedure `actualizarCategoriaAPU`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS actualizarCategoriaAPU
  (
    IN p_codAPU VARCHAR(255),
    IN p_codBase VARCHAR(255),
    IN p_codCategoriaAPUNueva VARCHAR(255)
  )
  BEGIN
    DECLARE v_codCategoriaActual VARCHAR(255);
    DECLARE v_codCategoriaBase INT;
    DECLARE v_codRecursoCompleto VARCHAR(255);
    DECLARE v_maxApu INT DEFAULT 0;
    DECLARE v_maxRecurso INT DEFAULT 0;
    DECLARE v_nuevoCodigo INT;
    DECLARE v_codCatAPU_num INT;
    DECLARE v_cnt INT DEFAULT 0;
    DECLARE v_maxLenCodRec INT;

    /* ===========================
       MANEJADOR DE ERRORES
       =========================== */
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Error en actualizarCategoriaAPU_strict_safe. Transacción cancelada.';
    END;

    START TRANSACTION;

    /* ===========================
       1. VALIDAR APU
       =========================== */
    SELECT
            codCategoriaAPU
            INTO v_codCategoriaActual
    FROM
            apus
    WHERE
            codBase = p_codBase
            AND CodAPU = p_codAPU
    FOR UPDATE;

    IF v_codCategoriaActual IS NULL
    THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'APU no encontrado';
    END IF;

    /* ===========================
       2. VALIDAR FORMATO CATEGORIA
       =========================== */
    IF p_codCategoriaAPUNueva IS NULL
      OR
      p_codCategoriaAPUNueva = ''
      OR
      p_codCategoriaAPUNueva REGEXP '^[0-9]+$' = 0
    THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'codCategoriaAPU inválido (no numérico)';
    END IF;

    /* ===========================
       3. SOLO SI CAMBIA CATEGORIA
       =========================== */
    IF v_codCategoriaActual <> p_codCategoriaAPUNueva
    THEN

      /* ===========================
         4. VALIDAR RECURSO DEL APU
         =========================== */
      SELECT
              COUNT(*)
              INTO v_cnt
      FROM
              recursos
      WHERE
              codBase = p_codBase
              AND Especificaciones = CONCAT(
                'APU: ',
                p_codAPU)
      FOR UPDATE;

      IF v_cnt = 0
      THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Recurso del APU no encontrado';
      END IF;

      IF v_cnt > 1
      THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Inconsistencia: múltiples recursos para el mismo APU';
      END IF;

      /* ===========================
         5. OBTENER codCategoriaBase
         =========================== */
      SELECT
              codCategoriaBase
              INTO v_codCategoriaBase
      FROM
              recursos
      WHERE
              codBase = p_codBase
              AND Especificaciones = CONCAT(
                'APU: ',
                p_codAPU)
      LIMIT 1
      FOR UPDATE;

      IF v_codCategoriaBase IS NULL
      THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'codCategoriaBase NULL en recurso del APU';
      END IF;

      /* ===========================
         6. LONGITUD CAMPO DESTINO
         =========================== */
      SELECT
              CHARACTER_MAXIMUM_LENGTH
              INTO v_maxLenCodRec
      FROM
              information_schema.columns
      WHERE
              table_schema = DATABASE()
              AND table_name = 'recursos'
              AND column_name = 'codRecursoCompleto';

      IF v_maxLenCodRec IS NULL
      THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'No se pudo determinar longitud de codRecursoCompleto';
      END IF;

      /* ===========================
         7. CALCULAR NUEVO CODIGO
         =========================== */
      SELECT
              IFNULL(
                MAX(codRecursoAPU),
                0)
              INTO v_maxApu
      FROM
              apus
      WHERE
              codBase = p_codBase
              AND codCategoriaAPU = p_codCategoriaAPUNueva
      FOR UPDATE;

      SELECT
              IFNULL(
                MAX(codRecurso),
                0)
              INTO v_maxRecurso
      FROM
              recursos
      WHERE
              codBase = p_codBase
              AND codCategoriaBase = v_codCategoriaBase
              AND codSubCategoria = p_codCategoriaAPUNueva
      FOR UPDATE;

      SET v_nuevoCodigo = GREATEST(
        v_maxApu,
        v_maxRecurso) + 1;
      SET v_codCatAPU_num = CAST(p_codCategoriaAPUNueva AS UNSIGNED);

      /* ===========================
         8. CONSTRUIR CODIGO COMPLETO
         =========================== */
      SET v_codRecursoCompleto = CONCAT(
        '6',
        LPAD(
          v_codCatAPU_num,
          4,
          '0'),
        LPAD(
          v_nuevoCodigo,
          5,
          '0'));

      IF LENGTH(
          v_codRecursoCompleto) > v_maxLenCodRec
      THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'codRecursoCompleto excede longitud del campo';
      END IF;

      IF EXISTS (SELECT
                    1
            FROM
                    recursos
            WHERE
                    codBase = p_codBase
                    AND codRecursoCompleto = v_codRecursoCompleto)
      THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'codRecursoCompleto duplicado';
      END IF;

      /* ===========================
         9. ACTUALIZAR APUS
         =========================== */
      UPDATE
      apus
      SET
              codCategoriaAPU = p_codCategoriaAPUNueva,
              codRecursoAPU = v_nuevoCodigo,
              ultimaModificacion = NOW()
      WHERE
        codBase = p_codBase
        AND CodAPU = p_codAPU;

      IF ROW_COUNT() <> 1
      THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Error actualizando APU';
      END IF;

      /* ===========================
         10. ACTUALIZAR RECURSO
         =========================== */
      UPDATE
      recursos
      SET
              codSubCategoria = p_codCategoriaAPUNueva,
              codRecurso = v_nuevoCodigo,
              codRecursoCompleto = v_codRecursoCompleto,
              ultimaModificacion = NOW()
      WHERE
        codBase = p_codBase
        AND codCategoriaBase = v_codCategoriaBase
        AND Especificaciones = CONCAT(
          'APU: ',
          p_codAPU);

      IF ROW_COUNT() <> 1
      THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Error actualizando recurso del APU';
      END IF;

    END IF;

    COMMIT;

  END
  $$

DELIMITER ;

