--
-- Create function `DaValorAPUconTanteoSinIndirectos`
--
CREATE
DEFINER = 'root'@'localhost'
FUNCTION IF NOT EXISTS DaValorAPUconTanteoSinIndirectos
  (
    icodbase VARCHAR(255) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    icodPresupuesto VARCHAR(255) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    iRevision VARCHAR(255) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    icodAPU VARCHAR(255) CHARSET utf8mb4 COLLATE utf8mb4_general_ci
  )
RETURNS DECIMAL(65, 10)
READS SQL DATA
  BEGIN
    DECLARE newValorConTanteo DECIMAL(65, 10);

    SELECT
            IF(t.id IS NULL, p.CostoDirectoTotal, t.CostoDirectoTotal)
            INTO newValorConTanteo
    FROM
            apus p
        LEFT JOIN
          presupuestos_tanteo_apus t
            ON (t.CodAPU = p.codAPU
                AND t.codBase = p.codBase
                AND t.codPresupuesto = icodPresupuesto
                AND t.revision = irevision)
    WHERE
            p.codBase = icodbase
            AND p.codAPU = icodAPU;

    RETURN newValorConTanteo;

  END
  $$

--
-- Create procedure `Tanteo_RestauraAPU`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS Tanteo_RestauraAPU
  (
    IN iCodBase VARCHAR(255),
    IN iCodPresupuesto VARCHAR(255),
    IN iRevision VARCHAR(255),
    IN iCodAPU VARCHAR(255)
  )
  BEGIN

    IF EXISTS (SELECT
                  1
          FROM
                  presupuestos_tanteo_recursos ptr
          WHERE
                  ptr.codBase = iCodBase
                  AND ptr.codPresupuesto = iCodPresupuesto
                  AND ptr.revision = iRevision)
    THEN
      IF EXISTS (SELECT
                    1
            FROM
                    presupuestos_tanteo_recursos_bkp ptrb
            WHERE
                    ptrb.codBase = iCodBase
                    AND ptrb.codPresupuesto = iCodPresupuesto
                    AND ptrb.revision = iRevision)
      THEN

        DELETE
        FROM
                presupuestos_tanteo_apus
        WHERE
                codBase = iCodBase
                AND codPresupuesto = iCodPresupuesto
                AND revision = iRevision
                AND CodAPU = iCodAPU;

        DELETE
        FROM
                presupuestos_tanteo_recursos
        WHERE
                codBase = iCodBase
                AND codPresupuesto = iCodPresupuesto
                AND revision = iRevision
                AND CodAPU = iCodAPU;

        INSERT INTO presupuestos_tanteo_apus
              (
                codUnicoTanteo,
                codBase,
                codPresupuesto,
                revision,
                CodAPU,
                CostoDirectoTotal,
                ultimaModificacion
              )
            SELECT
                    codUnicoTanteo,
                    codBase,
                    codPresupuesto,
                    revision,
                    CodAPU,
                    CostoDirectoTotal,
                    ultimaModificacion
            FROM
                    presupuestos_tanteo_apus_bkp
            WHERE
                    codBase = iCodBase
                    AND codPresupuesto = iCodPresupuesto
                    AND revision = iRevision
                    AND CodAPU = iCodAPU;

        INSERT INTO presupuestos_tanteo_recursos
              (
                codUnicoTanteo,
                codBase,
                codPresupuesto,
                revision,
                CodAPU,
                descripcion,
                idUnicoRecurso,
                Precio,
                CantidadUnidad,
                Rendimiento,
                Total
              )
            SELECT
                    codUnicoTanteo,
                    codBase,
                    codPresupuesto,
                    revision,
                    CodAPU,
                    descripcion,
                    idUnicoRecurso,
                    Precio,
                    CantidadUnidad,
                    Rendimiento,
                    Total
            FROM
                    presupuestos_tanteo_recursos
            WHERE
                    codBase = iCodBase
                    AND codPresupuesto = iCodPresupuesto
                    AND revision = iRevision
                    AND CodAPU = iCodAPU;
      END IF;
    END IF;
  END
  $$

--
-- Create procedure `Tanteo_BackupInicial`
