--
-- Create procedure `exportar_Presupuestos_Tanteo_Apus`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS exportar_Presupuestos_Tanteo_Apus
  (
    IN iCodBase VARCHAR(255),
    IN iCodPresupuesto VARCHAR(255),
    IN iRevision INT,
    IN id_exports VARCHAR(255)
  )
  BEGIN
    DECLARE done INTEGER;
    DECLARE v_id INTEGER;
    DECLARE cur1 CURSOR FOR
      SELECT
              pta.id
      FROM
              presupuestos_tanteo_apus pta
      WHERE
              pta.codBase = iCodBase
              AND pta.codPresupuesto = iCodPresupuesto
              AND pta.revision = iRevision;
    DECLARE CONTINUE HANDLER FOR NOT FOUND
    SET done = TRUE;
    /* ------------ INICIO ---------- -- */
    SET done := FALSE;
    OPEN cur1;
    loop_cur1:
    LOOP
      FETCH cur1 INTO v_id;
      IF done
      THEN
        LEAVE loop_cur1;
      END IF;

      INSERT INTO presupuestos_tanteo_apus_exports
            (
              codUnicoTanteo,
              codBase,
              codPresupuesto,
              revision,
              CodAPU,
              CostoDirectoTotal,
              ultimaModificacion,
              id_exports
            )
          SELECT
                  codUnicoTanteo,
                  codBase,
                  codPresupuesto,
                  revision,
                  CodAPU,
                  CostoDirectoTotal,
                  ultimaModificacion,
                  id_exports
          FROM
                  presupuestos_tanteo_apus
          WHERE
                  id = v_id;
    END LOOP;
    CLOSE cur1;
  END
  $$

DELIMITER ;

