DELIMITER $$

--
-- Create function `presupuestos_daValorAPU`
--
CREATE
DEFINER = 'root'@'localhost'
FUNCTION IF NOT EXISTS presupuestos_daValorAPU
  (
    icodBase VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    iCodAPU VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    icodPresupuesto VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    irevision VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    iPosGrid INTEGER
  )
RETURNS DECIMAL(65, 10)
READS SQL DATA
  BEGIN

    DECLARE newValor DECIMAL(65, 10);
    SELECT
            IF(t.id IS NULL, p.PUnitario * p.cantidad, t.CostoDirectoTotal * p.cantidad)
            INTO newValor
    FROM
            presupuestos_items_trabajo p
        LEFT JOIN
          presupuestos_tanteo_apus t
            ON (t.CodAPU = p.codAPU
                AND t.codBase = p.codBase
                AND t.codPresupuesto = p.codPresupuesto
                AND t.revision = p.revision)
    WHERE
            p.codBase = icodbase
            AND p.codAPU = icodAPU
            AND p.codPresupuesto = iCodPresupuesto
            AND p.revision = irevision
            AND p.posgrid = iPosGrid;

    RETURN newValor;
  END
  $$

--
-- Create function `DaValorEDT`
--
CREATE
DEFINER = 'root'@'localhost'
FUNCTION IF NOT EXISTS DaValorEDT
  (
    idEDT INTEGER,
    icodBase VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    icodPresupuesto VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    iRevision VARCHAR(10) CHARSET utf8mb4 COLLATE utf8mb4_general_ci
  )
RETURNS DECIMAL(65, 10)
READS SQL DATA
  BEGIN
    DECLARE resultado DECIMAL(65, 10);
    DECLARE ValorBusqueda CHAR(50);
    DECLARE nResultado DECIMAL(65, 10);

    SELECT
            pit.codEdt
            INTO valorBusqueda
    FROM
            presupuestos_items_trabajo pit
    WHERE
            pit.id = idEDT
            AND codBase = icodBase
            AND codPresupuesto = icodPresupuesto
            AND revision = iRevision;

    SET valorBusqueda := CONCAT(
      valorBusqueda,
      '.%');

    SELECT
            SUM(presupuestos_daValorAPU(
              pit1.codBase,
              pit1.codAPU,
              pit1.codPresupuesto,
              pit1.revision,
              pit1.posgrid))
            INTO nresultado
    FROM
            presupuestos_items_trabajo pit1
    WHERE
            codBase = icodBase
            AND codPresupuesto = icodPresupuesto
            AND revision = iRevision
            AND pit1.codItems LIKE valorbusqueda;
    IF nresultado IS NULL
    THEN
      SET Resultado := 0;
    ELSE
      SET Resultado := nResultado;
    END IF;

    RETURN Resultado;
  END
  $$

--
-- Create procedure `Presupuestos_DaTotalPresupuesto`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS Presupuestos_DaTotalPresupuesto
  (
    IN icodBase VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    IN icodPresupuesto VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    IN iRevision VARCHAR(10) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    OUT iTotalPresupuesto DECIMAL(65, 10),
    OUT rowscount INT,
    OUT nItemsPresupuesto INT,
    OUT nApus INT
  )
  proc:
    BEGIN

      DECLARE v_total DECIMAL(65, 10) DEFAULT 0;

      DECLARE EXIT HANDLER FOR SQLEXCEPTION
      BEGIN
        SET iTotalPresupuesto = 0;
        SET rowscount = 0;
        SET nItemsPresupuesto = 0;
        SET nApus = 0;
      END;

      /* ============================================================
         1. Conteos
         ============================================================ */

      SELECT
              COUNT(*)
              INTO rowscount
      FROM
              presupuestos_items_trabajo
      WHERE
              codBase = icodBase
              AND codPresupuesto = icodPresupuesto
              AND revision = iRevision;

      SELECT
              COUNT(*)
              INTO nItemsPresupuesto
      FROM
              presupuestos_items_trabajo
      WHERE
              codAPU IS NOT NULL
              AND codAPU <> ''
              AND codBase = icodBase
              AND codPresupuesto = icodPresupuesto
              AND revision = iRevision;

      SELECT
              COUNT(DISTINCT codAPU)
              INTO nApus
      FROM
              presupuestos_items_trabajo
      WHERE
              codAPU IS NOT NULL
              AND codAPU <> ''
              AND codBase = icodBase
              AND codPresupuesto = icodPresupuesto
              AND revision = iRevision;

      /* ============================================================
         2. Calcular total del presupuesto (sin cursor)
         ============================================================ */

      SELECT
              COALESCE(
                SUM(
                presupuestos_daValorAPU(
                  pit.codBase,
                  pit.codAPU,
                  pit.codPresupuesto,
                  pit.revision,
                  pit.posgrid)
                ),
                0)
              INTO v_total
      FROM
              presupuestos_items_trabajo pit
      WHERE
              pit.codAPU IS NOT NULL
              AND pit.codAPU <> ''
              AND pit.codBase = icodBase
              AND pit.codPresupuesto = icodPresupuesto
              AND pit.revision = iRevision;

      SET iTotalPresupuesto = COALESCE(
        v_total,
        0);

      /* ============================================================
         3. Actualizar filas EDT (sin cursor)
         ============================================================ */

      UPDATE
      presupuestos_items_trabajo pit
      SET
              pit.Ptotal = COALESCE(
                DaValorEDT(
                  pit.id,
                  icodBase,
                  icodPresupuesto,
                  iRevision),
                0),
              pit.cantidad = 0,
              pit.PUnitario = 0
      WHERE
        ( pit.codAPU IS NULL
          OR pit.codAPU = '')
        AND pit.codBase = icodBase
        AND pit.codPresupuesto = icodPresupuesto
        AND pit.revision = iRevision;

    END
    $$

--
-- Create function `ExisteEnEDT`
--
CREATE
DEFINER = 'root'@'localhost'
FUNCTION IF NOT EXISTS ExisteEnEDT
  (
    iCodBase VARCHAR(255),
    iCodPresupuesto VARCHAR(255),
    iRevision VARCHAR(255),
    iCodUnicoItems VARCHAR(255)
  )
RETURNS INT(11)
READS SQL DATA
  BEGIN
    DECLARE ExisteEdt INTEGER;
    SET ExisteEdt := 0;
    SELECT
            1
            INTO ExisteEdt
    FROM
            presupuestos_items_trabajo pit
    WHERE
            pit.codBase = iCodBase
            AND pit.codPresupuesto = iCodPresupuesto
            AND pit.revision = iRevision
            AND pit.codUnicoItems = iCodUnicoItems;
    RETURN ExisteEdt;
  END
  $$

--
-- Create procedure `Presupuestos_BorrarItem`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS Presupuestos_BorrarItem
  (
    IN cPosGrid INT,
    IN icodBase VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    IN icodPresupuesto VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    IN iRevision VARCHAR(10) CHARSET utf8mb4 COLLATE utf8mb4_general_ci
  )
  BEGIN
    DELETE
    FROM
            presupuestos_items_trabajo pit
    WHERE
            pit.posgrid = cPosGrid
            AND pit.codBase = icodBase
            AND pit.codPresupuesto = icodPresupuesto
            AND pit.revision = iRevision;
  END
  $$

--
-- Create procedure `Presupuestos_apusRepetido`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS Presupuestos_apusRepetido
  (
    IN iCodAPU VARCHAR(50),
    IN iCodBase VARCHAR(50),
    IN iCodPresupuesto VARCHAR(255),
    IN iRevision VARCHAR(255),
    IN cPosGrid INT
  )
READS SQL DATA
  BEGIN

    DECLARE ultCodItems VARCHAR(100) DEFAULT '';
    DECLARE posDot INT DEFAULT 0;
    DECLARE resultado INT DEFAULT 0;

    /* 1️⃣ Obtener codItems base */
    SELECT
            COALESCE(
              NULLIF(
                pit.codItems,
                ''),
              CONCAT(
                pit.codEdt,
                '.1'))
            INTO ultCodItems
    FROM
            presupuestos_items_trabajo pit
    WHERE
            pit.codBase = iCodBase
            AND pit.codPresupuesto = iCodPresupuesto
            AND pit.revision = iRevision
            AND pit.posgrid = cPosGrid
    LIMIT 1;

    IF ultCodItems IS NOT NULL
      AND
      ultCodItems <> ''
    THEN

      /* 2️⃣ Calcular patrón jerárquico */
      SET posDot = LOCATE(
        '.',
        REVERSE(
          ultCodItems));

      IF posDot > 0
      THEN
        SET ultCodItems = LEFT(
          ultCodItems,
          LENGTH(
            ultCodItems) - posDot + 1);
        SET ultCodItems = CONCAT(
          ultCodItems,
          '%');
      ELSE
        SET ultCodItems = CONCAT(
          ultCodItems,
          '.%');
      END IF;

      /* 3️⃣ Verificar repetición */
      IF EXISTS (SELECT
                    1
            FROM
                    presupuestos_items_trabajo pit
            WHERE
                    pit.codBase = iCodBase
                    AND pit.codPresupuesto = iCodPresupuesto
                    AND pit.revision = iRevision
                    AND pit.codAPU = iCodAPU
                    AND pit.codItems LIKE ultCodItems
            LIMIT 1)
      THEN
        SET resultado = 1;
      END IF;

    END IF;

    /* 4️⃣ DEVOLVER RESULTADO */
    SELECT
            resultado AS result;

  END
  $$

--
-- Create procedure `Presupuestos_addItem`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS Presupuestos_addItem
  (
    IN icodBase VARCHAR(50),
    IN icodPresupuesto VARCHAR(50),
    IN iRevision VARCHAR(50),
    IN iCodAPU VARCHAR(50),
    IN iCodAPUGenerico VARCHAR(50),
    IN cantidad DECIMAL(18, 6),
    IN idAnterior INT,
    IN newCodItems VARCHAR(50),
    IN cPosgrid INT
  )
MODIFIES SQL DATA
  BEGIN

    DECLARE vDescripcion VARCHAR(255);
    DECLARE vUnidad VARCHAR(50);
    DECLARE vRendimiento VARCHAR(50);
    DECLARE vNhCuadrillas VARCHAR(50);
    DECLARE vAnidado VARCHAR(50);
    DECLARE vPrecio DECIMAL(18, 6);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      RESIGNAL;
    END;

    START TRANSACTION;

    /* Validación básica */
    IF icodBase IS NULL
      OR
      iCodAPU IS NULL
      OR
      newCodItems IS NULL
    THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Parametros invalidos en Presupuestos_addItem';
    END IF;

    /* Obtener datos del APU */
    SELECT
            a.Descripcion,
            IFNULL(
              a.CostoDirectoTotal,
              0),
            a.Unidad,
            a.rendimientoHUnidad,
            a.nhCuadrillas,
            a.anidado
            INTO vDescripcion,
            vPrecio,
            vUnidad,
            vRendimiento,
            vNhCuadrillas,
            vAnidado
    FROM
            apus a
    WHERE
            a.codBase = icodBase
            AND a.CodAPU = iCodAPU
    LIMIT 1;

    IF vDescripcion IS NULL
    THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'APU no encontrado';
    END IF;

    /* Insert */
    INSERT INTO presupuestos_items_trabajo
          (
            codBase,
            codPresupuesto,
            revision,
            codEdt,
            codItems,
            codUnicoItems,
            codAPUGenerico,
            codAPU,
            descripcion,
            unidad,
            cantidad,
            PUnitario,
            Ptotal,
            notas,
            rendimientoHUnidad,
            nhCuadrillas,
            anidado,
            posgrid
          )
    VALUES
        (
          icodBase, icodPresupuesto, iRevision, NULL, newCodItems, UUID(), iCodAPUGenerico, iCodAPU, vDescripcion, vUnidad, cantidad, vPrecio, vPrecio * cantidad, 0, vRendimiento, vNhCuadrillas, vAnidado, cPosgrid
        );

    COMMIT;

  END
  $$

--
-- Create procedure `Presupuestos_actualizaCantidadAPU`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS Presupuestos_actualizaCantidadAPU
  (
    IN icodBase VARCHAR(255),
    IN iCodPresupuesto VARCHAR(255),
    IN iRevision VARCHAR(255),
    IN V_id INT,
    IN iCantidad DECIMAL(60, 10)
  )
  BEGIN
    DECLARE PrecioTrabajo DECIMAL(60, 10);
    SELECT
            IF(pta.CodAPU IS NULL, pit.Ptotal, pta.PrecioUnitarioTotal)
            INTO PrecioTrabajo
    FROM
            presupuestos_items_trabajo pit
        LEFT JOIN
          presupuestos_tanteo_apus pta
            ON (pta.codBase = pit.codBase
                AND pta.codPresupuesto = pit.codPresupuesto
                AND pta.revision = pit.revision
                AND pta.CodAPU = pit.codAPU)
    WHERE
            pit.codBase = icodBase
            AND pit.codPresupuesto = iCodPresupuesto
            AND pit.revision = iRevision
            AND pit.id = V_id;

    UPDATE
    presupuestos_items_trabajo pit
    SET
            pit.cantidad = iCantidad,
            pit.Ptotal := PrecioTrabajo
    WHERE
      pit.codBase = icodBase
      AND pit.codPresupuesto = iCodPresupuesto
      AND pit.revision = iRevision
      AND pit.id = V_id;
  END
  $$

--
-- Create procedure `daPosgridFinEdt`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS daPosgridFinEdt
  (
    IN iCodBase VARCHAR(255),
    IN iCodPresupuesto VARCHAR(255),
    IN iRevision VARCHAR(255),
    IN iOldPosgrid INT
  )
READS SQL DATA
  BEGIN

    DECLARE v_nextPos INT;
    DECLARE v_result INT;

    SET v_result = iOldPosgrid;

    SELECT
            MIN(pit.posgrid)
            INTO v_nextPos
    FROM
            presupuestos_items_trabajo pit
    WHERE
            pit.codBase = iCodBase
            AND pit.codPresupuesto = iCodPresupuesto
            AND pit.revision = iRevision
            AND pit.posgrid > iOldPosgrid
            AND (   pit.codAPU IS NULL
                    OR pit.codAPU = '');

    IF v_nextPos IS NOT NULL
    THEN
      SET v_result = v_nextPos - 1;
    ELSE
      SELECT
              IFNULL(
                MAX(posgrid),
                iOldPosgrid)
              INTO v_result
      FROM
              presupuestos_items_trabajo pit
      WHERE
              pit.codBase = iCodBase
              AND pit.codPresupuesto = iCodPresupuesto
              AND pit.revision = iRevision;
    END IF;

    SELECT
            v_result AS oNewPosGrid;

  END
  $$

DELIMITER ;

