--
-- Create procedure `guardarItemsProyecto`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS guardarItemsProyecto
  (
    IN iCodBase VARCHAR(255),
    IN iCodPresupuesto VARCHAR(255),
    IN iRevision VARCHAR(255)
  )
  BEGIN
    DECLARE v_realizarOperacion INTEGER;

    SELECT
            COUNT(pit.id)
            INTO v_realizarOperacion
    FROM
            presupuestos_items_trabajo pit
    WHERE
            pit.codBase = iCodBase
            AND pit.codPresupuesto = iCodPresupuesto
            AND pit.revision = iRevision;

    IF v_realizarOperacion > 0
    THEN
      DELETE
      FROM
              presupuestos_items pi
      WHERE
              pi.codBase = iCodBase
              AND pi.codPresupuesto = iCodPresupuesto
              AND pi.revision = iRevision;

      INSERT INTO presupuestos_items
            (
              codBase,
              codPresupuesto,
              revision,
              codEdt,
              codItems,
              codUnicoItems,
              codAPUGenerico,
              codAPU,
              descripcion,
              unidad,
              cantidad,
              PUnitario,
              Ptotal,
              notas,
              rendimientoHUnidad,
              nhCuadrillas,
              anidado,
              posgrid
            )
          SELECT
                  icodBase,
                  icodPresupuesto,
                  irevision,
                  pit.codEdt,
                  pit.codItems,
                  pit.codUnicoItems,
                  pit.codAPUGenerico,
                  pit.codAPU,
                  pit.descripcion,
                  pit.unidad,
                  pit.cantidad,
                  pit.PUnitario,
                  pit.Ptotal,
                  pit.notas,
                  pit.rendimientoHUnidad,
                  pit.nhCuadrillas,
                  pit.anidado,
                  pit.posgrid
          FROM
                  presupuestos_items_trabajo pit
          WHERE
                  pit.codBase = iCodBase
                  AND pit.codPresupuesto = iCodPresupuesto
                  AND pit.revision = iRevision
          ORDER BY
                  pit.posgrid;
    END IF;

  END
  $$

--
-- Create procedure `exportar_Presupuestos_items`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS exportar_Presupuestos_items
  (
    IN iCodBase VARCHAR(255),
    IN iCodPresupuesto VARCHAR(255),
    IN iRevision INT,
    IN id_exports VARCHAR(255)
  )
  BEGIN
    DECLARE done INTEGER;
    DECLARE v_id INTEGER;
    DECLARE cur1 CURSOR FOR
      SELECT
              pi.id
      FROM
              presupuestos_items pi
      WHERE
              pi.codBase = iCodBase
              AND pi.codPresupuesto = iCodPresupuesto
              AND pi.revision = iRevision;
    DECLARE CONTINUE HANDLER FOR NOT FOUND
    SET done = TRUE;
    /* ------------ INICIO ---------- -- */
    SET done := FALSE;
    OPEN cur1;
    loop_cur1:
    LOOP
      FETCH cur1 INTO v_id;
      IF done
      THEN
        LEAVE loop_cur1;
      END IF;
      INSERT INTO presupuestos_items_exports
            (
              codBase,
              codPresupuesto,
              revision,
              codEdt,
              codItems,
              codUnicoItems,
              codAPUGenerico,
              codAPU,
              descripcion,
              unidad,
              cantidad,
              PUnitario,
              Ptotal,
              notas,
              rendimientoHUnidad,
              nhCuadrillas,
              anidado,
              posgrid,
              id_exports
            )
          SELECT
                  codBase,
                  codPresupuesto,
                  revision,
                  codEdt,
                  codItems,
                  codUnicoItems,
                  codAPUGenerico,
                  codAPU,
                  descripcion,
                  unidad,
                  cantidad,
                  PUnitario,
                  Ptotal,
                  notas,
                  rendimientoHUnidad,
                  nhCuadrillas,
                  anidado,
                  posgrid,
                  id_exports
          FROM
                  presupuestos_items
          WHERE
                  id = v_id;
    END LOOP;
    CLOSE cur1;
  END
  $$

