DELIMITER $$

--
-- Create procedure `Tanteo_Inicio`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS Tanteo_Inicio
  (
    IN iCodBase VARCHAR(255),
    IN iCodPresupuesto VARCHAR(255),
    IN iRevision VARCHAR(255),
    IN iCodAPU VARCHAR(255)
  )
  BEGIN
    DECLARE done INTEGER;
    DECLARE v_cursor INTEGER;
    DECLARE cur CURSOR FOR
      SELECT
              ai.id
      FROM
              apus_items ai
      WHERE
              ai.codBase = icodBase
              AND ai.codAPU = icodAPU;
    DECLARE CONTINUE HANDLER FOR NOT FOUND
    SET done = TRUE;

    /* --- INICIO --- */
    SET done := FALSE;
    OPEN cur;
    loop_apus:
    LOOP
      FETCH cur INTO v_cursor;
      IF done
      THEN
        LEAVE loop_apus;
      END IF;


      INSERT INTO presupuestos_tanteo_recursos_bkp
            (
              codBase,
              codPresupuesto,
              revision,
              CodAPU,
              descripcion,
              idUnicoRecurso,
              Precio,
              CantidadUnidad,
              Rendimiento,
              Total
            )
          SELECT
                  t.codBase,
                  iCodPresupuesto,
                  iRevision,
                  t.CodAPU,
                  t.Descripcion,
                  t.idUnicoRecurso,
                  t.Precio,
                  t.CantidadUnidad,
                  t.Rendimiento,
                  t.Total
          FROM
                  apus_items t
          WHERE
                  t.id = v_cursor;
    END LOOP;
    CLOSE cur;

  END
  $$

--
-- Create procedure `recalcular_apu`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS recalcular_apu
  (
    IN p_codBase VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
    IN p_codAPU VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci
  )
  BEGIN
    DECLARE v_total DECIMAL(65, 10) DEFAULT 0;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      SET @apu_en_recalculo = NULL;
      RESIGNAL;
    END;

    /* ==========================
       Bloqueo anti-recursión
       ========================== */
    SET @apu_en_recalculo = 1;

    /* ==========================
       Recalcular totales items
       ========================== */
    UPDATE
    apus_items
    SET
            Total =
            IFNULL(
              Precio,
              0)
            * IFNULL(
              CantidadUnidad,
              0)
            * IFNULL(
              Rendimiento,
              1)
    WHERE
      codBase COLLATE utf8mb4_general_ci = p_codBase
      AND CodAPU COLLATE utf8mb4_general_ci = p_codAPU;

    /* ==========================
       Sumar total del APU
       ========================== */
    SELECT
            IFNULL(
              SUM(Total),
              0)
            INTO v_total
    FROM
            apus_items
    WHERE
            codBase COLLATE utf8mb4_general_ci = p_codBase
            AND CodAPU COLLATE utf8mb4_general_ci = p_codAPU;

    /* ==========================
       Actualizar cabecera
       ========================== */
    UPDATE
    apus
    SET
            CostoDirectoTotal = v_total,
            PrecioUnitarioTotal = v_total,
            ultimaModificacion = NOW()
    WHERE
      codBase COLLATE utf8mb4_general_ci = p_codBase
      AND CodAPU COLLATE utf8mb4_general_ci = p_codAPU;

    /* ==========================
       Liberar bloqueo
       ========================== */
    SET @apu_en_recalculo = NULL;

  END
  $$

--
-- Create procedure `calcular_ValoresApusTanteo`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS calcular_ValoresApusTanteo
  (
    IN icodBase VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    IN icodPresupuesto VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    IN iCodAPU VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    IN iRevision VARCHAR(10) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    OUT iTotal DECIMAL(65, 10)
  )
  BEGIN
    DECLARE TotalItem DECIMAL(65, 10);

    /* Inicio -- */
    /* Borrar linea Anterior Tanteo APUS         */
    DELETE
    FROM
            presupuestos_tanteo_apus t
    WHERE
            t.CodAPU = iCodAPU
            AND t.codBase = icodBase
            AND t.codPresupuesto = icodPresupuesto
            AND t.revision = iRevision;

    /* Calcular Valor APU         */
    SELECT
            IF(tanteo.CodAPU IS NULL, SUM(item.Total), SUM(tanteo.Total)
            )
            INTO TotalItem
    FROM
            apus_items item
        LEFT JOIN
          presupuestos_tanteo_recursos tanteo
            ON (
                tanteo.CodAPU = item.CodAPU
                AND tanteo.codBase = item.codBase
                AND tanteo.codPresupuesto = icodPresupuesto
                AND tanteo.revision = iRevision
                AND tanteo.idUnicoRecurso = item.idUnicoRecurso
              )
    WHERE
            item.CodAPU = icodAPU
            AND item.codBase = iCodBase;

    /* Realizar Inserccion */
    INSERT presupuestos_tanteo_apus
          (
            codBase,
            codPresupuesto,
            Revision,
            CodAPU,
            CostoDirectoTotal,
            ultimaModificacion
          )
    VALUES
        (
          iCodBase, iCodPresupuesto, iRevision, iCodAPU, TotalItem, SYSDATE()
        );

    SET iTotal = TotalItem;
  END
  $$

--
-- Create procedure `tanteo_guardarItems`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS tanteo_guardarItems
  (
    IN iCodBase VARCHAR(255),
    IN iCodPresupuesto VARCHAR(255),
    IN iRevision VARCHAR(255),
    IN iCodAPU VARCHAR(255),
    IN newCantidad DECIMAL(65, 10),
    IN newRendimiento DECIMAL(65, 10),
    IN iIDUnicoItem VARCHAR(255)
  )
  BEGIN
    DECLARE var_id INTEGER;
    DECLARE descripcion CHAR(255);
    DECLARE idUnicoRecurso CHAR(50);
    DECLARE precio DECIMAL(65, 10);
    DECLARE cantidadUnidad DECIMAL(65, 10);
    DECLARE rendimiento DECIMAL(65, 10);
    DECLARE total DECIMAL(65, 10);
    DECLARE newTotal DECIMAL(65, 10);
    DECLARE done INTEGER;
    DECLARE tanteoInicial INTEGER;
    DECLARE cursor1 CURSOR FOR
      SELECT
              id
      FROM
              apus_items
      WHERE
              codBase = icodbase
              AND CodAPU = iCodAPU;
    DECLARE CONTINUE HANDLER FOR NOT FOUND
    SET done = TRUE;
    /* INICIO -- */
    SET done := FALSE;
    SET tanteoInicial := 0;

    /* Comprobar si exite tanteo guardado */
    IF NOT EXISTS (SELECT
                  1
          FROM
                  presupuestos_tanteo_recursos ptr
          WHERE
                  ptr.codBase = iCodBase
                  AND ptr.codPresupuesto = iCodPresupuesto
                  AND ptr.revision = iRevision
                  AND ptr.CodAPU = iCodAPU)
    THEN
      OPEN cursor1;
      /* loop para crear las lineas de tanteos iniciales sin valores modificados */
      loop_cursor1:
      LOOP
        FETCH cursor1 INTO var_id;
        IF done
        THEN
          LEAVE loop_cursor1;
        END IF;
        SELECT
                apu.idUnicoRecurso,
                apu.Descripcion,
                apu.Precio,
                apu.CantidadUnidad,
                apu.Rendimiento,
                apu.Total
                INTO idUnicoRecurso, descripcion, precio, cantidadUnidad, rendimiento, total
        FROM
                apus_items apu
        WHERE
                id = var_id;
        INSERT INTO presupuestos_tanteo_recursos
              (
                codBase,
                codPresupuesto,
                revision,
                CodAPU,
                descripcion,
                idUnicoRecurso,
                Precio,
                CantidadUnidad,
                Rendimiento,
                Total
              )
        VALUES
            (
              iCodBase, iCodPresupuesto, iRevision, iCodAPU, descripcion, idUnicoRecurso, precio, cantidadUnidad, Rendimiento, total
            );
      END LOOP;
      CLOSE cursor1;
      SET tanteoInicial := 1;
    END IF;
    /* Cojo valor precio por defecto de la linea a cambiar */
    SELECT
            ai.Precio
            INTO precio
    FROM
            apus_items ai
    WHERE
            ai.codBase = icodBase
            AND ai.CodAPU = iCodAPU
            AND ai.idUnicoRecurso = iIDUnicoItem;
    /* modifico la linea correspondiente del tanteo con los valores nuevo calculando automaticamente el valor total */
    SET newTotal := precio * newRendimiento;
    SET newTotal := newTotal * newCantidad;

    UPDATE
    presupuestos_tanteo_recursos ptr1
    SET
            ptr1.Rendimiento = newRendimiento,
            ptr1.CantidadUnidad = newCantidad,
            ptr1.total = newTotal
    WHERE
      ptr1.codBase = icodBase
      AND ptr1.codPresupuesto = iCodPresupuesto
      AND ptr1.revision = irevision
      AND ptr1.CodAPU = iCodAPU
      AND ptr1.idUnicoRecurso = iIDUnicoItem;
    IF tanteoInicial = 1
    THEN
      CALL Tanteo_Inicio(
        iCodBase,
        iCodPresupuesto,
        iRevision,
        iCodAPU);
    END IF;
    CALL calcular_ValoresApusTanteo(
      iCodBase,
      iCodPresupuesto,
      iCodAPU,
      iRevision,
      total);
  END
  $$

--
-- Create procedure `CrearLineasTanteoAnidado`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS CrearLineasTanteoAnidado
  (
    IN icodBase VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    IN icodPresupuesto VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    IN iCodAPU VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    IN iRevision VARCHAR(10) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    IN iCodAPUAnidado VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    IN iValorRecursoAnidado DECIMAL(65, 10)
  )
  BEGIN

    DECLARE anidado VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE idUnicoRecursoAnidado VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE estaTanteado VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE PrecioTMP DECIMAL(65, 10);
    DECLARE VDummy DECIMAL(65, 10);

    /* Definicion de modo  */
    SET sql_mode = (SELECT
                REPLACE(
                  @@sql_mode,
                  'ONLY_FULL_GROUP_BY',
                  ''));

    SET idUnicoRecursoAnidado = CONCAT(
      'APU: ',
      iCodAPUAnidado);

    /* Comprueba si esta anidado   */
    SELECT
            ap.CodAPU
            INTO anidado
    FROM
            apus_items ap
    WHERE
            ap.CodAPU = icodAPU
            AND ap.codBase = iCodBase
            AND ap.idUnicoRecurso = idUnicoRecursoAnidado;

    /* Comprueba si esta tanteado */
    SELECT
            t1.CodAPU
            INTO estaTanteado
    FROM
            presupuestos_tanteo_recursos t1
    WHERE
            t1.codBase = icodBase
            AND t1.codPresupuesto = icodPresupuesto
            AND t1.Revision = iRevision
            AND t1.CodAPU = icodAPU
    LIMIT 1;

    /*  Rutina Principal de Calculo */
    IF (anidado IS NOT NULL)  /* Esta anidado */
    THEN
      BEGIN
        IF (estaTanteado IS NULL)
        THEN /* No esta Tanteado Insertar Lineas */
          BEGIN
            INSERT INTO presupuestos_tanteo_recursos
                  (
                    codBase,
                    codPresupuesto,
                    Revision,
                    CodAPU,
                    Descripcion,
                    idUnicoRecurso,
                    Precio,
                    CantidadUnidad,
                    Rendimiento,
                    Total
                  )

                SELECT
                        ap0.codBase,
                        icodPresupuesto,
                        iRevision,
                        ap0.CodAPU,
                        ap0.Descripcion,
                        ap0.idUnicoRecurso,
                        IF(
                        ap0.idUnicoRecurso = idUnicoRecursoAnidado,
                        iValorRecursoAnidado,
                        ap0.precio
                        ),
                        ap0.CantidadUnidad,
                        ap0.Rendimiento,
                        IF(
                        ap0.idUnicoRecurso = idUnicoRecursoAnidado,
                        ivalorRecursoAnidado * ap0.Rendimiento * ap0.CantidadUnidad,
                        ap0.Precio * ap0.Rendimiento * ap0.CantidadUnidad
                        )
                FROM
                        apus_items ap0
                WHERE
                        ap0.codBase = icodBase
                        AND ap0.CodAPU = iCodAPU;
          END;
        ELSE   /* Esta Tanteado Actualizar Lineas */
          BEGIN
            UPDATE
            presupuestos_tanteo_recursos tr1
            SET
                    tr1.Precio = iValorRecursoAnidado,
                    tr1.Total = tr1.Precio * tr1.CantidadUnidad * tr1.Rendimiento
            WHERE
              tr1.CodAPU = icodAPU
              AND tr1.codPresupuesto = icodPresupuesto
              AND tr1.revision = iRevision
              AND tr1.codBase = iCodBase
              AND tr1.idUnicoRecurso = idUnicoRecursoAnidado;
          END;
        END IF; /* Fin de estaTanteado */
      END;
    CALL calcular_ValoresApusTanteo(
      iCodBase,
      iCodPresupuesto,
      iCodAPU,
      iRevision,
      vDummy);
    END IF;  /* Fin de esta Anidado */
  END
  $$

--
-- Create procedure `borrar_apu_si_no_usado`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS borrar_apu_si_no_usado
  (
    IN pCodBase VARCHAR(255),
    IN pCodAPU VARCHAR(255),
    OUT oResultado VARCHAR(20),
    OUT oDetalle VARCHAR(255)
  )
  proc:
    BEGIN
      DECLARE vExiste INT DEFAULT 0;
      DECLARE vTienePadres INT DEFAULT 0;
      DECLARE vUsadoPresupuesto INT DEFAULT 0;
      DECLARE vUsadoTanteoRecursos INT DEFAULT 0;
      DECLARE vTmp INT DEFAULT 0;

      DECLARE EXIT HANDLER FOR SQLEXCEPTION
      BEGIN
        GET DIAGNOSTICS CONDITION 1 @sqlstate = RETURNED_SQLSTATE,
        @errno = MYSQL_ERRNO,
        @msg = MESSAGE_TEXT;
        ROLLBACK;
        SET oResultado = 'ERROR';
        SET oDetalle = CONCAT(
          'SQLSTATE=',
          @sqlstate,
          ' ERRNO=',
          @errno,
          ' MSG=',
          @msg);
      END;

      SET oResultado = 'ERROR';
      SET oDetalle = '';

      /* 1) Existe */
      SELECT
              COUNT(*)
              INTO vExiste
      FROM
              apus
      WHERE
              codBase = pCodBase
              AND CodAPU = pCodAPU;

      IF vExiste = 0
      THEN
        SET oResultado = 'ERROR';
        SET oDetalle = 'APU_NO_EXISTE_EN_CODBASE';
        LEAVE proc;
      END IF;

      /* 2) Cadena ascendente */
      DROP TEMPORARY TABLE IF EXISTS tmp_apu_chain;
      CREATE TEMPORARY TABLE tmp_apu_chain
        (
          CodAPU VARCHAR(255) NOT NULL,
          depth  INT          NOT NULL,
          PRIMARY KEY (CodAPU)
        ) ENGINE = MEMORY;

      INSERT INTO tmp_apu_chain
            (
              CodAPU,
              depth
            )
          WITH RECURSIVE chain
          AS (   SELECT
                         pCodAPU AS CodAPU,
                         0 AS depth
                 UNION ALL
                 SELECT
                         ai.CodAPU,
                         c.depth + 1
                 FROM
                         chain c
                     JOIN
                       recursos r
                           ON r.codBase = pCodBase
                           AND r.Especificaciones = CONCAT(
                             'APU: ',
                             c.CodAPU)
                     JOIN
                       apus_items ai
                           ON ai.codBase = pCodBase
                           AND ai.idUnicoRecurso = r.idUnico
                 WHERE
                         c.depth < 50)
          SELECT
                  CodAPU,
                  MIN(depth)
          FROM
                  chain
          GROUP BY
                  CodAPU;

      SELECT
              COUNT(*)
              INTO vTienePadres
      FROM
              tmp_apu_chain
      WHERE
              depth > 0;

      /* 3) Uso en presupuesto (EN SENTENCIAS SEPARADAS -> evita ERRNO 1137) */
      SET vUsadoPresupuesto = 0;

      SELECT
              COUNT(*)
              INTO vTmp
      FROM
              presupuestos_items pi
          JOIN
            tmp_apu_chain tc
              ON tc.CodAPU = pi.codAPU
      WHERE
              pi.codBase = pCodBase;
      SET vUsadoPresupuesto = vUsadoPresupuesto + vTmp;

      SELECT
              COUNT(*)
              INTO vTmp
      FROM
              presupuestos_items_trabajo pit
          JOIN
            tmp_apu_chain tc
              ON tc.CodAPU = pit.codAPU
      WHERE
              pit.codBase = pCodBase;
      SET vUsadoPresupuesto = vUsadoPresupuesto + vTmp;

      SELECT
              COUNT(*)
              INTO vTmp
      FROM
              presupuestos_items_trabajo_edt pite
          JOIN
            tmp_apu_chain tc
              ON tc.CodAPU = pite.codAPU
      WHERE
              pite.codBase = pCodBase;
      SET vUsadoPresupuesto = vUsadoPresupuesto + vTmp;

      SELECT
              COUNT(*)
              INTO vTmp
      FROM
              presupuestos_tanteo_apus pta
          JOIN
            tmp_apu_chain tc
              ON tc.CodAPU = pta.CodAPU
      WHERE
              pta.codBase = pCodBase;
      SET vUsadoPresupuesto = vUsadoPresupuesto + vTmp;

      SELECT
              COUNT(*)
              INTO vTmp
      FROM
              presupuestos_tanteo_apus_bkp ptab
          JOIN
            tmp_apu_chain tc
              ON tc.CodAPU = ptab.CodAPU
      WHERE
              ptab.codBase = pCodBase;
      SET vUsadoPresupuesto = vUsadoPresupuesto + vTmp;

      IF vUsadoPresupuesto > 0
      THEN
        SET oResultado = 'INTEGRADO';
        SET oDetalle = 'USO_EN_PRESUPUESTO_CADENA_APU';
        LEAVE proc;
      END IF;

      /* 4) Recursos asociados a la cadena */
      DROP TEMPORARY TABLE IF EXISTS tmp_apu_recursos;
      CREATE TEMPORARY TABLE tmp_apu_recursos
        (
          idUnicoRecurso VARCHAR(255) NOT NULL,
          PRIMARY KEY (idUnicoRecurso)
        ) ENGINE = MEMORY;

      INSERT IGNORE INTO tmp_apu_recursos
            (
              idUnicoRecurso
            )
          SELECT
                  r.idUnico
          FROM
                  recursos r
              JOIN
                tmp_apu_chain tc
                  ON r.codBase = pCodBase
                    AND r.Especificaciones = CONCAT(
                      'APU: ',
                      tc.CodAPU)
          WHERE
                  r.idUnico IS NOT NULL;

      /* 5) Tanteo recursos (también en sentencias separadas) */
      SET vUsadoTanteoRecursos = 0;

      SELECT
              COUNT(*)
              INTO vTmp
      FROM
              presupuestos_tanteo_recursos ptr
          JOIN
            tmp_apu_recursos tr
              ON tr.idUnicoRecurso = ptr.idUnicoRecurso
      WHERE
              ptr.codBase = pCodBase;
      SET vUsadoTanteoRecursos = vUsadoTanteoRecursos + vTmp;

      SELECT
              COUNT(*)
              INTO vTmp
      FROM
              presupuestos_tanteo_recursos_bkp ptrb
          JOIN
            tmp_apu_recursos tr
              ON tr.idUnicoRecurso = ptrb.idUnicoRecurso
      WHERE
              ptrb.codBase = pCodBase;
      SET vUsadoTanteoRecursos = vUsadoTanteoRecursos + vTmp;

      IF vUsadoTanteoRecursos > 0
      THEN
        SET oResultado = 'INTEGRADO';
        SET oDetalle = 'USO_TANTEO_RECURSOS_CADENA_APU';
        LEAVE proc;
      END IF;

      /* 6) Anidado => no borrar */
      IF vTienePadres > 0
      THEN
        SET oResultado = 'INTEGRADO';
        SET oDetalle = 'USADO_COMO_RECURSO_EN_OTRO_APU';
        LEAVE proc;
      END IF;

      /* 7) Borrado */
      START TRANSACTION;

      DELETE
      FROM
              apus_items
      WHERE
              codBase = pCodBase
              AND CodAPU = pCodAPU;

      DELETE
      FROM
              apus
      WHERE
              codBase = pCodBase
              AND CodAPU = pCodAPU;

      DELETE
      FROM
              recursos
      WHERE
              codBase = pCodBase
              AND Especificaciones = CONCAT(
                'APU: ',
                pCodAPU);

      COMMIT;

      SET oResultado = 'EXITO';
      SET oDetalle = 'APU_BORRADO_OK';

    END
    $$

--
-- Create procedure `actualizar_apu_completo`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS actualizar_apu_completo
  (
    IN p_codBase VARCHAR(50),
    IN p_codAPU VARCHAR(50)
  )
  BEGIN
    DECLARE v_costo_directo DECIMAL(18, 6);
    DECLARE v_costo_indirecto DECIMAL(18, 6);
    DECLARE v_anidado TINYINT DEFAULT 0;

    -- 1. Calcular costos
    SELECT
            IFNULL(
              SUM(Total),
              0)
            INTO v_costo_directo
    FROM
            apus_items
    WHERE
            codBase = p_codBase
            AND codAPU = p_codAPU;

    -- 2. Detectar APU anidado
    SELECT
            COUNT(*)
            INTO v_anidado
    FROM
            apus_items
    WHERE
            codBase = p_codBase
            AND codAPU = p_codAPU
            AND codCategoria = 6;

    -- 3. Indirectos
    SELECT
            (v_costo_directo * PorcentajeCostoIndirecto) / 100
            INTO v_costo_indirecto
    FROM
            apus
    WHERE
            codBase = p_codBase
            AND codAPU = p_codAPU;

    -- 4. Update APU
    UPDATE
    apus
    SET
            CostoDirectoTotal = v_costo_directo,
            CostoIndirectoTotal = v_costo_indirecto,
            PrecioUnitarioTotal = v_costo_directo + v_costo_indirecto,
            anidado = v_anidado,
            ultimaModificacion = NOW()
    WHERE
      codBase = p_codBase
      AND codAPU = p_codAPU;

    -- 5. Update recurso APU (cat 6)
    UPDATE
    recursos
    SET
            precio = v_costo_directo,
            preciolocal = v_costo_directo
    WHERE
      codBase = p_codBase
      AND Especificaciones = CONCAT(
        'APU: ',
        p_codAPU);

  END
  $$

--
-- Create function `Porcentaje`
--
CREATE
DEFINER = 'root'@'localhost'
FUNCTION IF NOT EXISTS Porcentaje
  (
    entrada DECIMAL(65, 10),
    tantoporciento DECIMAL(65, 10)
  )
RETURNS DECIMAL(65, 10)
NO SQL
  BEGIN
    RETURN (entrada * tantoporciento) / 100;
  END
  $$

--
-- Create procedure `recalcular_apu_totales`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS recalcular_apu_totales
  (
    IN p_codBase VARCHAR(255),
    IN p_codAPU VARCHAR(255)
  )
  BEGIN
    DECLARE v_CostoDirectoTotal DECIMAL(65, 10) DEFAULT 0;
    DECLARE v_CostoIndirectoTotal DECIMAL(65, 10) DEFAULT 0;
    DECLARE v_PrecioUnitarioTotal DECIMAL(65, 10) DEFAULT 0;
    DECLARE v_porcentajeIndirecto DECIMAL(65, 10) DEFAULT 0;

    /* ================================
       1. Validar APU existente
       ================================ */
    IF NOT EXISTS (SELECT
                  1
          FROM
                  apus
          WHERE
                  codBase = p_codBase
                  AND CodAPU = p_codAPU)
    THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'APU no encontrado';
    END IF;

    /* ================================
       2. Calcular CostoDirectoTotal
       ================================ */
    SELECT
            IFNULL(
              SUM(Total),
              0)
            INTO v_CostoDirectoTotal
    FROM
            apus_items
    WHERE
            codBase = p_codBase
            AND CodAPU = p_codAPU;

    /* ================================
       3. Obtener porcentaje indirecto
       ================================ */
    SELECT
            IFNULL(
              porcentajeCostoIndirecto,
              0)
            INTO v_porcentajeIndirecto
    FROM
            apus
    WHERE
            codBase = p_codBase
            AND CodAPU = p_codAPU
    LIMIT 1;

    /* ================================
       4. Calcular CostoIndirectoTotal
       ================================ */
    SET v_CostoIndirectoTotal =
    (v_CostoDirectoTotal * v_porcentajeIndirecto) / 100;

    /* ================================
       5. Calcular PrecioUnitarioTotal
       ================================ */
    SET v_PrecioUnitarioTotal =
    v_CostoDirectoTotal + v_CostoIndirectoTotal;

    /* ================================
       6. Actualizar tabla apus
       ================================ */
    UPDATE
    apus
    SET
            CostoDirectoTotal = v_CostoDirectoTotal,
            CostoIndirectoTotal = v_CostoIndirectoTotal,
            PrecioUnitarioTotal = v_PrecioUnitarioTotal
    WHERE
      codBase = p_codBase
      AND CodAPU = p_codAPU;

    /* ================================
       7. Actualizar porcentaje en apus_items
       ================================ */
    IF v_CostoDirectoTotal > 0
    THEN

      UPDATE
      apus_items
      SET
              porcentaje =
              (IFNULL(
                Total,
                0) / v_CostoDirectoTotal) * 100
      WHERE
        codBase = p_codBase
        AND CodAPU = p_codAPU;

    ELSE

      UPDATE
      apus_items
      SET
              porcentaje = 0
      WHERE
        codBase = p_codBase
        AND CodAPU = p_codAPU;

    END IF;

    /* ================================
       8. Actualizar recurso que representa el APU
       Especificaciones = 'APU: '+ CodAPU
       ================================ */
    UPDATE
    recursos
    SET
            preciolocal = v_CostoDirectoTotal,
            precio = v_CostoDirectoTotal,
            preciobase = v_CostoDirectoTotal,
            ultimaModificacion = NOW()
    WHERE
      codBase = p_codBase
      AND Especificaciones = CONCAT(
        'APU: ',
        p_codAPU);

  END
  $$

--
-- Create procedure `sincronizar_apu_como_recurso`
--
CREATE 
	DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS sincronizar_apu_como_recurso(
    IN p_codBase VARCHAR(255),
    IN p_codAPU  VARCHAR(255)
)
proc_block: BEGIN
    DECLARE v_idUnico        VARCHAR(255);
    DECLARE v_descripcion    VARCHAR(255);
    DECLARE v_unidad         VARCHAR(255);
    DECLARE v_precio         DECIMAL(65,10);

    DECLARE v_codAPU_actual  VARCHAR(255);
    DECLARE v_changed        INT DEFAULT 0;
    DECLARE done INT DEFAULT 0;

    /* Cursor 1: matriz de APUs afectados */
    DECLARE cur CURSOR FOR
        SELECT DISTINCT CodAPU
        FROM apus_items
        WHERE codBase = p_codBase
          AND idUnicoRecurso = v_idUnico;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    /* =====================================================
       FASE 1: Obtener recurso APU (lectura solamente)
       ===================================================== */
    SELECT idUnico, Descripcion, Unidad, IFNULL(Precio,0)
    INTO v_idUnico, v_descripcion, v_unidad, v_precio
    FROM recursos
    WHERE codBase = p_codBase
      AND Especificaciones = CONCAT('APU: ', p_codAPU)
    LIMIT 1;

    IF v_idUnico IS NULL THEN
        LEAVE proc_block; -- Changed to LEAVE proc_block; to exit the procedure
    END IF;

    /* =====================================================
       FASE 2: Actualizar apus_items SOLO si hay cambios
       ===================================================== */

    OPEN cur;

    read_loop: LOOP
        FETCH cur INTO v_codAPU_actual;
        IF done = 1 THEN
            LEAVE read_loop;
        END IF;

        /* Actualizar SOLO si realmente cambió algo */
        UPDATE apus_items
        SET
            Descripcion = v_descripcion,
            Unidad      = v_unidad,
            Precio      = v_precio,
            Total       = IFNULL(CantidadUnidad,0) *
                          v_precio *
                          IFNULL(Rendimiento,1)
        WHERE codBase = p_codBase
          AND CodAPU  = v_codAPU_actual
          AND idUnicoRecurso = v_idUnico
          AND (
                IFNULL(Precio,0) <> v_precio
             OR IFNULL(Descripcion,'') <> IFNULL(v_descripcion,'')
             OR IFNULL(Unidad,'') <> IFNULL(v_unidad,'')
          );

        /* Optimización 3: solo recalcular si hubo cambios */
        IF ROW_COUNT() > 0 THEN
            CALL recalcular_apu_totales(p_codBase, v_codAPU_actual);
        END IF;

    END LOOP;

    CLOSE cur;

END proc_block
$$

DELIMITER ;

--
-- Create table `codcpc`
--
CREATE TABLE IF NOT EXISTS codcpc
  (
    id          INT          NOT NULL AUTO_INCREMENT,
    codCPC      VARCHAR(15)  DEFAULT NULL,
    Descripcion TEXT         DEFAULT NULL,
    Tipo        VARCHAR(255) DEFAULT NULL,
    Porcentaje  FLOAT        DEFAULT NULL,
    PRIMARY KEY (id)
  )
ENGINE = INNODB,
AUTO_INCREMENT = 29784,
AVG_ROW_LENGTH = 120,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_general_ci,
ROW_FORMAT = DYNAMIC;

DELIMITER $$

--
-- Create procedure `insertar_item_apu`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS insertar_item_apu
  (
    IN p_codBase VARCHAR(255),
    IN p_codAPU VARCHAR(255),
    IN p_idUnicoRecurso VARCHAR(255),
    IN p_cantidadUnidad DECIMAL(65, 10),
    IN p_rendimiento DECIMAL(65, 10)
  )
  BEGIN
    DECLARE v_precio DECIMAL(65, 10);
    DECLARE v_rendimiento DECIMAL(65, 10);
    DECLARE v_total DECIMAL(65, 10);

    DECLARE v_codCategoria VARCHAR(255);
    DECLARE v_codSubCategoria VARCHAR(255);

    DECLARE v_codRecurso VARCHAR(255);
    DECLARE v_codRecursoCompleto VARCHAR(255);
    DECLARE v_descripcion VARCHAR(255);
    DECLARE v_unidad VARCHAR(255);
    DECLARE v_moneda VARCHAR(255);
    DECLARE v_codCPC VARCHAR(255);
    DECLARE v_tipoCPC VARCHAR(255);
    DECLARE v_porcentajeCPC VARCHAR(255);
    DECLARE v_termino VARCHAR(255);

    DECLARE v_existe INT DEFAULT 0;

    /* =====================================
       1. Validación cantidad
       ===================================== */
    IF p_cantidadUnidad IS NULL
      OR
      p_cantidadUnidad <= 0
    THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'CantidadUnidad inválida';
    END IF;

    /* =====================================
       2. Obtener datos completos del recurso
       ===================================== */
    SELECT
            IFNULL(
              Precio,
              0),
            codRecurso,
            codCategoriaBase,
            codSubCategoria,
            codRecursoCompleto,
            Descripcion,
            Unidad,
            moneda,
            codCPC,
            TipoCPC,
            porcentajeCPC,
            termino
            INTO v_precio,
            v_codRecurso,
            v_codCategoria,
            v_codSubCategoria,
            v_codRecursoCompleto,
            v_descripcion,
            v_unidad,
            v_moneda,
            v_codCPC,
            v_tipoCPC,
            v_porcentajeCPC,
            v_termino
    FROM
            recursos
    WHERE
            codBase = p_codBase
            AND idUnico = p_idUnicoRecurso
    LIMIT 1;

    IF v_codRecurso IS NULL
    THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Recurso no encontrado';
    END IF;

    /* =====================================
       3. Verificar duplicado
       ===================================== */
    SELECT
            COUNT(*)
            INTO v_existe
    FROM
            apus_items
    WHERE
            codBase = p_codBase
            AND CodAPU = p_codAPU
            AND idUnicoRecurso = p_idUnicoRecurso;

    IF v_existe > 0
    THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'El recurso ya existe en el APU';
    END IF;

    /* =====================================
       4. Calcular Total
       ===================================== */
    SET v_total = v_precio * p_cantidadUnidad * p_rendimiento;

    /* =====================================
       5. Insert completo en apus_items
       ===================================== */
    INSERT INTO apus_items
          (
            codBase,
            CodAPU,
            codAPUAlternativo,
            CodCategoria,
            codSubCategoria,
            idUnicoRecurso,
            codRecurso,
            codRecursoCompleto,
            Descripcion,
            Unidad,
            Precio,
            moneda,
            CantidadUnidad,
            Rendimiento,
            Total,
            porcentaje,
            codCPC,
            TipoCPC,
            porcentajeCPC,
            termino
          )
    VALUES
        (
          p_codBase, p_codAPU, NULL, v_codCategoria, v_codSubCategoria, p_idUnicoRecurso, v_codRecurso, v_codRecursoCompleto, v_descripcion, v_unidad, v_precio, v_moneda, p_cantidadUnidad, p_rendimiento, v_total, 0, v_codCPC, v_tipoCPC, v_porcentajeCPC, v_termino
        );

  END
  $$

--
-- Create procedure `exportar_APUS_y_APUS_Items`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS exportar_APUS_y_APUS_Items
  (
    IN iCodBase VARCHAR(255),
    IN iCodAPU VARCHAR(255),
    IN id_exports VARCHAR(255)
  )
  BEGIN
    DECLARE done INTEGER;
    DECLARE v_id INTEGER;
    DECLARE cur1 CURSOR FOR
      SELECT
              a.id
      FROM
              apus a
      WHERE
              a.codBase = iCodBase
              AND a.CodAPU = iCodAPU
              AND NOT EXISTS (SELECT
                          1
                  FROM
                          apus_exports ae
                  WHERE
                          ae.codBase = a.codBase
                          AND ae.id_exports = id_exports
                          AND ae.CodAPU = a.CodAPU);

    DECLARE CONTINUE HANDLER FOR NOT FOUND
    SET done = TRUE;
    /* ------------ INICIO ---------- -- */

    SET done := FALSE;
    OPEN cur1;
    loop_cur1:
    LOOP
      FETCH cur1 INTO v_id;
      IF done
      THEN
        LEAVE loop_cur1;
      END IF;


      /* Insertar APUS */

      INSERT INTO apus_exports
            (
              codBase,
              codCategoriaAPU,
              codRecursoAPU,
              CategoriaAPU,
              CodAPU,
              Descripcion,
              Unidad,
              Rendimiento,
              RendimientoTodoAnalisis,
              RendimientoTodoEscenario,
              CostoDirectoTotal,
              CostoIndirectoTotal,
              PorcentajeCostoIndirecto,
              PrecioUnitarioTotal,
              moneda,
              codCPC,
              FechaHoraCreacion,
              ultimaModificacion,
              pendienteRevision,
              rendimientoHUnidad,
              nhCuadrillas,
              anidado,
              id_exports
            )
          SELECT
                  codBase,
                  codCategoriaAPU,
                  codRecursoAPU,
                  CategoriaAPU,
                  CodAPU,
                  Descripcion,
                  Unidad,
                  Rendimiento,
                  RendimientoTodoAnalisis,
                  RendimientoTodoEscenario,
                  CostoDirectoTotal,
                  CostoIndirectoTotal,
                  PorcentajeCostoIndirecto,
                  PrecioUnitarioTotal,
                  moneda,
                  codCPC,
                  FechaHoraCreacion,
                  ultimaModificacion,
                  pendienteRevision,
                  rendimientoHUnidad,
                  nhCuadrillas,
                  anidado,
                  id_exports
          FROM
                  apus
          WHERE
                  id = v_id;

      /* Insertar APUS_ITEMS */

      INSERT INTO apus_items_exports
            (
              codBase,
              CodAPU,
              CodCategoria,
              codSubCategoria,
              idUnicoRecurso,
              codRecurso,
              codRecursoCompleto,
              Descripcion,
              Unidad,
              Precio,
              moneda,
              CantidadUnidad,
              Rendimiento,
              Total,
              porcentaje,
              codCPC,
              TipoCPC,
              porcentajeCPC,
              termino,
              id_exports
            )
          SELECT
                  codBase,
                  CodAPU,
                  CodCategoria,
                  codSubCategoria,
                  idUnicoRecurso,
                  codRecurso,
                  codRecursoCompleto,
                  Descripcion,
                  Unidad,
                  Precio,
                  moneda,
                  CantidadUnidad,
                  Rendimiento,
                  Total,
                  porcentaje,
                  codCPC,
                  TipoCPC,
                  porcentajeCPC,
                  termino,
                  id_exports
          FROM
                  apus_items
          WHERE
                  codBase = iCodBase
                  AND CodAPU = iCodAPU;
    END LOOP;
    CLOSE cur1;


  END
  $$

--
-- Create procedure `exportar_GestionAPUAnidado`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS exportar_GestionAPUAnidado
  (
    IN iCodBase VARCHAR(255),
    IN id_exports VARCHAR(255)
  )
  BEGIN
    DECLARE done INTEGER;
    DECLARE v_id INTEGER;

    DECLARE cur1 CURSOR FOR
      SELECT DISTINCT
              SUBSTR(idUnicoRecurso, 5, LENGTH(
                idUnicoRecurso))
      FROM
              apus_items_exports ai
      WHERE
              ai.codBase = iCodBase
              AND ai.idUnicoRecurso LIKE ('APU: %')
              AND ai.id_exports = id_exports
              AND NOT EXISTS (SELECT
                          1
                  FROM
                          apus_exports
                  WHERE
                          codBase = iCodBase
                          AND CodAPU IN (SELECT DISTINCT
                                      SUBSTR(idUnicoRecurso, 5, LENGTH(
                                        idUnicoRecurso))
                              FROM
                                      apus_items
                              WHERE
                                      codBase = iCodBase
                                      AND idUnicoRecurso LIKE ('APU: %')));

    DECLARE CONTINUE HANDLER FOR NOT FOUND
    SET done = TRUE;

    /* ------------ INICIO ---------- -- */
    SET done := FALSE;
    OPEN cur1;
    loop_cur1:
    LOOP
      FETCH cur1 INTO v_id;
      IF done
      THEN
        LEAVE loop_cur1;
      END IF;
      CALL exportar_APUS_y_APUS_Items(
        iCodBase,
        v_id,
        id_exports);
    END LOOP;
    CLOSE cur1;

  END
  $$

--
-- Create procedure `exportar_APUS_anidada`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS exportar_APUS_anidada
  (
    IN iCodBase VARCHAR(255),
    IN id_exports VARCHAR(255)
  )
  BEGIN
    DECLARE contador INT;

    /* ------------ INICIO ---------- -- */
    SELECT
            COUNT(*)
            INTO contador
    FROM
            apus_exports ae
    WHERE
            ae.anidado = 1
            AND ae.id_exports = id_exports;

    /* BUCLE DE ACTUALIZACION -- */

    WHILE contador > 0 DO
      /* Crear Nivel de ANIDADO */
      CALL exportar_GestionAPUAnidado(
        iCodBase,
        id_exports);

      /* Contar si es necesario nuevo nivel de anidado */
      SELECT
              COUNT(DISTINCT
              idUnicoRecurso)
              INTO contador
      FROM
              apus_items_exports ai
      WHERE
              ai.codBase = iCodBase
              AND ai.idUnicoRecurso LIKE ('APU: %')
              AND NOT EXISTS (SELECT
                          1
                  FROM
                          apus_exports
                  WHERE
                          codBase = iCodBase
                          AND CodAPU IN (SELECT DISTINCT
                                      SUBSTR(idUnicoRecurso, 5, LENGTH(
                                        idUnicoRecurso))
                              FROM
                                      apus_items
                              WHERE
                                      codBase = iCodBase
                                      AND idUnicoRecurso LIKE ('APU: %')));
    END WHILE;

  END
  $$

--
-- Create procedure `exportar_Presupuestos_APUS`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS exportar_Presupuestos_APUS
  (
    IN iCodBase VARCHAR(255),
    IN iCodPresupuesto VARCHAR(255),
    IN iRevision INT,
    IN id_exports VARCHAR(255)
  )
  BEGIN
    DECLARE done INTEGER;
    DECLARE v_id INTEGER;
    DECLARE v_CodAPU VARCHAR(255);
    DECLARE v_existe INTEGER;

    DECLARE cur1 CURSOR FOR
      SELECT
              pi.id,
              pi.codAPU
      FROM
              presupuestos_items pi
      WHERE
              pi.codBase = iCodBase
              AND pi.codPresupuesto = iCodPresupuesto
              AND pi.revision = iRevision
              AND pi.codAPU IS NOT NULL;
    DECLARE CONTINUE HANDLER FOR NOT FOUND
    SET done = TRUE;
    /* ------------ INICIO ---------- -- */
    SET done := FALSE;
    OPEN cur1;
    loop_cur1:
    LOOP
      FETCH cur1 INTO v_id, v_CodAPU;
      IF done
      THEN
        LEAVE loop_cur1;
      END IF;
      CALL exportar_APUS_y_APUS_Items(
        iCodBase,
        v_CodAPU,
        id_exports);
    END LOOP;
    CLOSE cur1;

    /* Tratar anidados -- */
    CALL exportar_APUS_anidada(
      iCodBase,
      id_exports);

  END
  $$

--
-- Create procedure `duplicar_apu_completo`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS duplicar_apu_completo
  (
    IN pCodAPUOrigen VARCHAR(50),
    IN pNuevaDescripcion VARCHAR(255),
    OUT pNuevoCodAPU VARCHAR(50)
  )
  BEGIN
    DECLARE vCodBase VARCHAR(50);
    DECLARE vCodCatAPU VARCHAR(50);
    DECLARE vCategoriaAPU VARCHAR(255);
    DECLARE vUnidad VARCHAR(50);
    DECLARE vMoneda VARCHAR(10);
    DECLARE vRend VARCHAR(50);
    DECLARE vRTA TINYINT(1);
    DECLARE vRTE TINYINT(1);
    DECLARE vPctInd DOUBLE;
    DECLARE vPendRev TINYINT(1);

    DECLARE vNuevoCodRecursoAPU BIGINT;
    DECLARE vNuevoCodRecurso BIGINT;
    DECLARE vNuevoIdUnico VARCHAR(80);
    DECLARE vNow DATETIME;
    DECLARE vCostoDirecto DOUBLE DEFAULT 0;

    /* Si falla algo, rollback */
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      RESIGNAL;
    END;

    SET vNow = NOW();

    IF pCodAPUOrigen IS NULL
      OR
      TRIM(pCodAPUOrigen) = ''
    THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'pCodAPUOrigen vacío';
    END IF;

    IF pNuevaDescripcion IS NULL
      OR
      TRIM(pNuevaDescripcion) = ''
    THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'pNuevaDescripcion vacía';
    END IF;

    START TRANSACTION;

    /* 1) Leer cabecera APU origen */
    SELECT
            codBase,
            codCategoriaAPU,
            CategoriaAPU,
            unidad,
            moneda,
            rendimiento,
            RendimientoTodoAnalisis,
            RendimientoTodoEscenario,
            PorcentajeCostoIndirecto,
            pendienteRevision
            INTO vCodBase,
            vCodCatAPU,
            vCategoriaAPU,
            vUnidad,
            vMoneda,
            vRend,
            vRTA,
            vRTE,
            vPctInd,
            vPendRev
    FROM
            apus
    WHERE
            codAPU = pCodAPUOrigen
    LIMIT 1
    FOR UPDATE;

    IF vCodBase IS NULL
      OR
      TRIM(vCodBase) = ''
    THEN
      ROLLBACK;
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'APU origen no existe';
    END IF;

    /* 2) Generar nuevo codAPU (si necesitas prefijo APUsr, cambia aquí) */
    SET pNuevoCodAPU = CONCAT(
      'APUsr',
      UUID_SHORT());
    -- SET pNuevoCodAPU = CAST(UUID_SHORT() AS CHAR);

    /* 3) Generar nuevo codRecursoAPU (secuencial por base+categoria) */
    SELECT
            IFNULL(
              MAX(CAST(codRecursoAPU AS UNSIGNED)),
              0) + 1
            INTO vNuevoCodRecursoAPU
    FROM
            apus
    WHERE
            codBase = vCodBase
            AND codCategoriaAPU = vCodCatAPU
    FOR UPDATE;

    /* 4) Insert cabecera APU nueva (totales en 0; luego recalculas) */
    INSERT INTO apus
          (
            codBase,
            CategoriaAPU,
            codCategoriaAPU,
            codRecursoAPU,
            codAPU,
            descripcion,
            unidad,
            rendimiento,
            RendimientoTodoAnalisis,
            RendimientoTodoEscenario,
            FechaHoraCreacion,
            CostoDirectoTotal,
            CostoIndirectoTotal,
            PorcentajeCostoIndirecto,
            PrecioUnitarioTotal,
            pendienteRevision,
            ultimaModificacion,
            moneda,
            rendimientoHUnidad,
            nhCuadrillas,
            anidado
          )
        SELECT
                a.codBase,
                a.CategoriaAPU,
                a.codCategoriaAPU,
                vNuevoCodRecursoAPU,
                pNuevoCodAPU,
                pNuevaDescripcion,
                a.unidad,
                a.rendimiento,
                a.RendimientoTodoAnalisis,
                a.RendimientoTodoEscenario,
                vNow,
                0,
                0,
                a.PorcentajeCostoIndirecto,
                0,
                a.pendienteRevision,
                vNow,
                a.moneda,
                a.rendimientoHUnidad,
                a.nhCuadrillas,
                a.anidado
        FROM
                apus a
        WHERE
                a.codAPU = pCodAPUOrigen
        LIMIT 1;

    /* 5) Crear recurso para “APU: nuevoCodAPU” en recursos (categoria 6) */
    SET vNuevoIdUnico = CONCAT(
      'Rsr',
      UUID_SHORT());

    /* codRecurso (secuencial por base+catBase=6+subcat=vCodCatAPU) */
    SELECT
            IFNULL(
              MAX(CAST(codRecurso AS UNSIGNED)),
              0) + 1
            INTO vNuevoCodRecurso
    FROM
            recursos
    WHERE
            codBase = vCodBase
            AND codCategoriaBase = 6
            AND codSubcategoria = vCodCatAPU
    FOR UPDATE;

    INSERT INTO recursos
          (
            idUnico,
            codBase,
            codRecurso,
            codCategoriaBase,
            codSubcategoria,
            codRecursoCompleto,
            descripcion,
            unidad,
            precio,
            preciolocal,
            termino,
            codAlternativo,
            codCPC,
            especificaciones,
            fechahoraCreacion,
            ultimaModificacion
          )
    VALUES
        (
          vNuevoIdUnico, vCodBase, vNuevoCodRecurso, 6, vCodCatAPU, CONCAT('6', LPAD(vCodCatAPU, 4, '0'), LPAD(vNuevoCodRecurso, 5, '0')), pNuevaDescripcion, vUnidad, 0, 0, 0, '', '', CONCAT('APU: ', pNuevoCodAPU), vNow, vNow
        );

    /* 6) Duplicar items al nuevo codAPU */
    INSERT INTO apus_items
          (
            codBase,
            codAPU,
            codCategoria,
            codSubcategoria,
            idUnicoRecurso,
            codRecurso,
            codRecursoCompleto,
            descripcion,
            Unidad,
            Precio,
            CantidadUnidad,
            Rendimiento,
            Total,
            Porcentaje
          )
        SELECT
                i.codBase,
                pNuevoCodAPU,
                i.codCategoria,
                i.codSubcategoria,
                i.idUnicoRecurso,
                i.codRecurso,
                i.codRecursoCompleto,
                i.descripcion,
                i.Unidad,
                i.Precio,
                i.CantidadUnidad,
                i.Rendimiento,
                i.Total,
                i.Porcentaje
        FROM
                apus_items i
        WHERE
                i.codBase = vCodBase
                AND i.codAPU = pCodAPUOrigen;

    /* 7) Recalcular totales de la nueva APU */
    UPDATE
    apus a
    SET
            a.CostoDirectoTotal = (SELECT
                        COALESCE(
                          SUM(x.Total),
                          0)
                FROM
                        apus_items x
                WHERE
                        x.codBase = a.codBase
                        AND x.codAPU = a.codAPU),
            a.CostoIndirectoTotal = ((SELECT
                        COALESCE(
                          SUM(x.Total),
                          0)
                FROM
                        apus_items x
                WHERE
                        x.codBase = a.codBase
                        AND x.codAPU = a.codAPU)
            * a.PorcentajeCostoIndirecto) / 100,
            a.PrecioUnitarioTotal = (SELECT
                        COALESCE(
                          SUM(x.Total),
                          0)
                FROM
                        apus_items x
                WHERE
                        x.codBase = a.codBase
                        AND x.codAPU = a.codAPU)
            + (((SELECT
                        COALESCE(
                          SUM(x.Total),
                          0)
                FROM
                        apus_items x
                WHERE
                        x.codBase = a.codBase
                        AND x.codAPU = a.codAPU)
            * a.PorcentajeCostoIndirecto) / 100),
            a.ultimaModificacion = vNow
    WHERE
      a.codBase = vCodBase
      AND a.codAPU = pNuevoCodAPU;

    /* 8) Poner precio del recurso APU = costo directo (SIN JOIN a apus, evita el error del trigger) */
    SELECT
            COALESCE(
              CostoDirectoTotal,
              0)
            INTO vCostoDirecto
    FROM
            apus
    WHERE
            codBase = vCodBase
            AND codAPU = pNuevoCodAPU
    LIMIT 1;

    UPDATE
    recursos r
    SET
            r.precio = vCostoDirecto,
            r.preciolocal = vCostoDirecto,
            r.ultimaModificacion = vNow
    WHERE
      r.codBase = vCodBase
      AND r.especificaciones = CONCAT(
        'APU: ',
        pNuevoCodAPU);

    COMMIT;
  END
  $$

--
-- Create function `Redondea`
--
CREATE
DEFINER = 'root'@'localhost'
FUNCTION IF NOT EXISTS Redondea
  (
    iValor DECIMAL(65, 10),
    iPrecision INT
  )
RETURNS DECIMAL(65, 10)
NO SQL
  BEGIN
    DECLARE oValor DECIMAL(65, 10);
    DECLARE i INT DEFAULT 10;

    SET oValor = ivalor;
    WHILE
    i > iPrecision DO

      SET oValor = ROUND(
        oValor,
        i - 1);

      SET i = i - 1;

    END WHILE;
    RETURN oValor;

  END
  $$

--
-- Create procedure `CuadreRecursos`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS CuadreRecursos
  (
    iPrecision INT
  )
  BEGIN
    DECLARE var_idRecurso INT;
    DECLARE done INTEGER;
    DECLARE oldPrecio DECIMAL(65, 10);
    DECLARE newPrecio DECIMAL(65, 10);

    DECLARE cur_Recurso CURSOR FOR
      SELECT
              id
      FROM
              recursos;

    DECLARE CONTINUE HANDLER FOR NOT FOUND
    SET done = TRUE;

    OPEN cur_recurso;
    loop_cur_Recurso:
    LOOP
      FETCH cur_recurso INTO var_idRecurso;
      IF done
      THEN
        LEAVE loop_cur_Recurso;
      END IF;
      SELECT
              Precio
              INTO oldPrecio
      FROM
              recursos
      WHERE
              id = var_idRecurso;
      SET newPrecio = Redondea(
        oldPrecio,
        iPrecision);
      UPDATE
      recursos
      SET
              precio = newPrecio,
              preciolocal = newPrecio
      WHERE
        id = var_idRecurso;

    END LOOP;
    CLOSE cur_recurso;
  END
  $$

--
-- Create procedure `cuadreAPUS_Items`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS cuadreAPUS_Items
  (
    iPrecision INT
  )
  BEGIN
    DECLARE var_idAPU_Items INT;
    DECLARE v_idUnicoRecurso VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE v_codBase VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci;

    DECLARE v_cantidadUnidad DECIMAL(65, 10);
    DECLARE v_Rendimiento DECIMAL(65, 10);
    DECLARE done INTEGER;
    DECLARE newTotal DECIMAL(65, 10);
    DECLARE newPrecio DECIMAL(65, 10);

    DECLARE cur_APUS_Items CURSOR FOR
      SELECT
              id
      FROM
              apus_items;

    DECLARE CONTINUE HANDLER FOR NOT FOUND
    SET done = TRUE;
    OPEN cur_apus_Items;
    loop_cur_apus_items:
    LOOP
      FETCH cur_apus_items INTO var_idAPU_Items;
      IF done
      THEN
        LEAVE loop_cur_apus_items;
      END IF;
      SELECT
              idUnicoRecurso,
              codBase,
              CantidadUnidad,
              Rendimiento
              INTO v_idUnicoRecurso, v_codBase, v_CantidadUnidad, V_rendimiento
      FROM
              apus_items
      WHERE
              id = var_idAPU_Items;
      SELECT
              Precio
              INTO newPrecio
      FROM
              recursos
      WHERE
              idUnico = V_idUnicoRecurso
              AND codBase = V_codBase;
      SET newTotal = Redondea(
        newprecio * v_rendimiento * v_cantidadUnidad,
        iPrecision);
      UPDATE
      apus_items
      SET
              Precio = newPrecio,
              Total = newTotal
      WHERE
        id = var_idAPU_Items;
    END LOOP;
    CLOSE cur_APUS_Items;
  END
  $$

--
-- Create procedure `cuadreAPUSTotal`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS cuadreAPUSTotal
  (
    newCostoIndirectoTotal DECIMAL(65, 10)
  )
  BEGIN
    DECLARE v_codAPU VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE v_codBase VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE var_idAPUS INT;
    DECLARE newTotal DECIMAL(65, 10);
    DECLARE newCostoIndirectoTotal DECIMAL(65, 10);
    DECLARE v_indirectos DECIMAL(65, 10);
    DECLARE done INTEGER;
    DECLARE cur_APUS CURSOR FOR
      SELECT
              id
      FROM
              apus;

    DECLARE CONTINUE HANDLER FOR NOT FOUND
    SET done = TRUE;
    OPEN cur_APUS;
    loop_apus:
    LOOP
      FETCH cur_APUS INTO var_idAPUS;
      IF done
      THEN
        LEAVE loop_apus;
      END IF;

      SELECT
              codBase,
              codAPU,
              PorcentajeCostoIndirecto
              INTO v_codBase, v_codAPU, v_indirectos
      FROM
              apus
      WHERE
              id = var_idAPUS;
      SELECT
              SUM(total)
              INTO newTotal
      FROM
              apus_items
      WHERE
              codBase = v_codBase
              AND codAPU = v_codAPU;
      SET newCostoIndirectoTotal = Redondea(
        Porcentaje(
          newTotal,
          v_indirectos),
        newCostoIndirectoTotal);

      UPDATE
      apus
      SET
              CostoDirectoTotal = newTotal,
              CostoIndirectoTotal = newCostoIndirectoTotal,
              PrecioUnitarioTotal = newTotal + newCostoIndirectoTotal
      WHERE
        id = var_idAPUS;


    END LOOP;
    CLOSE cur_APUS;
  END
  $$

