--
-- Create table `tgriditems`
--
CREATE TABLE IF NOT EXISTS tgriditems
  (
    id                 INT             NOT NULL AUTO_INCREMENT,
    codBase            VARCHAR(255)    DEFAULT NULL,
    codPresupuesto     VARCHAR(255)    DEFAULT NULL,
    revision           VARCHAR(255)    DEFAULT NULL,
    codEdt             VARCHAR(255)    DEFAULT NULL,
    codItems           VARCHAR(255)    DEFAULT NULL,
    codUnicoItems      VARCHAR(255)    DEFAULT NULL,
    codAPUGenerico     VARCHAR(255)    DEFAULT NULL,
    codAPU             VARCHAR(255)    DEFAULT NULL,
    descripcion        VARCHAR(255)    DEFAULT NULL,
    unidad             VARCHAR(255)    DEFAULT NULL,
    cantidad           DECIMAL(65, 10) DEFAULT NULL,
    PUnitario          DECIMAL(65, 10) DEFAULT NULL,
    Ptotal             DECIMAL(65, 10) DEFAULT NULL,
    notas              TINYINT(1)      DEFAULT NULL,
    rendimientoHUnidad VARCHAR(255)    DEFAULT NULL,
    nhCuadrillas       VARCHAR(255)    DEFAULT NULL,
    anidado            VARCHAR(1)      DEFAULT NULL,
    posgrid            INT             DEFAULT NULL,
    PRIMARY KEY (id)
  )
ENGINE = INNODB,
AVG_ROW_LENGTH = 3276,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_general_ci,
ROW_FORMAT = DYNAMIC;

DELIMITER $$

--
-- Create procedure `Presupuestos_Pareto_guardaItems`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS Presupuestos_Pareto_guardaItems
  (
    IN iCodBase VARCHAR(255),
    IN iCodPresupuesto VARCHAR(255),
    IN iRevision VARCHAR(255),
    IN iLimite INT,
    IN CadenaBusqueda VARCHAR(255)
  )
  BEGIN
    DECLARE done INTEGER;
    DECLARE var_iditems INTEGER;
    DECLARE var_codUnicoItems CHAR(50);
    DECLARE cursor1 CURSOR FOR
      SELECT
              pit2.id,
              pit2.codUnicoItems
      FROM
              presupuestos_items_trabajo pit2
      WHERE
              pit2.codAPU != ''
              AND pit2.codBase = icodBase
              AND pit2.codPresupuesto = icodPresupuesto
              AND pit2.revision = iRevision
              AND pit2.codItems LIKE CadenaBusqueda
      ORDER BY
              pit2.posgrid,
              pit2.Ptotal ASC LIMIT iLimite;
    DECLARE CONTINUE HANDLER FOR NOT FOUND
    SET done = TRUE;

    OPEN cursor1;
    loop_cursor1:
    LOOP
      FETCH cursor1 INTO var_iditems, var_codUnicoItems;
      IF done
      THEN
        LEAVE loop_cursor1;
      END IF;
      IF NOT EXISTS (SELECT
                    *
            FROM
                    tgriditems t
            WHERE
                    t.codBase = iCodBase
                    AND t.codPresupuesto = iCodPresupuesto
                    AND t.revision = irevision
                    AND t.codUnicoItems = var_codUnicoItems)
      THEN
        INSERT INTO tgriditems
              (
                codBase,
                codPresupuesto,
                revision,
                codEDT,
                codItems,
                codUnicoItems,
                codAPUGenerico,
                codAPU,
                descripcion,
                unidad,
                cantidad,
                PUnitario,
                Ptotal,
                notas,
                rendimientoHUnidad,
                nhCuadrillas,
                anidado,
                posgrid
              )
            SELECT
                    p.codBase,
                    p.codPresupuesto,
                    p.revision,
                    p.codEDT,
                    p.codItems,
                    p.codUnicoItems,
                    p.codAPUGenerico,
                    p.codAPU,
                    p.descripcion,
                    p.unidad,
                    IF((p.codAPU IS NULL) OR (p.codAPU = ''), NULL, p.cantidad)                                           AS Cantidad,
                    IF((p.codAPU IS NULL) OR (p.codAPU = ''), NULL, IF(t.id IS NULL, p.PUnitario, t.PrecioUnitarioTotal)) AS PUnitario,
                    IF
                    (t.id IS NULL, p.Ptotal, Redondea(
                      t.PrecioUnitarioTotal * p.cantidad,
                      5))                                                                                                 AS Ptotal,
                    p.notas,
                    p.rendimientoHUnidad,
                    p.nhCuadrillas,
                    p.anidado,
                    p.posgrid
            FROM
                    presupuestos_items_trabajo p
                LEFT JOIN
                  presupuestos_tanteo_apus t
                    ON (
                        t.CodAPU = p.codAPU
                        AND t.codBase = p.codBase
                        AND t.codPresupuesto = p.codPresupuesto
                        AND t.revision = p.Revision
                      )
            WHERE
                    p.id = var_iditems;
      END IF;
    END LOOP;
    CLOSE cursor1;
  END
  $$

--
-- Create procedure `Presupuestos_Pareto_General`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS Presupuestos_Pareto_General
  (
    IN icodBase VARCHAR(255),
    IN icodPresupuesto VARBINARY(255),
    IN iRevision VARBINARY(255)
  )
  BEGIN
    DECLARE done INTEGER;
    DECLARE nItems INTEGER;
    DECLARE var_iditems INTEGER;
    DECLARE cursor1 CURSOR FOR
      SELECT
              pit.id
      FROM
              presupuestos_items_trabajo pit
      WHERE
              (       pit.codAPU = ''
                      OR pit.codAPU IS NULL)
              AND pit.codBase = icodBase
              AND pit.codPresupuesto = icodPresupuesto
              AND pit.revision = iRevision
      ORDER BY
              pit.posgrid ASC;

    DECLARE cursor2 CURSOR FOR
      SELECT
              pit2.id
      FROM
              presupuestos_items_trabajo pit2
      WHERE
              pit2.codAPU != ''
              AND pit2.codBase = icodBase
              AND pit2.codPresupuesto = icodPresupuesto
              AND pit2.revision = iRevision
      ORDER BY
              pit2.posgrid,
              pit2.Ptotal ASC LIMIT nItems;

    DECLARE CONTINUE HANDLER FOR NOT FOUND
    SET done = TRUE;

    DELETE
    FROM
            tgriditems tg
    WHERE
            tg.codBase = icodbase
            AND tg.codPresupuesto = icodpresupuesto
            AND tg.revision = irevision;

    SELECT
            COUNT(*)
            INTO nItems
    FROM
            presupuestos_items_trabajo pit3
    WHERE
            pit3.codAPU != ''
    ORDER BY
            pit3.posgrid ASC;
    SET nItems := Porcentaje(
      nItems,
      20);
    SET nItems := TRUNCATE(
      nItems,
      0);
    SET nItems := IF(nItems = 0, 1, nItems);
    SET done = FALSE;
    OPEN cursor1;
    loop_edt:
    LOOP
      FETCH cursor1 INTO var_iditems;
      IF done
      THEN
        LEAVE loop_edt;
      END IF;
      INSERT INTO tgriditems
            (
              codBase,
              codPresupuesto,
              revision,
              codEDT,
              codItems,
              codUnicoItems,
              codAPUGenerico,
              codAPU,
              descripcion,
              unidad,
              cantidad,
              PUnitario,
              Ptotal,
              notas,
              rendimientoHUnidad,
              nhCuadrillas,
              anidado,
              posgrid
            )
          SELECT
                  codBase,
                  codPresupuesto,
                  revision,
                  codEDT,
                  codItems,
                  codUnicoItems,
                  codAPUGenerico,
                  codAPU,
                  descripcion,
                  unidad,
                  '',
                  '',
                  Ptotal,
                  notas,
                  rendimientoHUnidad,
                  nhCuadrillas,
                  anidado,
                  posgrid
          FROM
                  presupuestos_items_trabajo
          WHERE
                  id = var_iditems
          ORDER BY
                  posgrid;
    END LOOP;
    CLOSE cursor1;
    SET done = FALSE;
    OPEN cursor2;
    loop_apus:
    LOOP
      FETCH cursor2 INTO var_iditems;
      IF done
      THEN
        LEAVE loop_apus;
      END IF;
      INSERT INTO tgriditems
            (
              codBase,
              codPresupuesto,
              revision,
              codEDT,
              codItems,
              codUnicoItems,
              codAPUGenerico,
              codAPU,
              descripcion,
              unidad,
              cantidad,
              PUnitario,
              Ptotal,
              notas,
              rendimientoHUnidad,
              nhCuadrillas,
              anidado,
              posgrid
            )
          SELECT
                  p.codBase,
                  p.codPresupuesto,
                  p.revision,
                  p.codEDT,
                  p.codItems,
                  p.codUnicoItems,
                  p.codAPUGenerico,
                  p.codAPU,
                  p.descripcion,
                  p.unidad,
                  IF((p.codAPU IS NULL) OR (p.codAPU = ''), NULL, p.cantidad)                                           AS Cantidad,
                  IF((p.codAPU IS NULL) OR (p.codAPU = ''), NULL, IF(t.id IS NULL, p.PUnitario, t.PrecioUnitarioTotal)) AS PUnitario,
                  IF
                  (t.id IS NULL, p.Ptotal, Redondea(
                    t.PrecioUnitarioTotal * p.cantidad,
                    5))                                                                                                 AS Ptotal,
                  p.notas,
                  p.rendimientoHUnidad,
                  p.nhCuadrillas,
                  p.anidado,
                  p.posgrid
          FROM
                  presupuestos_items_trabajo p
              LEFT JOIN
                presupuestos_tanteo_apus t
                  ON (
                      t.CodAPU = p.codAPU
                      AND t.codBase = p.codBase
                      AND t.codPresupuesto = p.codPresupuesto
                      AND t.revision = p.Revision
                    )
          WHERE
                  p.id = var_iditems;

    END LOOP;
    CLOSE cursor2;

  END
  $$

--
-- Create function `generaCodEDT`
--
CREATE
DEFINER = 'root'@'localhost'
FUNCTION IF NOT EXISTS generaCodEDT
  (
    EDTBase VARCHAR(255),
    IDITEM INT
  )
RETURNS CHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci
NO SQL
  BEGIN
    RETURN CONCAT(
      TRIM(EDTBase),
      '.',
      IDITEM);
  END
  $$

--
-- Create procedure `Presupuestos_ReajustaCodItems2`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS Presupuestos_ReajustaCodItems2
  (
    IN iCodBase VARCHAR(255),
    IN iCodPresupuesto VARCHAR(255),
    IN iRevision VARCHAR(255)
  )
MODIFIES SQL DATA
  BEGIN

    DECLARE v_id INT;
    DECLARE v_codEdt VARCHAR(50);
    DECLARE v_codAPU VARCHAR(50);

    DECLARE v_oldCodEDT VARCHAR(50) DEFAULT '';
    DECLARE v_newCodItem VARCHAR(50);
    DECLARE v_countEDT INT DEFAULT 1;
    DECLARE v_pos INT DEFAULT 1;

    DECLARE done INT DEFAULT 0;

    DECLARE cur CURSOR FOR
      SELECT
              id,
              TRIM(codEdt),
              TRIM(codAPU)
      FROM
              presupuestos_items_trabajo
      WHERE
              codBase = iCodBase
              AND codPresupuesto = iCodPresupuesto
              AND revision = iRevision
      ORDER BY
              posgrid ASC
      FOR UPDATE;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      RESIGNAL;
    END;

    START TRANSACTION;

    OPEN cur;

    read_loop:
    LOOP
      FETCH cur INTO v_id, v_codEdt, v_codAPU;
      IF done = 1
      THEN
        LEAVE read_loop;
      END IF;

      /* Reasignar posgrid secuencial */
      UPDATE
      presupuestos_items_trabajo
      SET
              posgrid = v_pos
      WHERE
        id = v_id;

      /* Si es APU → recalcular codItems */
      IF v_codAPU IS NOT NULL
        AND
        v_codAPU <> ''
      THEN

        SET v_newCodItem = generaCodEDT(
          v_oldCodEDT,
          v_countEDT);

        UPDATE
        presupuestos_items_trabajo
        SET
                codItems = v_newCodItem
        WHERE
          id = v_id;

        SET v_countEDT = v_countEDT + 1;

      ELSE
        /* Es cabecera EDT */
        SET v_oldCodEDT = v_codEdt;
        SET v_countEDT = 1;
      END IF;

      SET v_pos = v_pos + 1;

    END LOOP;

    CLOSE cur;

    COMMIT;

  END
  $$

--
-- Create procedure `Presupuestos_deleteItem`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS Presupuestos_deleteItem
  (
    IN icodBase VARCHAR(50),
    IN icodPresupuesto VARCHAR(50),
    IN iRevision VARCHAR(10),
    IN iPosGrid INT
  )
MODIFIES SQL DATA
  BEGIN

    DECLARE vExiste INT DEFAULT 0;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      RESIGNAL;
    END;

    START TRANSACTION;

    /* Verificar existencia y bloquear fila */
    SELECT
            COUNT(*)
            INTO vExiste
    FROM
            presupuestos_items_trabajo
    WHERE
            codBase = icodBase
            AND codPresupuesto = icodPresupuesto
            AND revision = iRevision
            AND posgrid = iPosGrid
    FOR UPDATE;

    IF vExiste = 0
    THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'ITEM_NO_EXISTE';
    END IF;

    /* Borrar */
    DELETE
    FROM
            presupuestos_items_trabajo
    WHERE
            codBase = icodBase
            AND codPresupuesto = icodPresupuesto
            AND revision = iRevision
            AND posgrid = iPosGrid;

    /* Reajustar */
    CALL Presupuestos_ReajustaCodItems2(
      icodBase,
      icodPresupuesto,
      iRevision);

    COMMIT;

  END
  $$

--
-- Create procedure `Presupuestos_CopiarMoverApu`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS Presupuestos_CopiarMoverApu
  (
    IN icodBase VARCHAR(255),
    IN icodPresupuesto VARCHAR(255),
    IN iRevision VARCHAR(255),
    IN iPosInicio INT,
    IN iPosFin INT,
    IN iTipoMovimiento INT,
    IN idUsuario VARCHAR(255)
  )
  BEGIN
    DECLARE newCodUnicoItem CHAR(50);
    DECLARE iCodAPU CHAR(50);
    DECLARE newPosItem INT;

    /* 4:copiar 5:mover */
    SET newCodUnicoItem := UUID();
    IF iPosInicio != iPosFin
    THEN
      /* Obtiene codAPU */
      SELECT
              pit.codAPU
              INTO iCodAPU
      FROM
              presupuestos_items_trabajo pit
      WHERE
              posgrid = iPosInicio
              AND codBase = icodBase
              AND codPresupuesto = icodPresupuesto
              AND revision = irevision;

      IF iPosInicio < iPosFin
      THEN
        SET newPosItem := iPosInicio;
      ELSE
        SET newPosItem := iPosInicio + 1;
      END IF;


      IF iCodAPU != ''
        AND
        iCodAPU IS NOT NULL
      THEN
        /* Abre posicion en DB */
        UPDATE
        presupuestos_items_trabajo
        SET
                posgrid = posgrid + 1
        WHERE
          posgrid > iPosFin
          AND codBase = icodBase
          AND codPresupuesto = icodPresupuesto
          AND revision = irevision;

        /* inserta nuevo apu */

        INSERT INTO presupuestos_items_trabajo
              (
                codBase,
                codPresupuesto,
                revision,
                codEdt,
                codItems,
                codUnicoItems,
                codAPUGenerico,
                codAPU,
                descripcion,
                unidad,
                cantidad,
                PUnitario,
                Ptotal,
                notas,
                rendimientoHUnidad,
                nhCuadrillas,
                anidado,
                posgrid
              )
            SELECT
                    codBase,
                    codPresupuesto,
                    revision,
                    codEdt,
                    codItems,
                    newCodUnicoItem,
                    codAPUGenerico,
                    codAPU,
                    descripcion,
                    unidad,
                    cantidad,
                    PUnitario,
                    Ptotal,
                    notas,
                    rendimientoHUnidad,
                    nhCuadrillas,
                    anidado,
                    iPosFin + 1
            FROM
                    presupuestos_items_trabajo
            WHERE
                    codBase = icodBase
                    AND codPresupuesto = icodPresupuesto
                    AND revision = iRevision
                    AND posgrid = newPosItem;

        /* en caso de move borrar item inicio */
        IF iTipoMovimiento = 5
        THEN
          CALL Presupuestos_BorrarItem(
            newPosItem,
            icodBase,
            icodPresupuesto,
            iRevision);
        END IF;

        /* Reajusta valores coditem en EDT */
        CALL Presupuestos_ReajustaCodItems2(
          icodBase,
          icodPresupuesto,
          iRevision);

      /* Guarda en Historico */
      /*  CALL Presupuestos_adicionaHistoriaMovimiento(icodBase, icodPresupuesto, iRevision, iTipoMovimiento, iCodAPU, iPosInicio, iPosFin, NULL, idUsuario); */
      END IF;
    END IF;
  END
  $$

DELIMITER ;

--
-- Create table `debug_tbl`
--
CREATE TABLE IF NOT EXISTS debug_tbl
  (
    id         INT          NOT NULL AUTO_INCREMENT,
    FechaHora  DATETIME     DEFAULT NULL,
    etiqueta   VARCHAR(255) DEFAULT NULL,
    valorDebug VARCHAR(255) DEFAULT NULL,
    PRIMARY KEY (id)
  )
ENGINE = INNODB,
AVG_ROW_LENGTH = 66,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_general_ci,
ROW_FORMAT = DYNAMIC;

DELIMITER $$

--
-- Create procedure `debug_Proc`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS debug_Proc
  (
    enabled INTEGER,
    etiqueta VARCHAR(255),
    msg VARCHAR(255)
  )
  BEGIN
    IF enabled
    THEN
      SELECT
              CONCAT(
                '** ',
                CONCAT(
                  etiqueta,
                  ': ',
                  msg)) AS '** DEBUG:';
    END IF;
    INSERT INTO debug_tbl
          (
            FechaHora,
            etiqueta,
            valorDebug
          )
    VALUES
        (
          SYSDATE(), etiqueta, msg
        );
  END
  $$

--
-- Create procedure `Presupuestos_ActualizaValorLinea`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS Presupuestos_ActualizaValorLinea
  (
    IN icodBase VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    IN icodPresupuesto VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    IN iRevision VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    IN idPresupuestoItems INTEGER,
    IN newCantidad DECIMAL(65, 10)
  )
  BEGIN
    DECLARE newTotal DECIMAL(65, 10);
    DECLARE oldPUnitario DECIMAL(65, 10);

    SELECT
            PUnitario
            INTO oldPUnitario
    FROM
            presupuestos_items_trabajo
    WHERE
            id = idPresupuestoItems
            AND codBase = icodBase
            AND codPresupuesto = icodPresupuesto
            AND revision = iRevision;

    CALL debug_Proc(
      0,
      'id',
      idPresupuestoItems);
    CALL debug_Proc(
      0,
      'newcantidad',
      newCantidad);
    CALL debug_Proc(
      0,
      'oldPrecio',
      oldPUnitario);

    SET newTotal := Redondea(
      oldPUnitario * newCantidad,
      5);

    CALL debug_Proc(
      0,
      'newtotal',
      newTotal);

    UPDATE
    presupuestos_items_trabajo
    SET
            cantidad = newCantidad,
            Ptotal = newTotal
    WHERE
      id = idPresupuestoItems
      AND codBase = icodBase
      AND codPresupuesto = icodPresupuesto
      AND revision = iRevision;
  END
  $$

--
-- Create procedure `debug_func`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS debug_func
  (
    etiqueta VARCHAR(255),
