--
-- Create table `presupuestos_datosgenerales`
--
CREATE TABLE IF NOT EXISTS presupuestos_datosgenerales
  (
    id                INT             NOT NULL AUTO_INCREMENT,
    codBase           VARCHAR(255)    DEFAULT NULL,
    codPresupuesto    VARCHAR(255)    DEFAULT NULL,
    codReferencial    VARCHAR(255)    DEFAULT NULL,
    revision          VARCHAR(255)    DEFAULT NULL,
    descripcion       VARCHAR(255)    DEFAULT NULL,
    subtotal          DECIMAL(65, 10) DEFAULT NULL,
    iva               DECIMAL(65, 10) DEFAULT NULL,
    indirectos        DECIMAL(65, 10) DEFAULT NULL,
    total             DECIMAL(65, 10) DEFAULT NULL,
    fechaCreacion     DATETIME        DEFAULT NULL,
    fechaModificacion DATETIME        DEFAULT NULL,
    ndecimales        INT             DEFAULT NULL,
    ndecimalesMoneda  INT             DEFAULT NULL,
    porcentajeIVA     DECIMAL(65, 10) DEFAULT NULL,
    activo            INT             DEFAULT NULL,
    PRIMARY KEY (id)
  )
ENGINE = INNODB,
AVG_ROW_LENGTH = 8192,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_general_ci,
ROW_FORMAT = DYNAMIC;

DELIMITER $$

--
-- Create function `DaValorAPUconTanteoConIndirectos`
--
CREATE
DEFINER = 'root'@'localhost'
FUNCTION IF NOT EXISTS DaValorAPUconTanteoConIndirectos
  (
    icodbase VARCHAR(255),
    icodPresupuesto VARCHAR(255),
    iRevision VARCHAR(255),
    icodAPU VARCHAR(255)
  )
RETURNS DECIMAL(65, 10)
READS SQL DATA
  BEGIN
    DECLARE newValorConTanteo DECIMAL(65, 10);
    DECLARE porcentajeIndirectos DECIMAL(65, 10);

    SELECT
            pd.indirectos
            INTO porcentajeIndirectos
    FROM
            presupuestos_datosgenerales pd
    WHERE
            pd.codBase = icodbase
            AND pd.codPresupuesto = icodPresupuesto
            AND pd.revision = iRevision;

    SELECT
            IF(t.id IS NULL, p.CostoDirectoTotal + Porcentaje(
              p.CostoDirectoTotal,
              porcentajeIndirectos), t.PrecioUnitarioTotal + Porcentaje(
              t.PrecioUnitarioTotal,
              porcentajeIndirectos))
            INTO newValorConTanteo
    FROM
            apus p
        LEFT JOIN
          presupuestos_tanteo_apus t
            ON (t.CodAPU = p.codAPU
                AND t.codBase = p.codBase
                AND t.codPresupuesto = icodPresupuesto
                AND t.revision = irevision)
    WHERE
            p.codBase = icodbase
            AND p.codAPU = icodAPU;

    RETURN newValorConTanteo;

  END
  $$

--
-- Create procedure `updatePresupuestosDatosGenerales`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS updatePresupuestosDatosGenerales
  (
    iCodPresupuesto VARCHAR(50),
    iRevision VARCHAR(50),
    iCodBase VARCHAR(50)
  )
  BEGIN
    SELECT
            @totalPresupuesto := SUM(pItems.PTotal)
    FROM
            presupuestos_items pItems
    WHERE
            pItems.codPresupuesto = iCodPresupuesto
            AND pItems.revision = iRevision
            AND pItems.codBase = iCodBase
            AND pItems.codAPU != '';

    UPDATE
    presupuestos_datosgenerales datos
    SET
            datos.subtotal = @totalPresupuesto,
            datos.iva = Porcentaje(
              @totalPresupuesto,
              datos.porcentajeIVA),
            datos.total = datos.subtotal + datos.iva,
            datos.fechaModificacion = SYSDATE()
    WHERE
      datos.codPresupuesto = iCodPresupuesto
      AND datos.revision = iRevision
      AND datos.codBase = iCodBase;
  END
  $$

--
-- Create procedure `UpdateDatosGenerales`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS UpdateDatosGenerales
  (
    iCodBase VARCHAR(50),
    iCodPresupuesto VARCHAR(50),
    iRevision VARCHAR(50)
  )
  BEGIN
    SELECT
            @subtotal := SUM(p.Ptotal)
    FROM
            presupuestos_items p
    WHERE
            p.codBase = iCodBase
            AND p.codPresupuesto = iCodPresupuesto
            AND p.revision = iRevision
            AND p.codAPU != '';

    UPDATE
    presupuestos_datosgenerales t
    SET
            t.subtotal = @subtotal,
            t.iva = Porcentaje(
              @subtotal,
              t.porcentajeIVA),
            t.total = @subtotal + t.iva,
            t.FechaModificacion = SYSDATE()
    WHERE
      t.codBase = iCodBase
      AND t.codPresupuesto = iCodPresupuesto
      AND t.revision = iRevision;
  END
  $$

--
-- Create procedure `PrecioAddAPUPresupuesto`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS PrecioAddAPUPresupuesto
  (
    IN icodbase VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    IN icodAPU VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    IN iCodPresupuesto VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    IN iRevision VARCHAR(10) CHARSET utf8mb4 COLLATE utf8mb4_general_ci,
    IN iCalCulaConIndirecto INT(1),
    IN iPrecision INT,
    OUT iPrecioAPU DECIMAL(65, 10)
  )
  BEGIN
    DECLARE indirectos DECIMAL(65, 10);
    DECLARE VTotal DECIMAL(65, 10);
    DECLARE VResultado DECIMAL(65, 10);
    DECLARE done INTEGER;
    DECLARE anidado INT(1);
    DECLARE var_idUnicoRecurso VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE cur_Anidado CURSOR FOR
      SELECT
              apu0.idUnicoRecurso
      FROM
              apus_items apu0
      WHERE
              apu0.CodAPU = iCodAPU
              AND apu0.codBase = icodBase;
    DECLARE CONTINUE HANDLER FOR NOT FOUND
    SET done = TRUE;
    SELECT
            datos.indirectos
            INTO indirectos
    FROM
            presupuestos_datosgenerales datos
    WHERE
            datos.codBase = icodBase
            AND datos.codPresupuesto = iCodPresupuesto
            AND datos.revision = iRevision;
    SELECT
            anidado
            INTO anidado
    FROM
            apus apu1
    WHERE
            apu1.codBase = icodBase
            AND apu1.CodAPU = icodAPU;

    SET VResultado := 0;

    SET VTotal := 0;
    CALL debug_Proc(
      FALSE,
      'Anidado',
      anidado);


    IF anidado = 1
    THEN
      OPEN cur_Anidado;
      loop_cur_anidado:
      LOOP
        FETCH cur_Anidado INTO var_idUnicoRecurso;
        IF
          done
        THEN
          LEAVE loop_cur_anidado;

        END IF;
        SELECT
                IF
                (
                t1.idUnicoRecurso IS NULL,  /* reajustar la entrada a valor de tanteo */
                itm.precio * itm.CantidadUnidad * itm.Rendimiento,
                t1.Precio * itm.CantidadUnidad * itm.Rendimiento
                )
                INTO VTotal
        FROM
                apus_items itm
            INNER JOIN
              presupuestos_tanteo_recursos t1
                ON (
                    t1.codBase = itm.codBase
                    AND t1.idUnicoRecurso = itm.idUnicoRecurso
                    AND t1.codPresupuesto = iCodPresupuesto
                    AND t1.revision = iRevision
                  )
        WHERE
                itm.CodAPU = iCodAPU
                AND itm.codBase = iCodBase
                AND itm.idUnicoRecurso = var_idUnicoRecurso
        LIMIT 1;
        SET VTotal = redondea(
          VTotal,
          iPrecision);
        SET VResultado := VResultado + VTotal;
        CALL debug_Proc(
          FALSE,
          'Valor Recurso',
          VTotal);

      END LOOP loop_cur_anidado;
      CLOSE cur_anidado;
    ELSE

      SELECT
              PrecioUnitarioTotal
              INTO VResultado
      FROM
              apus
      WHERE
              CodAPU = icodAPU
              AND codBase = iCodBase;

      SET VResultado = redondea(
        VResultado,
        iPrecision);
    END IF;

    SET iPrecioAPU := VResultado + (iCalCulaConIndirecto * redondea(
      Porcentaje(
        VResultado,
        indirectos),
      iPrecision));
    CALL debug_proc(
      FALSE,
      'Valor APU: ',
      iPrecioAPU);

  END
  $$

--
-- Create procedure `exportar_Presupuestos_DatosGenerales`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS exportar_Presupuestos_DatosGenerales
  (
    IN iCodBase VARCHAR(255),
    IN iCodPresupuesto VARCHAR(255),
    IN iRevision INT,
    IN id_Exports VARCHAR(255)
  )
  BEGIN
    DECLARE done INTEGER;
    DECLARE v_id INTEGER;
    DECLARE cur1 CURSOR FOR
      SELECT
              pd.id
      FROM
              presupuestos_datosgenerales pd
      WHERE
              pd.codBase = iCodBase
              AND pd.codPresupuesto = iCodPresupuesto
              AND pd.revision = iRevision;
    DECLARE CONTINUE HANDLER FOR NOT FOUND
    SET done = TRUE;
    /* ------------ INICIO ---------- -- */
    SET done := FALSE;
    OPEN cur1;
    loop_cur1:
    LOOP
      FETCH cur1 INTO v_id;
      IF done
      THEN
        LEAVE loop_cur1;
      END IF;
      INSERT INTO presupuestos_datosgenerales_exports
            (
              codBase,
              codPresupuesto,
              codReferencial,
              revision,
              descripcion,
              subtotal,
              iva,
              indirectos,
              total,
              fechaCreacion,
              fechaModificacion,
              ndecimales,
              ndecimalesMoneda,
              porcentajeIVA,
              activo,
              id_exports
            )
          SELECT
                  codBase,
                  codPresupuesto,
                  codReferencial,
                  revision,
                  descripcion,
                  subtotal,
                  iva,
                  indirectos,
                  total,
                  fechaCreacion,
                  fechaModificacion,
                  ndecimales,
                  ndecimalesMoneda,
                  porcentajeIVA,
                  activo,
                  id_Exports
          FROM
                  presupuestos_datosgenerales
          WHERE
                  id = v_id;

    END LOOP;
    CLOSE cur1;
  END
  $$

--
-- Create procedure `cuadrePresupuestosItems`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS cuadrePresupuestosItems
  (
    IN icodBase VARCHAR(255),
    IN iCodPresupuesto VARCHAR(255),
    IN iRevision VARCHAR(255)
  )
  BEGIN
    DECLARE done INTEGER;
    DECLARE v_ID INTEGER;
    DECLARE v_codapu CHAR(50);
    DECLARE v_indirectos DECIMAL(65, 10);
    DECLARE v_costoItem DECIMAL(65, 10);
    DECLARE v_cantidad DECIMAL(65, 10);
    DECLARE v_Ndecimales DECIMAL(65, 10);
    DECLARE v_PUnitario DECIMAL(65, 10);
    DECLARE v_PTotal DECIMAL(65, 10);
    DECLARE cur_Pitems CURSOR FOR
      SELECT
              pi.id,
              pi.codAPU,
              pi.cantidad
      FROM
              presupuestos_items pi
      WHERE
              pi.codBase = icodBase
              AND pi.codPresupuesto = iCodPresupuesto
              AND pi.revision = iRevision
              AND (   pi.codAPU IS NOT NULL
                      AND TRIM(pi.codAPU) <> '')
      ORDER BY
              pi.posgrid ASC;
    DECLARE CONTINUE HANDLER FOR NOT FOUND
    SET done = TRUE;

    /* Inicio -- */
    SET done := FALSE;
    SELECT
            pd.indirectos,
            pd.ndecimalesMoneda
            INTO v_indirectos, v_Ndecimales
    FROM
            presupuestos_datosgenerales pd
    WHERE
            pd.codBase = icodBase
            AND pd.codPresupuesto = iCodPresupuesto
            AND pd.revision = iRevision;
    OPEN cur_Pitems;
    cur_Pitems:
    LOOP
      FETCH cur_Pitems INTO v_id, v_codapu, v_cantidad;
      IF done
      THEN
        LEAVE cur_Pitems;
      END IF;
      SELECT
              SUM(ai.total)
              INTO v_costoItem
      FROM
              apus_items ai
      WHERE
              ai.CodAPU = v_codapu
              AND ai.codBase = icodBase;

      SET v_PUnitario := v_costoItem + Redondea(
        porcentaje(
          v_costoItem,
          v_indirectos),
        v_Ndecimales);
      SET v_PTotal := v_PUnitario * v_cantidad;

      UPDATE
      presupuestos_items pi
      SET
              pi.PUnitario = v_PUnitario,
              pi.Ptotal = v_PTotal
      WHERE
        pi.id = v_ID;

    END LOOP;
  END
  $$

--
-- Create procedure `actualizarPresupuestosDatosGenerales`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS actualizarPresupuestosDatosGenerales
  (
    iCodPresupuesto VARCHAR(50),
    iRevision VARCHAR(50),
    iCodBase VARCHAR(50)
  )
  BEGIN
    DECLARE totalPresupuesto DECIMAL(65, 10);

    SELECT
            @totalPresupuesto := SUM(pItems.Ptotal)
    FROM
            presupuestos_items pItems
    WHERE
            pItems.codPresupuesto = iCodPresupuesto
            AND pItems.revision = iRevision
            AND pItems.codBase = iCodBase
            AND pItems.codAPU != '';

    IF @totalPresupuesto IS NULL
    THEN
      SET totalPresupuesto := 0;
    ELSE
      SET totalPresupuesto := @totalPresupuesto;
    END IF;

    UPDATE
    presupuestos_datosgenerales datos
    SET
            datos.subtotal = totalPresupuesto,
            datos.iva = Porcentaje(
              totalPresupuesto,
              datos.porcentajeIVA),
            datos.total = datos.subtotal + datos.iva,
            datos.fechaModificacion = SYSDATE()
    WHERE
      datos.codPresupuesto = iCodPresupuesto
      AND datos.revision = iRevision
      AND datos.codBase = iCodBase;
  END
  $$

DELIMITER ;

--
-- Create table `presupuestos_edt`
--
CREATE TABLE IF NOT EXISTS presupuestos_edt
  (
    id                      INT          NOT NULL AUTO_INCREMENT,
    codBase                 VARCHAR(255) NOT NULL,
    codPresupuesto          VARCHAR(255) NOT NULL,
    Revision                VARCHAR(255) NOT NULL,
    CodEDT                  VARCHAR(255) NOT NULL,
    Descripcion             VARCHAR(255) NOT NULL,
    Responsable             VARCHAR(255) DEFAULT NULL,
    Definicion              TEXT         DEFAULT NULL,
    puntero                 INT          DEFAULT NULL,
    codUnicoItemPresupuesto VARCHAR(255) DEFAULT NULL,
    PRIMARY KEY (id)
  )
ENGINE = INNODB,
AVG_ROW_LENGTH = 2340,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_general_ci,
ROW_FORMAT = DYNAMIC;

DELIMITER $$

--
-- Create function `EstaItemEnEDT`
--
CREATE
DEFINER = 'root'@'localhost'
FUNCTION IF NOT EXISTS EstaItemEnEDT
  (
    iCodBase VARCHAR(255),
    iCodPresupuesto VARCHAR(255),
    iRevision VARCHAR(255),
    EDTdePertenencia VARCHAR(255)
  )
RETURNS INT(11)
READS SQL DATA
  BEGIN
    DECLARE v_EDTBase VARCHAR(255);
    DECLARE v_puntero INTEGER;
    SET v_EDTBase := REVERSE(
      EDTdePertenencia);
    SET v_puntero := LOCATE(
      '.',
      v_EDTBase);
    SET v_EDTBase := SUBSTR(v_EDTBase, v_puntero + 1, LENGTH(
      v_EDTBase));
    SET v_EDTBase := REVERSE(
      v_EDTBase);
    SELECT
            SUM(pe.id)
            INTO v_puntero
    FROM
            presupuestos_edt pe
    WHERE
            pe.codBase = iCodBase
            AND pe.codPresupuesto = iCodPresupuesto
            AND pe.Revision = iRevision
            AND pe.CodEDT = v_EDTBase;
    IF v_puntero > 0
    THEN
      RETURN 1;
    ELSE
      RETURN 0;
    END IF;
  END
  $$

--
-- Create procedure `EDT_SincronizaEDTPresupuesto`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS EDT_SincronizaEDTPresupuesto
  (
    IN iCodBase VARCHAR(255),
    IN iCodPresupuesto VARCHAR(255),
    IN iRevision VARCHAR(255)
  )
  BEGIN

    /* =========================
       VARIABLES
       ========================= */
    DECLARE v_done INT DEFAULT 0;
    DECLARE v_ExisteEDT INT DEFAULT 0;
    DECLARE v_id INT;
    DECLARE v_codEDT VARCHAR(50);
    DECLARE v_codUnicoItems VARCHAR(50);
    DECLARE v_posgrid INT;
    DECLARE v_ultimoValorPosGrid INT DEFAULT 0;

    /* =========================
       CURSORES (ANTES DE HANDLERS)
       ========================= */

    DECLARE cur1 CURSOR FOR
      SELECT
              pe.id,
              pe.CodEDT,
              pe.codUnicoItemPresupuesto,
              pit.posgrid
      FROM
              presupuestos_edt pe
          LEFT JOIN
            presupuestos_items_trabajo pit
                ON pit.codBase = pe.codBase
                AND pit.codPresupuesto = pe.codPresupuesto
                AND pit.revision = pe.Revision
                AND pit.codEdt = pe.CodEDT
      WHERE
              pe.codBase = iCodBase
              AND pe.codPresupuesto = iCodPresupuesto
              AND pe.Revision = iRevision
      ORDER BY
              pe.CodEDT;

    DECLARE cur2 CURSOR FOR
      SELECT
              pit.id,
              pit.codItems
      FROM
              presupuestos_items_trabajo pit
      WHERE
              pit.codBase = iCodBase
              AND pit.codPresupuesto = iCodPresupuesto
              AND pit.revision = iRevision
              AND pit.codAPU IS NOT NULL
      ORDER BY
              pit.posgrid;

    DECLARE cur3 CURSOR FOR
      SELECT
              pite.id
      FROM
              presupuestos_items_trabajo_edt pite
      WHERE
              pite.codBase = iCodBase
              AND pite.codPresupuesto = iCodPresupuesto
              AND pite.revision = iRevision
              AND pite.posgrid IS NULL
      ORDER BY
              pite.codAPU DESC;

    /* =========================
       HANDLERS (DESPUÉS DE CURSORES)
       ========================= */

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      RESIGNAL;
    END;

    /* =========================
       TRANSACCIÓN
       ========================= */
    START TRANSACTION;

    /* 1) Limpiar tabla temporal */
    DELETE
    FROM
            presupuestos_items_trabajo_edt
    WHERE
            codBase = iCodBase
            AND codPresupuesto = iCodPresupuesto
            AND revision = iRevision;

    /* 2) Volcar EDT */
    SET v_done = 0;
    OPEN cur1;

    loop1:
    LOOP
      FETCH cur1 INTO v_id, v_codEDT, v_codUnicoItems, v_posgrid;
      IF v_done = 1
      THEN
        LEAVE loop1;
      END IF;

      INSERT INTO presupuestos_items_trabajo_edt
            (
              codBase,
              codPresupuesto,
              revision,
              codEdt,
              descripcion,
              codUnicoItems,
              posgrid
            )
          SELECT
                  pe.codBase,
                  pe.codPresupuesto,
                  pe.Revision,
                  pe.CodEDT,
                  pe.Descripcion,
                  pe.codUnicoItemPresupuesto,
                  v_posgrid
          FROM
                  presupuestos_edt pe
          WHERE
                  pe.id = v_id;

    END LOOP;

    CLOSE cur1;

    /* 3) Insertar Items */
    SET v_done = 0;
    OPEN cur2;

    loop2:
    LOOP
      FETCH cur2 INTO v_id, v_codEDT;
      IF v_done = 1
      THEN
        LEAVE loop2;
      END IF;

      SET v_ExisteEDT = IFNULL(
        EstaItemEnEDT(
          iCodBase,
          iCodPresupuesto,
          iRevision,
          v_codEDT),
        0);

      IF v_ExisteEDT = 1
      THEN
        INSERT INTO presupuestos_items_trabajo_edt
              (
                codBase,
                codPresupuesto,
                revision,
                codEdt,
                codItems,
                codUnicoItems,
                codAPUGenerico,
                codAPU,
                descripcion,
                unidad,
                cantidad,
                PUnitario,
                Ptotal,
                notas,
                rendimientoHUnidad,
                nhCuadrillas,
                anidado,
                posgrid
              )
            SELECT
                    codBase,
                    codPresupuesto,
                    revision,
                    codEdt,
                    codItems,
                    codUnicoItems,
                    codAPUGenerico,
                    codAPU,
                    descripcion,
                    unidad,
                    cantidad,
                    PUnitario,
                    Ptotal,
                    notas,
                    rendimientoHUnidad,
                    nhCuadrillas,
                    anidado,
                    posgrid
            FROM
                    presupuestos_items_trabajo
            WHERE
                    id = v_id;
      END IF;

    END LOOP;

    CLOSE cur2;

    /* 4) Reasignar posgrid */
    SELECT
            IFNULL(
              MAX(posgrid),
              0)
            INTO v_ultimoValorPosGrid
    FROM
            presupuestos_items_trabajo_edt
    WHERE
            codBase = iCodBase
            AND codPresupuesto = iCodPresupuesto
            AND revision = iRevision;

    SET v_done = 0;
    OPEN cur3;

    loop3:
    LOOP
      FETCH cur3 INTO v_id;
      IF v_done = 1
      THEN
        LEAVE loop3;
      END IF;

      SET v_ultimoValorPosGrid = v_ultimoValorPosGrid + 1;

      UPDATE
      presupuestos_items_trabajo_edt
      SET
              posgrid = v_ultimoValorPosGrid
      WHERE
        id = v_id;

    END LOOP;

    CLOSE cur3;

    /* 5) Reemplazar tabla final */
    DELETE
    FROM
            presupuestos_items_trabajo
    WHERE
            codBase = iCodBase
            AND codPresupuesto = iCodPresupuesto
            AND revision = iRevision;

    INSERT INTO presupuestos_items_trabajo
        SELECT
                *
        FROM
                presupuestos_items_trabajo_edt
        WHERE
                codBase = iCodBase
                AND codPresupuesto = iCodPresupuesto
                AND revision = iRevision;

    COMMIT;

  END
  $$

DELIMITER ;

