DELIMITER $$

--
-- Create function `NombreAnidado`
--
CREATE
DEFINER = 'root'@'localhost'
FUNCTION IF NOT EXISTS NombreAnidado
  (
    CodAPU VARCHAR(50)
  )
RETURNS VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci
NO SQL
  BEGIN
    RETURN CONCAT(
      'APU: ',
      CodAPU);
  END
  $$

--
-- Create procedure `updatePresupuestosItems`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS updatePresupuestosItems
  (
    iCodAPU VARCHAR(50),
    iCodBase VARCHAR(50),
    iCodPresupuesto VARCHAR(50),
    iRevision VARCHAR(10)
  )
  BEGIN
    /* Actualiza desde apusitem y se propaga por el resto de tablas  */
    SELECT
            @newCostoDirectoTotal := SUM(itm.Total)
    FROM
            apus_items itm
    WHERE
            itm.CodAPU = iCodAPU
            AND itm.codBase = iCodBase;

    SELECT
            @indirectos := datos.indirectos
    FROM
            presupuestos_datosgenerales datos
    WHERE
            datos.codBase = pitems.codBase
            AND datos.codPresupuesto = iCodPresupuesto
            AND datos.revision = iRevision;

    /* Actualizacion de apus  */
    UPDATE
    apus
    SET
            CostoDirectoTotal = @newcostoDirectoTotal,

            CostoIndirectoTotal = Porcentaje(
              @newcostoDirectoTotal,
              @indirectos),
            PrecioUnitarioTotal = CostoDirectoTotal + CostoIndirectoTotal
    WHERE
      CodAPU = iCodAPU
      AND codBase = icodBase;

    /* Actualizacion de Recursos  */
    UPDATE
    recursos recurso
LEFT JOIN
  apus_items items
    ON (items.codBase = iCodBase
        AND items.CodAPU = iCodAPU)
    SET
            recurso.Descripcion = items.Descripcion,
            recurso.unidad = items.Unidad,
            recurso.precio = items.Precio,
            recurso.preciolocal = items.Precio,
            ultimaModificacion = SYSDATE()
    WHERE
      recurso.codBase = iCodBase
      AND recurso.idUnico = items.idUnicoRecurso;

    /* Actualiza Presupuestos_items  */
    UPDATE
    presupuestos_items pItems
LEFT JOIN
  apus apu
    ON (apu.CodAPU = icodAPU
        AND apu.codBase = icodBase)


    SET
            pitems.descripcion = apu.Descripcion,
            pitems.unidad = apu.Unidad,
            pitems.PUnitario = apu.CostoDirectoTotal + Porcentaje(
              apu.CostoDirectoTotal,
              @indirectos),
            pitems.Ptotal = pitems.PUnitario * Pitems.cantidad
    WHERE
      pitems.codAPU = iCodAPU
      AND pitems.codBase = icodBase
      AND pitems.codPresupuesto = datos.codPresupuesto
      AND pitems.revision = datos.revision;


    /* Actualizar Apu como Recurso  */
    UPDATE
    recursos Arecurso
LEFT JOIN
  apus Napu
    ON (Napu.CodAPU = iCodAPU
        AND Napu.codBase = Arecurso.codBase)
    SET
            Arecurso.Descripcion = Napu.Descripcion,
            Arecurso.unidad = Napu.Unidad,
            Arecurso.precio = Napu.CostoDirectoTotal,
            Arecurso.precioLocal = Napu.CostoDirectoTotal,
            Arecurso.ultimaModificacion = SYSDATE()
    WHERE
      Arecurso.especificaciones = NombreAnidado(
        iCodAPU)
      AND Arecurso.codBase = icodBase;

    /* Actualizar tanteo  */
    DELETE
    FROM
            presupuestos_tanteo_apus tanteo
    WHERE
            tanteo.codBase = iCodBase
            AND tanteo.CodAPU = icodAPU;

    /* Actualizar items tanteo */
    DELETE
    FROM
            presupuestos_tanteo_recursos Rtanteo
    WHERE
            Rtanteo.codBase = iCodBase
            AND Rtanteo.CodAPU = icodAPU;

  END
  $$

DELIMITER ;

