--
-- Create function `incremetnaCodItems`
--
CREATE
DEFINER = 'root'@'localhost'
FUNCTION IF NOT EXISTS incremetnaCodItems
  (
    oldCodItems VARCHAR(255)
  )
RETURNS CHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci
NO SQL
  BEGIN
    DECLARE v_i INTEGER;
    DECLARE v_j INTEGER;
    DECLARE v_tmp CHAR(50);
    SET v_tmp := REVERSE(
      oldCodItems);
    SET v_i := LOCATE(
      '.',
      v_tmp);
    SET v_j := SUBSTR(v_tmp, 1, v_i);
    SET v_j := REVERSE(
      v_j);
    SET v_j := v_j + 1;
    SET v_tmp := SUBSTR(v_tmp, v_i, LENGTH(
      v_tmp));
    SET v_tmp := REVERSE(
      v_tmp);
    SET v_tmp := CONCAT(
      v_tmp,
      v_j);
    RETURN v_tmp;
  END
  $$

DELIMITER ;

