DELIMITER $$

--
-- Create procedure `Presupuestos_Pareto_Capitulos`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS Presupuestos_Pareto_Capitulos
  (
    IN icodBase VARCHAR(255),
    IN icodPresupuesto VARBINARY(255),
    IN iRevision VARBINARY(255)
  )
  BEGIN
    DECLARE done INTEGER;
    DECLARE nItems INTEGER;
    DECLARE var_iditems INTEGER;
    DECLARE var_cadenaEDT CHAR(50);
    DECLARE cursor1 CURSOR FOR
      SELECT
              pit.id
      FROM
              presupuestos_items_trabajo pit
      WHERE
              (       pit.codAPU = ''
                      OR pit.codAPU IS NULL)
              AND pit.codBase = icodBase
              AND pit.codPresupuesto = icodPresupuesto
              AND pit.revision = iRevision
      ORDER BY
              pit.posgrid ASC;

    DECLARE cursor2 CURSOR FOR
      SELECT
              pit2.codEDT
      FROM
              tgriditems_edt pit2
      WHERE
              pit2.codBase = icodBase
              AND pit2.codPresupuesto = icodPresupuesto
              AND pit2.revision = iRevision
      ORDER BY
              pit2.posgrid ASC;

    DECLARE CONTINUE HANDLER FOR NOT FOUND
    SET done = TRUE;

    DELETE
    FROM
            tgriditems tg
    WHERE
            tg.codBase = icodbase
            AND tg.codPresupuesto = icodpresupuesto
            AND tg.revision = irevision;

    DELETE
    FROM
            tgriditems_edt tg
    WHERE
            tg.codBase = icodbase
            AND tg.codPresupuesto = icodpresupuesto
            AND tg.revision = irevision;

    SET done = FALSE;
    OPEN cursor1;
    loop_edt:
    LOOP
      FETCH cursor1 INTO var_iditems;
      IF done
      THEN
        LEAVE loop_edt;
      END IF;
      INSERT INTO tgriditems
            (
              codBase,
              codPresupuesto,
              revision,
              codEDT,
              codItems,
              codUnicoItems,
              codAPUGenerico,
              codAPU,
              descripcion,
              unidad,
              cantidad,
              PUnitario,
              Ptotal,
              notas,
              rendimientoHUnidad,
              nhCuadrillas,
              anidado,
              posgrid
            )
          SELECT
                  codBase,
                  codPresupuesto,
                  revision,
                  codEDT,
                  codItems,
                  codUnicoItems,
                  codAPUGenerico,
                  codAPU,
                  descripcion,
                  unidad,
                  '',
                  '',
                  Ptotal,
                  notas,
                  rendimientoHUnidad,
                  nhCuadrillas,
                  anidado,
                  posgrid
          FROM
                  presupuestos_items_trabajo
          WHERE
                  id = var_iditems
          ORDER BY
                  posgrid;
      INSERT INTO tgriditems_edt
            (
              codBase,
              codPresupuesto,
              revision,
              codEDT,
              codItems,
              codUnicoItems,
              codAPUGenerico,
              codAPU,
              descripcion,
              unidad,
              cantidad,
              PUnitario,
              Ptotal,
              notas,
              rendimientoHUnidad,
              nhCuadrillas,
              anidado,
              posgrid
            )
          SELECT
                  codBase,
                  codPresupuesto,
                  revision,
                  codEDT,
                  codItems,
                  codUnicoItems,
                  codAPUGenerico,
                  codAPU,
                  descripcion,
                  unidad,
                  '',
                  '',
                  Ptotal,
                  notas,
                  rendimientoHUnidad,
                  nhCuadrillas,
                  anidado,
                  posgrid
          FROM
                  presupuestos_items_trabajo
          WHERE
                  id = var_iditems
          ORDER BY
                  posgrid;
    END LOOP loop_edt;
    CLOSE cursor1;

    /* Parte adiciona Items */
    SET done = FALSE;
    OPEN cursor2;
    loop_apus:
    LOOP
      FETCH cursor2 INTO var_cadenaEDT;
      IF done
      THEN
        LEAVE loop_apus;
      END IF;
      SELECT
              COUNT(*)
              INTO nItems
      FROM
              presupuestos_items_trabajo pit
      WHERE
              pit.codBase = icodbase
              AND pit.codPresupuesto = icodPresupuesto
              AND pit.revision = irevision
              AND pit.codItems LIKE CONCAT(
                var_cadenaEDT,
                '.%');
      SET nItems := Porcentaje(
        nItems,
        20);
      SET nItems := TRUNCATE(
        nItems,
        0);
      SET nItems := IF(nItems = 0, 1, nItems);
      CALL Presupuestos_Pareto_guardaItems(
        icodBase,
        icodPresupuesto,
        iRevision,
        nItems,
        CONCAT(
          var_cadenaEDT,
          '.%'));
    END LOOP loop_apus;
    CLOSE cursor2;

  END
  $$

DELIMITER ;

