--
-- Create procedure `Presupuestos_NotasCopiarEnAPUS`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS Presupuestos_NotasCopiarEnAPUS
  (
    IN iCodBase VARCHAR(255),
    IN iCodPresupuesto VARCHAR(255),
    IN iRevision VARCHAR(255),
    IN iNota LONGTEXT
  )
  BEGIN
    DECLARE oldText LONGTEXT;
    DECLARE var_idAPUS INTEGER;
    DECLARE done INTEGER;
    DECLARE cur_APUS CURSOR FOR
      SELECT
              id
      FROM
              presupuestos_notas pn
      WHERE
              pn.codBase = iCodBase
              AND pn.codPresupuesto = iCodPresupuesto
              AND pn.Revision = iRevision;

    DECLARE CONTINUE HANDLER FOR NOT FOUND
    SET done = TRUE;
    SET done := FALSE;
    OPEN cur_APUS;
    loop_apus:
    LOOP
      FETCH cur_APUS INTO var_idAPUS;
      IF done
      THEN
        LEAVE loop_apus;
      END IF;
      SELECT
              pn.notas
              INTO oldText
      FROM
              presupuestos_notas pn
      WHERE
              pn.id = var_idAPUS;
      SET oldText := CONCAT(
        oldText,
        iNota);
      UPDATE
      presupuestos_notas pn
      SET
              pn.notas = oldText,
              pn.fechahora = SYSDATE()
      WHERE
        pn.id = var_idAPUS;
    END LOOP;
    CLOSE cur_APUS;
  END
  $$

--
-- Create function `devuelveEDTBase`
--
CREATE
DEFINER = 'root'@'localhost'
FUNCTION IF NOT EXISTS devuelveEDTBase
  (
    datosInicio VARCHAR(255),
    tipoFuncion INTEGER
  )
RETURNS CHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci
NO SQL
  BEGIN
    /*tipofuncion ->  0: es CODEDT, 1: es CODITEMS */
    DECLARE v_tmp CHAR(255);
    DECLARE v_i INTEGER;

    SET v_tmp := REVERSE(
      datosInicio);
    SET v_i := LOCATE(
      '.',
      v_tmp);
    IF tipoFuncion = 0
    THEN
      SET v_tmp := REVERSE(
        v_tmp);
      SET v_tmp := CONCAT(
        v_tmp,
        '.%');
    ELSE
      SET v_tmp := SUBSTR(v_tmp, v_i, LENGTH(
        v_tmp));
      SET v_tmp := REVERSE(
        v_tmp);
      SET v_tmp := CONCAT(
        v_tmp,
        '%');
    END IF;
    RETURN v_tmp;
  END
  $$

--
-- Create procedure `presupuestos_reajustaCodItems`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS presupuestos_reajustaCodItems
  (
    IN cPosGrid INT,
    IN iCodBase VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
    IN icodPresupuesto VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
    IN iRevision VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci
  )
  BEGIN
    DECLARE fPosgrid INTEGER;
    DECLARE done INTEGER;
    DECLARE var_PosGrid INTEGER;
    DECLARE valor_busqueda CHAR(50);
    DECLARE v_coditems CHAR(50);
    DECLARE newCodItems CHAR(50);
    DECLARE cur CURSOR FOR
      SELECT
              posgrid
      FROM
              presupuestos_items_trabajo pit
      WHERE
              pit.posgrid > cPosGrid
              AND pit.posgrid < fPosgrid + 1
              AND pit.codBase = iCodbase
              AND pit.codPresupuesto = icodPresupuesto
              AND pit.revision = iRevision
      ORDER BY
              pit.posgrid ASC;

    DECLARE CONTINUE HANDLER FOR NOT FOUND
    SET done = TRUE;

    SELECT
            pit4.codItems
            INTO v_coditems
    FROM
            presupuestos_items_trabajo pit4
    WHERE
            pit4.posgrid = cPosGrid;

    IF v_coditems != ''
    THEN
      SET newCodItems := v_coditems;
      SET valor_busqueda := devuelveEDTBase(
        v_coditems,
        1);
    ELSE
      SELECT
              pit5.CodEdt
              INTO v_coditems
      FROM
              presupuestos_items_trabajo pit5
      WHERE
              pit5.posgrid = cPosGrid;
      SET valor_busqueda := devuelveEDTBase(
        v_coditems,
        0);
      SET newCodItems := REPLACE(
        valor_busqueda,
        '%',
        '0');
    END IF;

    SELECT
            pit2.posgrid
            INTO fPosgrid
    FROM
            presupuestos_items_trabajo pit2
    WHERE
            pit2.codItems LIKE valor_busqueda
            AND pit2.codBase = icodbase
            AND pit2.codpresupuesto = icodPResupuesto
            AND pit2.revision = iRevision
    ORDER BY
            pit2.posgrid DESC LIMIT 1;

    OPEN cur;

    loop_cur:
    LOOP
      FETCH cur INTO var_PosGrid;
      IF done
      THEN
        LEAVE loop_cur;
      END IF;

      SET newCodItems := incremetnaCodItems(
        newCodItems);

      UPDATE
      presupuestos_items_trabajo pit3
      SET
              pit3.codItems = newCodItems
      WHERE
        posgrid = var_PosGrid;
    END LOOP;
    CLOSE cur;
  END
  $$

--
-- Create procedure `Presupuestos_EstaAPUenCapitulo`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS Presupuestos_EstaAPUenCapitulo
  (
    IN iCodBase VARCHAR(255),
    IN iCodPresupuesto VARCHAR(255),
    IN iRevision VARCHAR(255),
    IN iPosItemInicio INT,
    IN iPosItemFin INT,
    OUT estado VARCHAR(50)
  )
  BEGIN
    DECLARE cadenaBusqueda CHAR(50);
    DECLARE iCodAPU CHAR(50);

    SELECT
            pit.codAPU
            INTO iCodAPU
    FROM
            presupuestos_items_trabajo pit
    WHERE
            pit.codBase = iCodBase
            AND pit.codPresupuesto = iCodPresupuesto
            AND pit.revision = iRevision
            AND pit.posgrid = iPosItemInicio;

    SELECT
            IF(pit.codAPU IS NULL, devuelveEDTBase(
              pit.codEdt,
              0), devuelveEDTBase(
              pit.codItems,
              1))
            INTO cadenaBusqueda
    FROM
            presupuestos_items_trabajo pit
    WHERE
            pit.codBase = iCodBase
            AND pit.codPresupuesto = iCodPresupuesto
            AND pit.revision = iRevision
            AND pit.posgrid = iPosItemFin;

    SELECT
            pit.codAPU
            INTO estado
    FROM
            presupuestos_items_trabajo pit
    WHERE
            pit.codBase = iCodBase
            AND pit.codPresupuesto = iCodPresupuesto
            AND pit.revision = iRevision
            AND pit.codAPU = iCodAPU
            AND pit.codItems LIKE cadenaBusqueda;

  END
  $$

DELIMITER ;

