--
-- Create table `recursos_contadores`
--
CREATE TABLE IF NOT EXISTS recursos_contadores
  (
    codBase          VARCHAR(255) NOT NULL,
    codCategoriaBase INT          NOT NULL,
    codSubCategoria  INT          NOT NULL,
    ultimoCodRecurso INT          NOT NULL,
    PRIMARY KEY (codBase, codCategoriaBase, codSubCategoria)
  )
ENGINE = INNODB,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_general_ci,
ROW_FORMAT = DYNAMIC;

DELIMITER $$

--
-- Create procedure `mueveRecurso_mysql`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS mueveRecurso_mysql
  (
    IN p_codBase VARCHAR(255),
    IN p_codCategoriaBase INT,
    IN p_nuevaSubCategoria INT,
    IN p_idUnicoRecurso VARCHAR(255)
  )
  BEGIN
    DECLARE v_newCodRecurso INT;
    DECLARE v_codRecursoCompleto VARCHAR(255);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Error en mueveRecurso_mysql';
    END;

    START TRANSACTION;

    -- 1️⃣ asegurar contador
    INSERT INTO recursos_contadores
          (
            codBase,
            codCategoriaBase,
            codSubCategoria,
            ultimoCodRecurso
          )
    VALUES
        (
          p_codBase, p_codCategoriaBase, p_nuevaSubCategoria, 0
        )
    ON DUPLICATE KEY UPDATE
    ultimoCodRecurso = ultimoCodRecurso;

    -- 2️⃣ incrementar contador (lock implícito)
    UPDATE
    recursos_contadores
    SET
            ultimoCodRecurso = ultimoCodRecurso + 1
    WHERE
      codBase = p_codBase
      AND codCategoriaBase = p_codCategoriaBase
      AND codSubCategoria = p_nuevaSubCategoria;

    -- 3️⃣ obtener nuevo código
    SELECT
            ultimoCodRecurso
            INTO v_newCodRecurso
    FROM
            recursos_contadores
    WHERE
            codBase = p_codBase
            AND codCategoriaBase = p_codCategoriaBase
            AND codSubCategoria = p_nuevaSubCategoria;

    -- 4️⃣ actualizar recurso
    UPDATE
    recursos
    SET
            codCategoriaBase = p_codCategoriaBase,
            codSubCategoria = p_nuevaSubCategoria,
            codRecurso = v_newCodRecurso
    WHERE
      codBase = p_codBase
      AND idUnico = p_idUnicoRecurso;

    -- 5️⃣ generar codRecursoCompleto
    SET v_codRecursoCompleto =
    CONCAT(
      p_codCategoriaBase,
      '-',
      p_nuevaSubCategoria,
      '-',
      v_newCodRecurso);

    -- 6️⃣ actualizar apus_items
    UPDATE
    apus_items
    SET
            codCategoria = p_codCategoriaBase,
            codSubCategoria = p_nuevaSubCategoria,
            codRecurso = v_newCodRecurso,
            codRecursoCompleto = v_codRecursoCompleto
    WHERE
      codBase = p_codBase
      AND idUnicoRecurso = p_idUnicoRecurso;

    COMMIT;
  END
  $$

DELIMITER ;

