DELIMITER $$

--
-- Create procedure `genera_PresupuestosRecursos`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS genera_PresupuestosRecursos
  (
    IN icodbase VARCHAR(255),
    IN icodPresupuesto VARCHAR(255),
    IN irevision VARCHAR(255)
  )
  BEGIN
    bloque1:
    BEGIN
      DECLARE done INTEGER;
      DECLARE v_presupuestosItemsID INTEGER;
      DECLARE v_codAPU VARCHAR(250);
      DECLARE cursor1 CURSOR FOR
        SELECT
                pi.id
        FROM
                presupuestos_items pi
        WHERE
                pi.codBase = icodbase
                AND pi.codPresupuesto = icodPresupuesto
                AND pi.revision = irevision
                AND pi.codapu IS NOT NULL;
      DECLARE CONTINUE HANDLER FOR NOT FOUND
      SET done = TRUE;
      OPEN cursor1;
      SET done := FALSE;
      LOOP1:
      LOOP
        FETCH cursor1 INTO v_presupuestosItemsID;
        IF done
        THEN
          LEAVE loop1;
        END IF;
        SELECT
                pi2.codAPU
                INTO v_codAPU
        FROM
                presupuestos_items pi2
        WHERE
                pi2.id = v_presupuestosItemsID;
        bloque2:
        BEGIN
          DECLARE done2 INTEGER;
          DECLARE v_entrar INTEGER;
          DECLARE v_idunicorecurso VARCHAR(50);
          DECLARE cursor2 CURSOR FOR
            SELECT
                    ai.idUnicoRecurso
            FROM
                    apus_items ai
            WHERE
                    ai.codBase = icodbase
                    AND ai.CodAPU = v_codAPU;
          DECLARE CONTINUE HANDLER FOR NOT FOUND SET done2 = TRUE;
          SET done2 := FALSE;
          OPEN cursor2;
          loop2:
          LOOP
            FETCH cursor2 INTO v_idunicorecurso;
            IF done2
            THEN
              LEAVE loop2;
            END IF;
            SELECT
                    COUNT(*)
                    INTO v_entrar
            FROM
                    presupuestos_recursos pr
            WHERE
                    pr.codBase = icodbase
                    AND pr.codPresupuesto = icodPresupuesto
                    AND pr.revision = irevision
                    AND pr.idUnicoRecurso = v_idunicorecurso;
            IF v_entrar = 0
            THEN
              INSERT INTO presupuestos_recursos
                    (
                      codBase,
                      codPresupuesto,
                      revision,
                      CodAPU,
                      CodCategoria,
                      codSubCategoria,
                      idUnicoRecurso,
                      codRecurso,
                      codRecursoCompleto,
                      Descripcion,
                      Unidad,
                      Precio,
                      moneda,
                      CantidadUnidad,
                      Rendimiento,
                      Total,
                      porcentaje,
                      codCPC,
                      tipoCPC,
                      porcentajeCPC,
                      termino
                    )
                  SELECT
                          icodbase,
                          icodPresupuesto,
                          irevision,
                          v_codAPU,
                          ai2.CodCategoria,
                          ai2.codSubCategoria,
                          ai2.idUnicoRecurso,
                          ai2.codRecurso,
                          ai2.codRecursoCompleto,
                          ai2.Descripcion,
                          ai2.Unidad,
                          ai2.Precio,
                          ai2.moneda,
                          ai2.CantidadUnidad,
                          ai2.Rendimiento,
                          ai2.Total,
                          ai2.porcentaje,
                          ai2.codcpc,
                          ai2.TipoCPC,
                          ai2.porcentajeCPC,
                          ai2.termino
                  FROM
                          apus_items ai2
                  WHERE
                          ai2.codbase = icodbase
                          AND ai2.CodAPU = v_codAPU
                          AND ai2.idUnicoRecurso = v_idunicorecurso;
            END IF;
          END LOOP loop2;
        END bloque2;
      END LOOP loop1;
    END bloque1;
  END
  $$

DELIMITER ;

