DELIMITER $$

--
-- Create procedure `exportar_Presupuestos_EDT`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS exportar_Presupuestos_EDT
  (
    IN iCodBase VARCHAR(255),
    IN iCodPresupuesto VARCHAR(255),
    IN iRevision INT,
    IN id_exports VARCHAR(255)
  )
  BEGIN
    DECLARE done INTEGER;
    DECLARE v_id INTEGER;
    DECLARE cur1 CURSOR FOR
      SELECT
              pe.id
      FROM
              presupuestos_edt pe
      WHERE
              pe.codBase = iCodBase
              AND pe.codPresupuesto = iCodPresupuesto
              AND pe.revision = iRevision;
    DECLARE CONTINUE HANDLER FOR NOT FOUND
    SET done = TRUE;
    /* ------------ INICIO ---------- -- */
    SET done := FALSE;
    OPEN cur1;
    loop_cur1:
    LOOP
      FETCH cur1 INTO v_id;
      IF done
      THEN
        LEAVE loop_cur1;
      END IF;

      INSERT INTO presupuestos_edt_exports
            (
              codBase,
              codPresupuesto,
              Revision,
              CodEDT,
              Descripcion,
              Responsable,
              Definicion,
              codUnicoItemPresupuesto,
              id_exports
            )
          SELECT
                  codBase,
                  codPresupuesto,
                  Revision,
                  CodEDT,
                  Descripcion,
                  Responsable,
                  Definicion,
                  codUnicoItemPresupuesto,
                  id_exports
          FROM
                  presupuestos_edt
          WHERE
                  id = v_id;

    END LOOP;
    CLOSE cur1;
  END
  $$

--
-- Create procedure `Exportar_Presupuestos`
