DELIMITER $$

--
-- Create procedure `crearAPUUnico`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS crearAPUUnico
  (
    IN p_codCategoriaAPU VARCHAR(50),
    IN p_descripcion VARCHAR(255),
    IN p_unidad VARCHAR(50),
    IN p_codBase VARCHAR(255)
  )
  BEGIN
    DECLARE v_moneda VARCHAR(20);
    DECLARE v_codAPU CHAR(50);
    DECLARE v_exists INT;
    DECLARE v_categoriaAPU VARCHAR(255);
    DECLARE v_codRecursoAPU INT;
    DECLARE v_lock_key VARCHAR(255);
    DECLARE v_lock_status INT;
    DECLARE v_unidad_normalizada VARCHAR(50);

    /* -----------------------------------------------------------
       1. Obtener moneda desde BASES
       ----------------------------------------------------------- */
    SELECT
            moneda
            INTO v_moneda
    FROM
            giproylocal.bases
    WHERE
            codBase = p_codBase
    LIMIT 1;

    /* -----------------------------------------------------------
       2. Obtener descripción de la categoría APU
       ----------------------------------------------------------- */
    SELECT
            descripcion
            INTO v_categoriaAPU
    FROM
            categoriaapus
    WHERE
            codBase = p_codBase
            AND categoria_base = 6
            AND ciu = p_codCategoriaAPU
    LIMIT 1;

    /* -----------------------------------------------------------
       3. Normalizar unidad según tabla UNIDADES (subcategoria = 6)
          - Case-insensitive
          - Si no existe => 'u'
       ----------------------------------------------------------- */
    SELECT
            u.descripcion
            INTO v_unidad_normalizada
    FROM
            unidades u
    WHERE
            u.subcategoria = 6
            AND LOWER(
              u.descripcion) = LOWER(
              p_unidad)
    LIMIT 1;

    IF v_unidad_normalizada IS NULL
    THEN
      SET v_unidad_normalizada = 'u';
    END IF;

    /* -----------------------------------------------------------
       4. Verificar si ya existe APU con misma descripción + unidad
       ----------------------------------------------------------- */
    SELECT
            COUNT(*)
            INTO v_exists
    FROM
            apus
    WHERE
            codBase = p_codBase
            AND LOWER(
              Descripcion) = LOWER(
              p_descripcion)
            AND Unidad = v_unidad_normalizada;

    /* -----------------------------------------------------------
       5. Crear APU si no existe
       ----------------------------------------------------------- */
    IF v_exists = 0
    THEN

      /* Clave de LOCK por base + categoría */
      SET v_lock_key = CONCAT(
        'lock_seq_',
        p_codBase,
        '_',
        p_codCategoriaAPU);

      /* Obtener LOCK (timeout 5s) */
      SELECT
              GET_LOCK(
                v_lock_key,
                5)
              INTO v_lock_status;

      IF v_lock_status = 1
      THEN

        /* Asegurar fila de secuencia */
        INSERT INTO apu_secuencias
              (
                codBase,
                codCategoriaAPU,
                ultimo_codRecursoAPU
              )
        VALUES
            (
              p_codBase, p_codCategoriaAPU, 0
            )
        ON DUPLICATE KEY UPDATE
        ultimo_codRecursoAPU = ultimo_codRecursoAPU;

        /* Incrementar secuencia de forma segura */
        UPDATE
        apu_secuencias
        SET
                ultimo_codRecursoAPU = ultimo_codRecursoAPU + 1
        WHERE
          codBase = p_codBase
          AND codCategoriaAPU = p_codCategoriaAPU;

        SELECT
                ultimo_codRecursoAPU
                INTO v_codRecursoAPU
        FROM
                apu_secuencias
        WHERE
                codBase = p_codBase
                AND codCategoriaAPU = p_codCategoriaAPU;

        /* Generar codAPU único */
        SET v_codAPU = UPPER(
          CONCAT(
            'APUsr',
            UUID()));

        /* Insertar nuevo APU */
        INSERT INTO apus
              (
                CodAPU,
                codCategoriaAPU,
                codRecursoAPU,
                CategoriaAPU,
                Descripcion,
                Unidad,
                Rendimiento,
                RendimientoTodoAnalisis,
                RendimientoTodoEscenario,
                CostoDirectoTotal,
                CostoIndirectoTotal,
                PorcentajeCostoIndirecto,
                PrecioUnitarioTotal,
                moneda,
                codCPC,
                FechaHoraCreacion,
                ultimaModificacion,
                pendienteRevision,
                codBase,
                rendimientoHUnidad,
                nhCuadrillas,
                anidado
              )
        VALUES
            (
              REPLACE(v_codAPU, '-', ''), p_codCategoriaAPU, v_codRecursoAPU, v_categoriaAPU, p_descripcion, v_unidad_normalizada, 'Horas/Unidad', '1', '1', 0, 0, 0, 0, v_moneda, NULL, NOW(), NOW(), '1', p_codBase, '0', '0', '0'
            );

        /* Liberar LOCK */
        DO RELEASE_LOCK(
          v_lock_key);

      ELSE
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'No se pudo obtener el LOCK para generar codRecursoAPU.';
      END IF;
    END IF;
  END
  $$

DELIMITER ;

--
-- Create table `apu_recalculo_queue`
--
CREATE TABLE IF NOT EXISTS apu_recalculo_queue
  (
    codBase VARCHAR(255) NOT NULL,
    codAPU  VARCHAR(255) NOT NULL,
    PRIMARY KEY (codBase, codAPU)
  )
ENGINE = INNODB,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_general_ci,
ROW_FORMAT = DYNAMIC;

--
-- Create index `uq_queue` on table `apu_recalculo_queue`
--
ALTER TABLE apu_recalculo_queue
ADD UNIQUE INDEX uq_queue (codBase, codAPU);

--
-- Create index `uq_recalc` on table `apu_recalculo_queue`
--
ALTER TABLE apu_recalculo_queue
ADD UNIQUE INDEX uq_recalc (codBase, codAPU);

DELIMITER $$

--
-- Create procedure `procesar_recalculo_apus`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS procesar_recalculo_apus
  (
    IN p_codBase VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci
  )
  BEGIN
    DECLARE v_codAPU VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE v_done INT DEFAULT 0;

    DECLARE cur CURSOR FOR
      SELECT
              codAPU
      FROM
              apu_recalculo_queue
      WHERE
              codBase = p_codBase;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      SET @apu_en_recalculo = NULL;
      RESIGNAL;
    END;

    SET @apu_en_recalculo = 1;

    OPEN cur;

    read_loop:
    LOOP
      FETCH cur INTO v_codAPU;

      IF v_done = 1
      THEN
        LEAVE read_loop;
      END IF;

      /* 1) Recalcular el APU actual */
      CALL recalcular_apu(
        p_codBase,
        v_codAPU);

      /* 2) Encolar APUs padres: aquellos que usan el recurso cuyo Especificaciones = 'APU: <hijo>' */
      INSERT IGNORE INTO apu_recalculo_queue
            (
              codBase,
              codAPU
            )
          SELECT
                  ai.codBase,
                  ai.CodAPU
          FROM
                  recursos r
              JOIN
                apus_items ai
                  ON ai.codBase = r.codBase
                    AND ai.idUnicoRecurso = r.idUnico
          WHERE
                  r.codBase = p_codBase
                  AND r.Especificaciones = CONCAT(
                    'APU: ',
                    v_codAPU);

      /* 3) Marcar como procesado */
      DELETE
      FROM
              apu_recalculo_queue
      WHERE
              codBase = p_codBase
              AND codAPU = v_codAPU;
    END LOOP;

    CLOSE cur;

    SET @apu_en_recalculo = NULL;
  END
  $$

--
-- Create procedure `actualizar_recurso_completo`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS actualizar_recurso_completo
  (
    IN p_codBase VARCHAR(255),
    IN p_idUnico VARCHAR(255),
    IN p_precio DECIMAL(18, 6),
    IN p_descripcion VARCHAR(255),
    IN p_unidad VARCHAR(50)
  )
  BEGIN
    DECLARE v_codAPU VARCHAR(255);
    DECLARE done INT DEFAULT 0;

    DECLARE cur_apus CURSOR FOR
      SELECT DISTINCT
              CodAPU
      FROM
              apus_items
      WHERE
              codBase = p_codBase
              AND idUnicoRecurso = p_idUnico;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    /* =====================================
       1) Sincronizar items del recurso
       ===================================== */
    UPDATE
    apus_items
    SET
            Precio = p_precio,
            Descripcion = p_descripcion,
            Unidad = p_unidad,
            Total = p_precio
            * CantidadUnidad
            * IFNULL(
              NULLIF(
                Rendimiento,
                0),
              1)
    WHERE
      codBase = p_codBase
      AND idUnicoRecurso = p_idUnico;

    /* =====================================
       2) Encolar APUs directos afectados
       ===================================== */
    SET done = 0;
    OPEN cur_apus;

    read_loop:
    LOOP
      FETCH cur_apus INTO v_codAPU;
      IF done = 1
      THEN
        LEAVE read_loop;
      END IF;

      INSERT IGNORE INTO apu_recalculo_queue
            (
              codBase,
              codAPU
            )
      VALUES
          (
            p_codBase, v_codAPU
          );

    END LOOP;

    CLOSE cur_apus;

    /* =====================================
       3) Si el recurso representa un APU
          (Especificaciones = 'APU: X')
          también encolar ese APU
       ===================================== */
    INSERT IGNORE INTO apu_recalculo_queue
          (
            codBase,
            codAPU
          )
        SELECT
                codBase,
                TRIM(SUBSTRING(Especificaciones, 6))
        FROM
                recursos
        WHERE
                codBase = p_codBase
                AND idUnico = p_idUnico
                AND Especificaciones LIKE 'APU:%';

  END
  $$

DELIMITER ;

