--
-- Create procedure `actualizaRolProyectoStakes`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS actualizaRolProyectoStakes
  (
    IN icodBase VARCHAR(255),
    IN icodPresupuesto VARCHAR(255),
    IN iRevision VARCHAR(255),
    IN oldDescripcion VARCHAR(255),
    IN newDescripcion VARCHAR(255)
  )
  BEGIN
    UPDATE
    presupuestos_stakeholders ps
    SET
            ps.rolPresupuesto = newDescripcion
    WHERE
      ps.rolPresupuesto = oldDescripcion
      AND ps.codBase = icodBase
      AND ps.codPresupuesto = icodPresupuesto
      AND ps.revision = iRevision;

    UPDATE
    presupuestos_edo pe
    SET
            pe.RolProyecto = newDescripcion
    WHERE
      pe.RolProyecto = oldDescripcion
      AND pe.codBase = icodBase
      AND pe.codPresupuesto = icodPresupuesto
      AND pe.revision = iRevision;
  END
  $$

