DELIMITER $$

--
-- Create procedure `updateApusItemsAnidado`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS updateApusItemsAnidado
  (
    IN icodbase VARCHAR(50),
    IN icodAPU VARCHAR(50),
    IN iCodPresupuesto VARCHAR(50),
    IN iRevision VARCHAR(10)
  )
  BEGIN
    DECLARE var_final INTEGER;
    DECLARE var_codAPU VARCHAR(50);
    DECLARE apuAnidado CURSOR FOR
      SELECT
              CodAPU
      FROM
              apus_items
      WHERE
              codBase = icodBase COLLATE utf8mb4_general_ci
              AND idUnicoRecurso = NombreAnidado(
                iCodAPU);

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET var_final = 1;

    SET @sNombreAnidado = NombreAnidado(
      iCodAPU COLLATE utf8mb4_general_ci);

    SELECT
            @indirectos := datos.indirectos
    FROM
            presupuestos_datosgenerales datos
    WHERE
            datos.codBase = icodBase COLLATE utf8mb4_general_ci
            AND datos.codPresupuesto = iCodPresupuesto COLLATE utf8mb4_general_ci
            AND datos.revision = iRevision COLLATE utf8mb4_general_ci;

    UPDATE
    apus_items itm
LEFT JOIN
  apus apu
    ON (
        apu.codBase = icodBase COLLATE utf8mb4_general_ci
        AND apu.CodAPU = iCodAPU COLLATE utf8mb4_general_ci)
    SET
            itm.Precio = apu.CostoDirectoTotal,
            itm.Total = itm.Precio * itm.CantidadUnidad * itm.Rendimiento
    WHERE
      itm.codBase = icodBase COLLATE utf8mb4_general_ci
      AND itm.idUnicoRecurso = NombreAnidado(
        iCodAPU) COLLATE utf8mb4_general_ci;

    OPEN apuAnidado;

    cursorloop:
    LOOP

      FETCH apuAnidado INTO var_codAPU;
      IF var_final = 1
      THEN
        LEAVE cursorloop;
      END IF;
      SELECT
              var_codAPU
      FROM
              bases;
      /* update de los valores apu ok */
      UPDATE
      apus apu
      SET
              apu.CostoDirectoTotal = (SELECT
                          SUM(itm.PTotal)
                  FROM
                          apus_items itm
                  WHERE
                          itm.CodAPU = apu.CodAPU
                          AND itm.codBase = apu.codBase),
              apu.CostoIndirectoTotal = Porcentaje(
                apu.CostoDirectoTotal,
                @indirectos),
              apu.PrecioUnitarioTotal = pu.CostoDirectoTotal + pu.CostoIndirectoTotal
      WHERE
        apu.CodAPU = var_codAPU
        AND apu.codBase = icodBase COLLATE utf8mb4_general_ci;

      /* update presupuesto items  seguir haciendo traza */
      UPDATE
      presupuestos_items Pitems
  LEFT JOIN
    apus apuR
      ON (
          apuR.codBase = icodBase COLLATE utf8mb4_general_ci
          AND apuR.CodAPU = var_codAPU)
      SET
              Pitems.PUnitario := Porcentaje(
                apuR.CostoDirectoTotal,
                @indirectos),
              Pitems.PTotal = pitems.PUnitario * pitems.cantidad
      WHERE
        Pitems.codBase = icodbase COLLATE utf8mb4_general_ci
        AND Pitems.codAPU = var_codAPU
        AND Pitems.codPresupuesto = icodPresupuesto COLLATE utf8mb4_general_ci
        AND Pitems.revision = iRevision COLLATE utf8mb4_general_ci;

      /* Update Recursos */
      UPDATE
      recursos r
  LEFT JOIN
    apus apuR
      ON (apuR.codBase = pitems.codBase
          AND apuR.CodAPU = var_codAPU)
      SET
              precio = apuR.CostoDirectoTotal,
              preciolocal = apuR.CostoDirectoTotal
      WHERE
        r.codBase = icodbase COLLATE utf8mb4_general_ci
        AND r.Especificaciones = NombreAnidado(
          icodAPU COLLATE utf8mb4_general_ci);

    END LOOP cursorloop;
    CLOSE apuAnidado;
  END
  $$

--
-- Create procedure `sp_clonar_base`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS sp_clonar_base
  (
    IN p_basePadre VARCHAR(50),
    IN p_nuevaBase VARCHAR(50),
    IN p_presupuesto VARCHAR(50),
    IN p_nombreBase VARCHAR(255),
    IN p_descripcion TEXT
  )
  BEGIN
    DECLARE vExiste INT DEFAULT 0;

    /* =====================================================
       HANDLER: devuelve error real
       ===================================================== */
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
      ROLLBACK;
      SET foreign_key_checks = 1;
      SET @CLONANDO_BASE = NULL;
      RESIGNAL;
    END;

    /* =====================================================
       Validaciones
       ===================================================== */

    /* Base padre debe existir */
    SELECT
            COUNT(*)
            INTO vExiste
    FROM
            bases
    WHERE
            codBase = p_basePadre;

    IF vExiste = 0
    THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Base padre no existe';
    END IF;

    /* Nueva base no debe existir */
    SELECT
            COUNT(*)
            INTO vExiste
    FROM
            bases
    WHERE
            codBase = p_nuevaBase;

    IF vExiste > 0
    THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'La nueva base ya existe';
    END IF;

    /* Ya existe base para el presupuesto */
    SELECT
            COUNT(*)
            INTO vExiste
    FROM
            bases
    WHERE
            presupuestoAsignado = p_presupuesto;

    IF vExiste > 0
    THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Ya existe una base para este presupuesto';
    END IF;

    /* =====================================================
       Inicio proceso
       ===================================================== */
    START TRANSACTION;

    SET @CLONANDO_BASE = 1;
    SET foreign_key_checks = 0;

    /* =====================================================
       BASE
       ===================================================== */
    INSERT INTO bases
          (
            codBase,
            nombre,
            descripcion,
            indirectos,
            TRendimiento,
            UTiempo,
            SeguridadIndustrial,
            Observaciones,
            FechaHoraCreacion,
            FechaHoraModificacion,
            pais,
            cambioAplicado,
            sincronizada,
            moneda,
            basesPadres,
            presupuestoAsignado
          )
        SELECT
                p_nuevaBase,
                p_nombreBase,
                p_descripcion,
                indirectos,
                TRendimiento,
                UTiempo,
                SeguridadIndustrial,
                Observaciones,
                FechaHoraCreacion,
                NOW(),
                pais,
                cambioAplicado,
                sincronizada,
                moneda,
                p_basePadre,
                p_presupuesto
        FROM
                bases
        WHERE
                codBase = p_basePadre;

    /* =====================================================
       CATEGORIAS
       ===================================================== */
    INSERT INTO categoriaapus
          (
            Categoria_base,
            Ciu,
            codBase,
            NombreBase,
            Descripcion,
            codExterno,
            comentarios,
            Usado,
            sincronizada,
            origen,
            fechaCreacion
          )
        SELECT
                Categoria_base,
                Ciu,
                p_nuevaBase,
                p_nombreBase,
                Descripcion,
                codExterno,
                comentarios,
                Usado,
                sincronizada,
                origen,
                fechaCreacion
        FROM
                categoriaapus
        WHERE
                codBase = p_basePadre;

    /* =====================================================
       RECURSOS
       ===================================================== */
    INSERT INTO recursos
          (
            idUnico,
            codBase,
            codRecurso,
            codRecursoCompleto,
            codCategoriaBase,
            codSubCategoria,
            Descripcion,
            unidad,
            precio,
            preciolocal,
            precioBase,
            moneda,
            termino,
            codAlternativo,
            codCPC,
            tipoCPC,
            porcentajeCPC,
            Especificaciones,
            Especificaciones2,
            fechaHoraCreacion,
            ultimaModificacion,
            codDistribuidor,
            distribuidor
          )
        SELECT
                idUnico,
                p_nuevaBase,
                codRecurso,
                codRecursoCompleto,
                codCategoriaBase,
                codSubCategoria,
                Descripcion,
                unidad,
                precio,
                preciolocal,
                precioBase,
                moneda,
                termino,
                codAlternativo,
                codCPC,
                tipoCPC,
                porcentajeCPC,
                Especificaciones,
                Especificaciones2,
                fechaHoraCreacion,
                NOW(),
                codDistribuidor,
                distribuidor
        FROM
                recursos
        WHERE
                codBase = p_basePadre;

    /* =====================================================
       APUS
       ===================================================== */
    INSERT INTO apus
          (
            codBase,
            codCategoriaAPU,
            codRecursoAPU,
            CategoriaAPU,
            codAPU,
            Descripcion,
            Unidad,
            Rendimiento,
            RendimientoTodoAnalisis,
            RendimientoTodoEscenario,
            FechaHoraCreacion,
            CostoDirectoTotal,
            CostoIndirectoTotal,
            PorcentajeCostoIndirecto,
            PrecioUnitarioTotal,
            moneda,
            codCPC,
            ultimaModificacion,
            pendienteRevision,
            rendimientoHUnidad,
            nhCuadrillas,
            anidado
          )
        SELECT
                p_nuevaBase,
                codCategoriaAPU,
                codRecursoAPU,
                CategoriaAPU,
                codAPU,
                Descripcion,
                Unidad,
                Rendimiento,
                RendimientoTodoAnalisis,
                RendimientoTodoEscenario,
                FechaHoraCreacion,
                CostoDirectoTotal,
                CostoIndirectoTotal,
                PorcentajeCostoIndirecto,
                PrecioUnitarioTotal,
                moneda,
                codCPC,
                NOW(),
                pendienteRevision,
                rendimientoHUnidad,
                nhCuadrillas,
                anidado
        FROM
                apus
        WHERE
                codBase = p_basePadre;

    /* =====================================================
       APUS ITEMS
       ===================================================== */
    INSERT INTO apus_items
          (
            codBase,
            codAPU,
            codCategoria,
            codSubCategoria,
            idUnicoRecurso,
            codRecurso,
            codRecursoCompleto,
            Descripcion,
            Unidad,
            Precio,
            moneda,
            CantidadUnidad,
            Rendimiento,
            Total,
            porcentaje,
            codCPC,
            tipoCPC,
            porcentajeCPC
          )
        SELECT
                p_nuevaBase,
                codAPU,
                codCategoria,
                codSubCategoria,
                idUnicoRecurso,
                codRecurso,
                codRecursoCompleto,
                Descripcion,
                Unidad,
                Precio,
                moneda,
                CantidadUnidad,
                Rendimiento,
                Total,
                porcentaje,
                codCPC,
                tipoCPC,
                porcentajeCPC
        FROM
                apus_items
        WHERE
                codBase = p_basePadre;

    /* =====================================================
       AJUSTES INICIALES DE REPORTES
       ===================================================== */
    INSERT INTO presupuestos_configreportes
          (
            CodBase,
            CodPresupuesto,
            revision,
            RConstitucionProyecto,
            RAnalisisPrecios,
            RCronogramaTrabajo,
            RCronogramaValorado,
            RDesagregacionTecnologica,
            RDesagregacionTecnologicaAPUS,
            REDTDiccionario,
            REDTListado,
            REDTValorada,
            REquipoProyecto,
            RDescomposicionOrganizacion,
            RFormulaPolinomicas,
            RGestionTiempos,
            RPorcentajeIndirectos,
            RPresupuestos,
            RCurvaS
          )
        SELECT
                p_nuevaBase,
                p_presupuesto,
                0,
                RConstitucionProyecto,
                RAnalisisPrecios,
                RCronogramaTrabajo,
                RCronogramaValorado,
                RDesagregacionTecnologica,
                RDesagregacionTecnologicaAPUS,
                REDTDiccionario,
                REDTListado,
                REDTValorada,
                REquipoProyecto,
                RDescomposicionOrganizacion,
                RFormulaPolinomicas,
                RGestionTiempos,
                RPorcentajeIndirectos,
                RPresupuestos,
                RCurvaS
        FROM
                empresas_config
        WHERE
                codUnico = 1;

    /* =====================================================
       Restaurar entorno
       ===================================================== */
    SET foreign_key_checks = 1;
    SET @CLONANDO_BASE = NULL;

    COMMIT;

  END
  $$

--
-- Create procedure `actualizarBaseYRecalcularAPUS`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS actualizarBaseYRecalcularAPUS
  (
    IN p_codBase VARCHAR(255),
    IN p_descripcion TEXT,
    IN p_indirectos DECIMAL(10, 4),
    IN p_seguridadIndustrial BOOLEAN,
    IN p_observaciones TEXT,
    IN p_pais VARCHAR(100),
    IN p_cambioAplicado VARCHAR(50),
    IN p_moneda VARCHAR(20),
    IN p_fechaHora DATETIME
  )
  BEGIN
    DECLARE v_indirectos_actual DECIMAL(10, 4);

    START TRANSACTION;

    -- Bloquear base
    SELECT
            indirectos
            INTO v_indirectos_actual
    FROM
            bases
    WHERE
            codBase = p_codBase
    FOR UPDATE;

    -- Actualizar base
    UPDATE
    bases
    SET
            descripcion = p_descripcion,
            indirectos = p_indirectos,
            seguridadIndustrial = p_seguridadIndustrial,
            observaciones = p_observaciones,
            fechaHoraModificacion = p_fechaHora,
            pais = p_pais,
            cambioAplicado = p_cambioAplicado,
            moneda = p_moneda
    WHERE
      codBase = p_codBase;

    -- Si cambia el porcentaje → recalcular APUS
    IF ABS(
        v_indirectos_actual - p_indirectos) > 0.00001
    THEN

      UPDATE
      apus
      SET
              PorcentajeCostoIndirecto = p_indirectos,
              CostoIndirectoTotal =
              (CostoDirectoTotal * p_indirectos) / 100,
              PrecioUnitarioTotal =
              CostoDirectoTotal +
              ((CostoDirectoTotal * p_indirectos) / 100),
              ultimaModificacion = p_fechaHora
      WHERE
        codBase = p_codBase;

    END IF;

    COMMIT;
  END
  $$

DELIMITER ;

