DELIMITER $$

--
-- Create procedure `exportar_Presupuestos_TratamientoAnidados`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE IF NOT EXISTS exportar_Presupuestos_TratamientoAnidados
  (
    IN iCodBase VARCHAR(255),
    IN id_exports VARCHAR(255)
  )
  BEGIN
    DECLARE done INTEGER;
    DECLARE v_id INTEGER;
    DECLARE v_CodAPU VARCHAR(255);
    DECLARE v_existe INTEGER;

    DECLARE cur1 CURSOR FOR
      SELECT
              ae.id
      FROM
              apus_exports ae
      WHERE
              ae.codBase = iCodBase
              AND ae.anidado = 1
              AND ae.id_exports = id_exports;
    DECLARE CONTINUE HANDLER FOR NOT FOUND
    SET done = TRUE;
    /* ------------ INICIO ---------- -- */
    SET done := FALSE;
    OPEN cur1;
    loop_cur1:
    LOOP
      FETCH cur1 INTO v_id, v_CodAPU;
      IF done
      THEN
        LEAVE loop_cur1;
      END IF;
    END LOOP;
    CLOSE cur1;
  END
  $$

--
-- Create function `presupuesto_daNewCodItems`
--
CREATE
DEFINER = 'root'@'localhost'
FUNCTION IF NOT EXISTS presupuesto_daNewCodItems
  (
    oldCodItems VARCHAR(255)
  )
RETURNS CHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_general_ci
NO SQL
  BEGIN
    DECLARE I INTEGER;
    DECLARE J INTEGER;
    DECLARE parte1 CHAR(50);

    SET parte1 := REVERSE(
      oldCodItems);
    SET I := LOCATE(
      '.',
      parte1);
    SET J := SUBSTR(parte1, 1, I - 1);
    SET parte1 := SUBSTR(parte1, I, LENGTH(
      parte1));
    SET J := J + 1;
    SET parte1 := CONCAT(
      J,
      parte1);
    SET parte1 := REVERSE(
      parte1);

    RETURN parte1;
  END
  $$

DELIMITER ;

