--
-- Create trigger `t_AU_Presupuestos_items_trabajo`
--
CREATE
DEFINER = 'root'@'localhost'
TRIGGER IF NOT EXISTS t_AU_Presupuestos_items_trabajo
AFTER UPDATE
ON presupuestos_notas
FOR EACH ROW
BEGIN
UPDATE
presupuestos_items_trabajo pit
SET
        pit.notas = TRUE
WHERE
  pit.codBase = new.codBase
  AND pit.codPresupuesto = new.codPresupuesto
  AND pit.revision = new.Revision
  AND pit.codUnicoItems = new.codUnicoItems;
END
$$

