--
-- Create trigger `trg_recursos_before_delete_cleanup_apus`
--
CREATE
DEFINER = 'root'@'localhost'
TRIGGER IF NOT EXISTS trg_recursos_before_delete_cleanup_apus
BEFORE DELETE
ON recursos
FOR EACH ROW
BEGIN

DECLARE v_precision INT DEFAULT 4;

/* =====================================
   Si estamos clonando → NO HACER NADA
   ===================================== */
IF IFNULL(
    @CLONANDO_BASE,
    0) = 0
THEN

  /* 1) Recalcular APUs afectados */
  UPDATE
  apus a
JOIN
(   SELECT
            ai_all.codBase,
            ai_all.CodAPU,
            SUM(
            CASE
                    WHEN ai_all.codBase = OLD.codBase
                      AND ai_all.idUnicoRecurso = OLD.idUnico
                      THEN
                      0
                    ELSE
                    IFNULL(
                      ai_all.Total,
                      0)
            END
            ) AS sumTotal
    FROM
            apus_items ai_all
    WHERE
            ai_all.codBase = OLD.codBase
            AND ai_all.CodAPU IN (SELECT DISTINCT
                        ai3.CodAPU
                FROM
                        apus_items ai3
                WHERE
                        ai3.codBase = OLD.codBase
                        AND ai3.idUnicoRecurso = OLD.idUnico)
    GROUP BY
            ai_all.codBase,
            ai_all.CodAPU) x
  ON x.codBase = a.codBase
    AND x.CodAPU = a.CodAPU
  SET
          a.CostoDirectoTotal = x.sumTotal,
          a.CostoIndirectoTotal = Redondea(
            Porcentaje(
              x.sumTotal,
              IFNULL(
                a.PorcentajeCostoIndirecto,
                0)),
            v_precision),
          a.PrecioUnitarioTotal =
          x.sumTotal +
          Redondea(
            Porcentaje(
              x.sumTotal,
              IFNULL(
                a.PorcentajeCostoIndirecto,
                0)),
            v_precision),
          a.ultimaModificacion = NOW();

  /* 2) Borrar items */
  DELETE
  FROM
          apus_items
  WHERE
          codBase = OLD.codBase
          AND idUnicoRecurso = OLD.idUnico;

END IF;

END
$$

--
-- Create trigger `trg_apus_bd_no_borrar_si_integrado`
--
CREATE
DEFINER = 'root'@'localhost'
TRIGGER IF NOT EXISTS trg_apus_bd_no_borrar_si_integrado
BEFORE DELETE
ON apus
FOR EACH ROW
BEGIN
DECLARE vTienePadres INT DEFAULT 0;
DECLARE vUsadoPresupuesto INT DEFAULT 0;
DECLARE vUsadoTanteoRecursos INT DEFAULT 0;

/* Cadena ascendente: OLD.CodAPU -> APUs que lo usan como recurso -> ... */
WITH RECURSIVE chain
AS (   SELECT
               OLD.CodAPU AS CodAPU,
               0 AS depth
       UNION ALL
       SELECT
               ai.CodAPU AS CodAPU,
               c.depth + 1 AS depth
       FROM
               chain c
           JOIN
             recursos r
                 ON r.codBase = OLD.codBase
                 AND r.Especificaciones = CONCAT(
                   'APU: ',
                   c.CodAPU)
           JOIN
             apus_items ai
                 ON ai.codBase = OLD.codBase
                 AND ai.idUnicoRecurso = r.idUnico
       WHERE
               c.depth < 50)
SELECT
        /* si hay depth>0 => está anidado en otro APU (directo o indirecto) */
        SUM(CASE
                WHEN depth > 0
                  THEN
                  1
                ELSE
                0
        END)
        INTO vTienePadres
FROM
        (   SELECT
                    CodAPU,
                    MIN(depth) AS depth
            FROM
                    chain
            GROUP BY
                    CodAPU) x;

IF vTienePadres > 0
THEN
  SIGNAL SQLSTATE '45000'
  SET MESSAGE_TEXT = 'INTEGRADO: USADO_COMO_RECURSO_EN_OTRO_APU';
END IF;

/* Uso en presupuesto/tanteo apus (si cualquiera de la cadena está en presupuesto => bloquear) */
WITH RECURSIVE chain2
AS (   SELECT
               OLD.CodAPU AS CodAPU
       UNION
       SELECT
               ai.CodAPU
       FROM
               chain2 c
           JOIN
             recursos r
                 ON r.codBase = OLD.codBase
                 AND r.Especificaciones = CONCAT(
                   'APU: ',
                   c.CodAPU)
           JOIN
             apus_items ai
                 ON ai.codBase = OLD.codBase
                 AND ai.idUnicoRecurso = r.idUnico)
SELECT
        ((  SELECT
                    COUNT(*)
            FROM
                    presupuestos_items
            WHERE
                    codBase = OLD.codBase
                    AND codAPU IN (SELECT
                                CodAPU
                        FROM
                                chain2))
        + ( SELECT
                    COUNT(*)
            FROM
                    presupuestos_items_trabajo
            WHERE
                    codBase = OLD.codBase
                    AND codAPU IN (SELECT
                                CodAPU
                        FROM
                                chain2))
        + ( SELECT
                    COUNT(*)
            FROM
                    presupuestos_items_trabajo_edt
            WHERE
                    codBase = OLD.codBase
                    AND codAPU IN (SELECT
                                CodAPU
                        FROM
                                chain2))
        + ( SELECT
                    COUNT(*)
            FROM
                    presupuestos_tanteo_apus
            WHERE
                    codBase = OLD.codBase
                    AND CodAPU IN (SELECT
                                CodAPU
                        FROM
                                chain2))
        + ( SELECT
                    COUNT(*)
            FROM
                    presupuestos_tanteo_apus_bkp
            WHERE
                    codBase = OLD.codBase
                    AND CodAPU IN (SELECT
                                CodAPU
                        FROM
                                chain2))
        )
        INTO vUsadoPresupuesto;

IF vUsadoPresupuesto > 0
THEN
  SIGNAL SQLSTATE '45000'
  SET MESSAGE_TEXT = 'INTEGRADO: USO_EN_PRESUPUESTO_CADENA_APU';
END IF;

/* Uso en tanteo de recursos:
   - Por CodAPU en la cadena (tus tablas lo tienen)
   - Y por idUnicoRecurso de recursos "APU: <CodAPU>" (refuerzo extra)
*/
WITH RECURSIVE chain3
AS (   SELECT
               OLD.CodAPU AS CodAPU
       UNION
       SELECT
               ai.CodAPU
       FROM
               chain3 c
           JOIN
             recursos r
                 ON r.codBase = OLD.codBase
                 AND r.Especificaciones = CONCAT(
                   'APU: ',
                   c.CodAPU)
           JOIN
             apus_items ai
                 ON ai.codBase = OLD.codBase
                 AND ai.idUnicoRecurso = r.idUnico)
,
apu_recursos
AS (   SELECT
               r.idUnico
       FROM
               recursos r
       WHERE
               r.codBase = OLD.codBase
               AND r.Especificaciones IN (SELECT
                           CONCAT(
                             'APU: ',
                             CodAPU)
                   FROM
                           chain3))
SELECT
        ((  SELECT
                    COUNT(*)
            FROM
                    presupuestos_tanteo_recursos
            WHERE
                    codBase = OLD.codBase
                    AND (
                            CodAPU IN (SELECT
                                        CodAPU
                                FROM
                                        chain3)
                            OR idUnicoRecurso IN (SELECT
                                        idUnico
                                FROM
                                        apu_recursos)
                    ))
        + ( SELECT
                    COUNT(*)
            FROM
                    presupuestos_tanteo_recursos_bkp
            WHERE
                    codBase = OLD.codBase
                    AND (
                            CodAPU IN (SELECT
                                        CodAPU
                                FROM
                                        chain3)
                            OR idUnicoRecurso IN (SELECT
                                        idUnico
                                FROM
                                        apu_recursos)
                    ))
        )
        INTO vUsadoTanteoRecursos;

IF vUsadoTanteoRecursos > 0
THEN
  SIGNAL SQLSTATE '45000'
  SET MESSAGE_TEXT = 'INTEGRADO: USO_TANTEO_RECURSOS_CADENA_APU';
END IF;

END
$$

--
-- Create trigger `apus_bu_proteger_codrecursoapu`
--
CREATE
DEFINER = 'root'@'localhost'
TRIGGER IF NOT EXISTS apus_bu_proteger_codrecursoapu
BEFORE UPDATE
ON apus
FOR EACH ROW
BEGIN
-- Si cambian codBase o codCategoriaAPU o codRecursoAPU, valida que no choque
IF (NEW.codBase <> OLD.codBase)
  OR
  (NEW.codCategoriaAPU <> OLD.codCategoriaAPU)
  OR
  (NEW.codRecursoAPU <> OLD.codRecursoAPU)
THEN

  IF EXISTS (SELECT
                1
        FROM
                apus a
        WHERE
                a.codBase = NEW.codBase
                AND a.codCategoriaAPU = NEW.codCategoriaAPU
                AND a.codRecursoAPU = NEW.codRecursoAPU
                AND a.CodAPU <> OLD.CodAPU
        LIMIT 1)
  THEN
    SIGNAL SQLSTATE '45000'
    SET MESSAGE_TEXT = 'INTEGRIDAD: codRecursoAPU duplicado para codBase/codCategoriaAPU';
  END IF;
END IF;
END
$$

--
-- Create trigger `ActualizarItemsPresupuesto`
--
CREATE
DEFINER = 'root'@'localhost'
TRIGGER IF NOT EXISTS ActualizarItemsPresupuesto
AFTER UPDATE
ON presupuestos_datosgenerales
FOR EACH ROW
BEGIN
IF (old.indirectos) <> (new.indirectos)
THEN
  UPDATE
  presupuestos_items pItems   /* Lineas Presupuestos */
LEFT JOIN
apus_items item
  ON (item.codBase = Pitems.codBase
      AND item.CodAPU = Pitems.CodAPU)
  SET
          pItems.PUnitario = item.Precio + Porcentaje(
            item.Precio,
            new.indirectos),
          pItems.Ptotal := pItems.PUnitario * pItems.cantidad
  WHERE
    pitems.codBase = new.codBase
    AND PItems.codPresupuesto = new.codPresupuesto
    AND Pitems.Revision = new.Revision;
  UPDATE
  presupuestos_tanteo_apus tanteo   /* Tanteo Items */
  SET
          tanteo.PorcentajeCostoIndirecto := new.indirectos,
          tanteo.CostoIndirectoTotal := Porcentaje(
            tanteo.CostoDirectoTotal,
            new.indirectos),
          tanteo.PrecioUnitarioTotal := tanteo.CostoIndirectoTotal + tanteo.CostoIndirectoTotal
  WHERE
    tanteo.codBase = new.codBase
    AND tanteo.codPresupuesto = new.codPresupuesto
    AND tanteo.Revision = new.Revision;

END IF;
END
$$

